export type ViewType = 'dashboard' | 'inventory' | 'sales' | 'clients' | 'credit' | 'expenses' | 'settings';

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React, { useState, useEffect, useMemo } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  ShoppingCart, 
  Users, 
  CreditCard, 
  Settings, 
  LogOut, 
  Menu, 
  X,
  TrendingDown,
  RefreshCw,
  Store
} from 'lucide-react';
import { ViewType, UserProfile, Product, Client, Sale, Expense } from './types';
import DashboardView from './views/DashboardView';
import InventoryView from './views/InventoryView';
import SalesView from './views/SalesView';
import ClientsView from './views/ClientsView';
import CreditView from './views/CreditView';
import ExpensesView from './views/ExpensesView';
import SettingsView from './views/SettingsView';
import AuthView from './views/AuthView';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<UserProfile | null>(null);
  const [currentView, setCurrentView] = useState<ViewType>('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [syncing, setSyncing] = useState(false);

  // Initialize data from local storage to simulate Supabase persistency
  useEffect(() => {
    const savedUser = localStorage.getItem('cr_user');
    if (savedUser) {
      setCurrentUser(JSON.parse(savedUser));
    }
  }, []);

  const handleLogin = (user: UserProfile) => {
    setCurrentUser(user);
    localStorage.setItem('cr_user', JSON.stringify(user));
  };

  const handleLogout = () => {
    setCurrentUser(null);
    localStorage.removeItem('cr_user');
  };

  const handleSync = async () => {
    if (!currentUser?.sheetsUrl) {
       alert('Configura tu URL de Google Sheets en Ajustes para sincronizar.');
       return;
    }
    setSyncing(true);
    // Simulate API call to Google Apps Script
    await new Promise(resolve => setTimeout(resolve, 2000));
    setSyncing(false);
    alert('Sincronización con Google Sheets completada exitosamente.');
  };

  if (!currentUser) {
    return <AuthView onLogin={handleLogin} />;
  }

  const renderView = () => {
    switch (currentView) {
      case 'dashboard': return <DashboardView />;
      case 'inventory': return <InventoryView />;
      case 'sales': return <SalesView />;
      case 'clients': return <ClientsView />;
      case 'credit': return <CreditView />;
      case 'expenses': return <ExpensesView />;
      case 'settings': return <SettingsView user={currentUser} onUpdateUser={handleLogin} />;
      default: return <DashboardView />;
    }
  };

  const NavItem = ({ view, icon: Icon, label }: { view: ViewType, icon: any, label: string }) => (
    <button
      onClick={() => { setCurrentView(view); setIsSidebarOpen(false); }}
      className={`w-full flex items-center space-x-3 px-4 py-3 rounded-lg transition-colors ${
        currentView === view 
          ? 'bg-blue-600 text-white shadow-lg' 
          : 'text-slate-600 hover:bg-slate-100'
      }`}
    >
      <Icon size={20} />
      <span className="font-medium">{label}</span>
    </button>
  );

  return (
    <div className="flex h-screen bg-slate-50 overflow-hidden">
      {/* Sidebar Overlay */}
      {isSidebarOpen && (
        <div 
          className="fixed inset-0 bg-black/50 z-40 lg:hidden" 
          onClick={() => setIsSidebarOpen(false)}
        />
      )}

      {/* Sidebar */}
      <aside className={`
        fixed lg:static inset-y-0 left-0 w-64 bg-white border-r border-slate-200 z-50 transform transition-transform duration-300 lg:translate-x-0
        ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}
      `}>
        <div className="flex flex-col h-full p-4">
          <div className="flex items-center space-x-2 px-2 mb-8">
            <div className="bg-blue-600 p-2 rounded-lg text-white">
              <Store size={24} />
            </div>
            <h1 className="text-xl font-bold tracking-tight text-slate-800">Caja Pro</h1>
          </div>

          <nav className="flex-1 space-y-1">
            <NavItem view="dashboard" icon={LayoutDashboard} label="Dashboard" />
            <NavItem view="inventory" icon={Package} label="Inventario" />
            <NavItem view="sales" icon={ShoppingCart} label="Ventas" />
            <NavItem view="clients" icon={Users} label="Clientes" />
            <NavItem view="credit" icon={CreditCard} label="Crédito & Deudas" />
            <NavItem view="expenses" icon={TrendingDown} label="Egresos" />
            <div className="my-4 border-t border-slate-100" />
            <NavItem view="settings" icon={Settings} label="Configuración" />
          </nav>

          <div className="pt-4 border-t border-slate-100">
            <div className="bg-blue-50 rounded-xl p-4 mb-4">
              <p className="text-xs text-blue-600 font-semibold uppercase mb-1">Tu Negocio</p>
              <p className="text-sm font-bold text-slate-800 truncate">{currentUser.businessName}</p>
            </div>
            <button 
              onClick={handleLogout}
              className="w-full flex items-center space-x-3 px-4 py-3 rounded-lg text-red-600 hover:bg-red-50 transition-colors"
            >
              <LogOut size={20} />
              <span className="font-medium">Cerrar Sesión</span>
            </button>
          </div>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col h-full overflow-hidden">
        {/* Header */}
        <header className="h-16 bg-white border-b border-slate-200 flex items-center justify-between px-4 lg:px-8 flex-shrink-0">
          <div className="flex items-center space-x-4">
            <button 
              onClick={() => setIsSidebarOpen(true)}
              className="lg:hidden p-2 text-slate-600 hover:bg-slate-100 rounded-md"
            >
              <Menu size={24} />
            </button>
            <h2 className="text-lg font-bold text-slate-800 lg:text-xl">
              {currentUser.businessName}
            </h2>
          </div>

          <div className="flex items-center space-x-3">
             <button 
                onClick={handleSync}
                disabled={syncing}
                className="flex items-center space-x-2 bg-emerald-50 text-emerald-700 px-3 py-1.5 rounded-full text-sm font-medium hover:bg-emerald-100 transition-colors disabled:opacity-50"
             >
                <RefreshCw size={16} className={syncing ? 'animate-spin' : ''} />
                <span className="hidden sm:inline">Sincronizar Sheets</span>
             </button>
             <div className="w-8 h-8 rounded-full bg-slate-200 flex items-center justify-center text-slate-600 font-bold uppercase">
               {currentUser.businessName.charAt(0)}
             </div>
          </div>
        </header>

        {/* View Container */}
        <div className="flex-1 overflow-y-auto p-4 lg:p-8 bg-slate-50 hide-scrollbar">
          <div className="max-w-6xl mx-auto h-full">
            {renderView()}
          </div>
        </div>
      </main>
    </div>
  );
};

export default App;

import { Product, Client, Sale, Expense, SaleStatus } from '../types';

// Storage Keys
const KEYS = {
  PRODUCTS: 'cr_products',
  CLIENTS: 'cr_clients',
  SALES: 'cr_sales',
  EXPENSES: 'cr_expenses'
};

const get = <T,>(key: string): T[] => {
  const data = localStorage.getItem(key);
  return data ? JSON.parse(data) : [];
};

const save = <T,>(key: string, data: T[]) => {
  localStorage.setItem(key, JSON.stringify(data));
};

export const dbService = {
  // Products
  getProducts: () => get<Product>(KEYS.PRODUCTS),
  saveProduct: (product: Product) => {
    const products = get<Product>(KEYS.PRODUCTS);
    const index = products.findIndex(p => p.id === product.id);
    if (index >= 0) products[index] = product;
    else products.push(product);
    save(KEYS.PRODUCTS, products);
  },
  deleteProduct: (id: string) => {
    save(KEYS.PRODUCTS, get<Product>(KEYS.PRODUCTS).filter(p => p.id !== id));
  },

  // Clients
  getClients: () => get<Client>(KEYS.CLIENTS),
  saveClient: (client: Client) => {
    const clients = get<Client>(KEYS.CLIENTS);
    const index = clients.findIndex(c => c.id === client.id);
    if (index >= 0) clients[index] = client;
    else clients.push(client);
    save(KEYS.CLIENTS, clients);
  },

  // Sales
  getSales: () => get<Sale>(KEYS.SALES),
  createSale: (sale: Sale) => {
    const sales = get<Sale>(KEYS.SALES);
    sales.push(sale);
    save(KEYS.SALES, sales);

    // Update inventory
    const products = get<Product>(KEYS.PRODUCTS);
    sale.items.forEach(item => {
      const p = products.find(prod => prod.id === item.productId);
      if (p) p.stock -= item.quantity;
    });
    save(KEYS.PRODUCTS, products);

    // Update client debt if credit
    if (sale.status === SaleStatus.CREDIT && sale.clientId) {
      const clients = get<Client>(KEYS.CLIENTS);
      const c = clients.find(cl => cl.id === sale.clientId);
      if (c) c.currentDebt += (sale.total - sale.amountPaid);
      save(KEYS.CLIENTS, clients);
    }
  },

  // Expenses
  getExpenses: () => get<Expense>(KEYS.EXPENSES),
  saveExpense: (expense: Expense) => {
    const expenses = get<Expense>(KEYS.EXPENSES);
    expenses.push(expense);
    save(KEYS.EXPENSES, expenses);
  }
};

import React, { useMemo } from 'react';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer, 
  AreaChart, 
  Area 
} from 'recharts';
import { dbService } from '../services/dbService';
import { DollarSign, TrendingUp, TrendingDown, Package, Users, AlertCircle } from 'lucide-react';

const DashboardView: React.FC = () => {
  const sales = dbService.getSales();
  const expenses = dbService.getExpenses();
  const products = dbService.getProducts();
  const clients = dbService.getClients();

  const stats = useMemo(() => {
    const totalRevenue = sales.reduce((acc, s) => acc + s.total, 0);
    const totalExpenses = expenses.reduce((acc, e) => acc + e.amount, 0);
    const lowStockCount = products.filter(p => p.stock <= 5).length;
    const pendingCredits = clients.reduce((acc, c) => acc + c.currentDebt, 0);

    return {
      revenue: totalRevenue,
      expenses: totalExpenses,
      profit: totalRevenue - totalExpenses,
      lowStock: lowStockCount,
      pendingCredits
    };
  }, [sales, expenses, products, clients]);

  const chartData = useMemo(() => {
    // Basic aggregation by date (last 7 days simulation)
    const last7Days = [...Array(7)].map((_, i) => {
      const d = new Date();
      d.setDate(d.getDate() - i);
      return d.toISOString().split('T')[0];
    }).reverse();

    return last7Days.map(date => {
      const daySales = sales.filter(s => s.date.startsWith(date)).reduce((acc, s) => acc + s.total, 0);
      const dayExpenses = expenses.filter(e => e.date.startsWith(date)).reduce((acc, e) => acc + e.amount, 0);
      return {
        name: date.slice(5),
        ventas: daySales,
        gastos: dayExpenses,
        neto: daySales - dayExpenses
      };
    });
  }, [sales, expenses]);

  const StatCard = ({ title, value, icon: Icon, color, trend }: any) => (
    <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 flex items-start justify-between">
      <div>
        <p className="text-sm font-medium text-slate-500 mb-1">{title}</p>
        <h3 className="text-2xl font-bold text-slate-800">${value.toLocaleString()}</h3>
        {trend && <p className={`text-xs mt-2 font-medium ${trend > 0 ? 'text-emerald-600' : 'text-rose-600'}`}>
          {trend > 0 ? '+' : ''}{trend}% vs mes pasado
        </p>}
      </div>
      <div className={`p-3 rounded-xl ${color}`}>
        <Icon size={24} />
      </div>
    </div>
  );

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-slate-800">Resumen de Negocio</h1>
          <p className="text-slate-500">Aquí tienes lo que está pasando hoy.</p>
        </div>
        <div className="flex bg-white p-1 rounded-lg border border-slate-200">
          <button className="px-4 py-1.5 text-sm font-medium bg-slate-100 rounded-md">Semana</button>
          <button className="px-4 py-1.5 text-sm font-medium text-slate-600">Mes</button>
          <button className="px-4 py-1.5 text-sm font-medium text-slate-600">Año</button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <StatCard title="Ingresos Totales" value={stats.revenue} icon={DollarSign} color="bg-blue-50 text-blue-600" />
        <StatCard title="Gastos Totales" value={stats.expenses} icon={TrendingDown} color="bg-rose-50 text-rose-600" />
        <StatCard title="Ingreso Neto" value={stats.profit} icon={TrendingUp} color="bg-emerald-50 text-emerald-600" />
        <StatCard title="Crédito Pendiente" value={stats.pendingCredits} icon={Users} color="bg-amber-50 text-amber-600" />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 bg-white p-6 rounded-2xl border border-slate-100">
          <h3 className="text-lg font-bold mb-6 text-slate-800">Tendencia de Ventas vs Gastos</h3>
          <div className="h-80 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={chartData}>
                <defs>
                  <linearGradient id="colorVentas" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.1}/>
                    <stop offset="95%" stopColor="#3b82f6" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#64748b', fontSize: 12}} dy={10} />
                <YAxis axisLine={false} tickLine={false} tick={{fill: '#64748b', fontSize: 12}} />
                <Tooltip 
                  contentStyle={{borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)'}}
                />
                <Area type="monotone" dataKey="ventas" stroke="#3b82f6" strokeWidth={2} fillOpacity={1} fill="url(#colorVentas)" />
                <Area type="monotone" dataKey="gastos" stroke="#f43f5e" strokeWidth={2} fill="transparent" />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="space-y-4">
          <div className="bg-white p-6 rounded-2xl border border-slate-100">
            <h3 className="text-lg font-bold mb-4 text-slate-800 flex items-center gap-2">
              <AlertCircle className="text-amber-500" size={20} />
              Alertas de Stock
            </h3>
            {stats.lowStock > 0 ? (
              <div className="space-y-3">
                {products.filter(p => p.stock <= 5).slice(0, 4).map(p => (
                  <div key={p.id} className="flex items-center justify-between p-3 bg-amber-50 rounded-xl border border-amber-100">
                    <div>
                      <p className="text-sm font-bold text-slate-800">{p.name}</p>
                      <p className="text-xs text-slate-500">Stock: {p.stock} unidades</p>
                    </div>
                    <button className="text-xs font-bold text-amber-700 bg-amber-200 px-2 py-1 rounded">Reponer</button>
                  </div>
                ))}
                {stats.lowStock > 4 && <p className="text-center text-xs text-slate-400">Y {stats.lowStock - 4} productos más...</p>}
              </div>
            ) : (
              <div className="text-center py-8">
                <Package className="mx-auto text-slate-200 mb-2" size={40} />
                <p className="text-sm text-slate-400">Todo el inventario está al día.</p>
              </div>
            )}
          </div>

          <div className="bg-gradient-to-br from-blue-600 to-indigo-700 p-6 rounded-2xl text-white">
            <h3 className="font-bold text-lg mb-2">Respaldo Automático</h3>
            <p className="text-blue-100 text-sm mb-4">Tus datos están sincronizados con Google Sheets para que nunca pierdas nada.</p>
            <div className="flex items-center gap-2">
              <div className="w-2 h-2 rounded-full bg-emerald-400 animate-pulse" />
              <span className="text-xs font-medium">Conexión Segura</span>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default DashboardView;

import React, { useState, useMemo } from 'react';
import { dbService } from '../services/dbService';
import { Product, Client, SaleItem, SaleStatus, Sale } from '../types';
import { ShoppingCart, Search, User, Trash2, Plus, Minus, CreditCard, Wallet, Download } from 'lucide-react';

const SalesView: React.FC = () => {
  const [cart, setCart] = useState<SaleItem[]>([]);
  const [selectedClient, setSelectedClient] = useState<Client | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [clientSearch, setClientSearch] = useState('');
  const [saleStatus, setSaleStatus] = useState<SaleStatus>(SaleStatus.COMPLETED);
  const [amountPaid, setAmountPaid] = useState<string>('');

  const products = dbService.getProducts();
  const clients = dbService.getClients();

  const filteredProducts = useMemo(() => {
    if (!searchTerm) return [];
    return products.filter(p => 
      p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
      p.barcode.includes(searchTerm)
    );
  }, [products, searchTerm]);

  const filteredClients = useMemo(() => {
    if (!clientSearch) return [];
    return clients.filter(c => c.name.toLowerCase().includes(clientSearch.toLowerCase()));
  }, [clients, clientSearch]);

  const total = useMemo(() => cart.reduce((acc, item) => acc + (item.price * item.quantity), 0), [cart]);

  const addToCart = (product: Product) => {
    if (product.stock <= 0) {
      alert('Sin stock disponible');
      return;
    }
    setCart(prev => {
      const existing = prev.find(item => item.productId === product.id);
      if (existing) {
        return prev.map(item => item.productId === product.id ? { ...item, quantity: item.quantity + 1 } : item);
      }
      return [...prev, { productId: product.id, name: product.name, price: product.price, quantity: 1 }];
    });
    setSearchTerm('');
  };

  const updateQuantity = (id: string, delta: number) => {
    setCart(prev => prev.map(item => {
      if (item.productId === id) {
        const newQty = Math.max(0, item.quantity + delta);
        return { ...item, quantity: newQty };
      }
      return item;
    }).filter(item => item.quantity > 0));
  };

  const handleProcessSale = () => {
    if (cart.length === 0) return;
    if (saleStatus === SaleStatus.CREDIT && !selectedClient) {
      alert('Debes seleccionar un cliente para ventas a crédito');
      return;
    }

    const sale: Sale = {
      id: crypto.randomUUID(),
      userId: 'current-user',
      clientId: selectedClient?.id,
      items: cart,
      total,
      date: new Date().toISOString(),
      status: saleStatus,
      amountPaid: saleStatus === SaleStatus.CREDIT ? Number(amountPaid) : total
    };

    dbService.createSale(sale);
    alert('Venta realizada con éxito. Generando recibo...');
    // Reset
    setCart([]);
    setSelectedClient(null);
    setAmountPaid('');
    setSaleStatus(SaleStatus.COMPLETED);
  };

  return (
    <div className="h-full flex flex-col lg:flex-row gap-6 animate-in fade-in duration-500">
      {/* Left: Product Selection */}
      <div className="flex-1 flex flex-col space-y-6">
        <div className="bg-white p-6 rounded-2xl border border-slate-200 space-y-4">
          <h3 className="text-lg font-bold text-slate-800 flex items-center gap-2">
            <Search size={20} className="text-blue-500" />
            Buscar Productos
          </h3>
          <div className="relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
            <input 
              type="text" 
              placeholder="Nombre o Código de Barras..." 
              className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-blue-500"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
            {filteredProducts.length > 0 && (
              <div className="absolute top-full left-0 right-0 mt-2 bg-white border border-slate-200 rounded-xl shadow-xl z-20 max-h-60 overflow-y-auto">
                {filteredProducts.map(p => (
                  <button 
                    key={p.id}
                    onClick={() => addToCart(p)}
                    className="w-full px-4 py-3 flex items-center justify-between hover:bg-blue-50 transition-colors"
                  >
                    <div className="text-left">
                      <p className="font-bold text-slate-800">{p.name}</p>
                      <p className="text-xs text-slate-400">Stock: {p.stock}</p>
                    </div>
                    <span className="font-bold text-blue-600">${p.price}</span>
                  </button>
                ))}
              </div>
            )}
          </div>
        </div>

        <div className="bg-white p-6 rounded-2xl border border-slate-200 space-y-4">
          <h3 className="text-lg font-bold text-slate-800 flex items-center gap-2">
            <User size={20} className="text-blue-500" />
            Cliente {selectedClient && <span className="text-emerald-600 ml-2">(✓ {selectedClient.name})</span>}
          </h3>
          {!selectedClient ? (
            <div className="relative">
              <input 
                type="text" 
                placeholder="Buscar cliente por nombre..." 
                className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-blue-500"
                value={clientSearch}
                onChange={(e) => setClientSearch(e.target.value)}
              />
              {filteredClients.length > 0 && (
                <div className="absolute top-full left-0 right-0 mt-2 bg-white border border-slate-200 rounded-xl shadow-xl z-20">
                  {filteredClients.map(c => (
                    <button 
                      key={c.id}
