import React, { useState, useMemo, useEffect, useRef } from 'react';
import { dbService } from '../services/dbService';
import { Product, Client, SaleItem, SaleStatus, Sale } from '../types';
import { ShoppingCart, Search, User, Trash2, Plus, Minus, CreditCard, Wallet, Download, ScanLine } from 'lucide-react';

const SalesView: React.FC = () => {
  const [cart, setCart] = useState<SaleItem[]>([]);
  const [selectedClient, setSelectedClient] = useState<Client | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [clientSearch, setClientSearch] = useState('');
  const [saleStatus, setSaleStatus] = useState<SaleStatus>(SaleStatus.COMPLETED);
  const [amountPaid, setAmountPaid] = useState<string>('');
  const searchInputRef = useRef<HTMLInputElement>(null);

  const products = dbService.getProducts();
  const clients = dbService.getClients();

  // Auto-focus search on mount
  useEffect(() => {
    searchInputRef.current?.focus();
  }, []);

  const addToCart = (product: Product) => {
    if (product.stock <= 0) {
      alert(`Sin stock disponible para: ${product.name}`);
      return;
    }
    setCart(prev => {
      const existing = prev.find(item => item.productId === product.id);
      if (existing) {
        return prev.map(item => item.productId === product.id ? { ...item, quantity: item.quantity + 1 } : item);
      }
      return [...prev, { productId: product.id, name: product.name, price: product.price, quantity: 1 }];
    });
    setSearchTerm('');
    searchInputRef.current?.focus();
  };

  // Logic for automatic barcode scanning
  useEffect(() => {
    if (searchTerm.trim().length > 2) {
      const exactMatch = products.find(p => p.barcode === searchTerm.trim());
      if (exactMatch) {
        addToCart(exactMatch);
        // We don't need to clear here because addToCart clears it, 
        // but if addToCart didn't clear it, we would.
      }
    }
  }, [searchTerm, products]);

  const filteredProducts = useMemo(() => {
    if (!searchTerm) return [];
    return products.filter(p => 
      p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
      p.barcode.includes(searchTerm)
    );
  }, [products, searchTerm]);

  const filteredClients = useMemo(() => {
    if (!clientSearch) return [];
    return clients.filter(c => c.name.toLowerCase().includes(clientSearch.toLowerCase()));
  }, [clients, clientSearch]);

  const total = useMemo(() => cart.reduce((acc, item) => acc + (item.price * item.quantity), 0), [cart]);

  const updateQuantity = (id: string, delta: number) => {
    setCart(prev => prev.map(item => {
      if (item.productId === id) {
        const newQty = Math.max(0, item.quantity + delta);
        return { ...item, quantity: newQty };
      }
      return item;
    }).filter(item => item.quantity > 0));
  };

  const handleProcessSale = () => {
    if (cart.length === 0) return;
    if (saleStatus === SaleStatus.CREDIT && !selectedClient) {
      alert('Debes seleccionar un cliente para ventas a crédito');
      return;
    }

    const sale: Sale = {
      id: crypto.randomUUID(),
      userId: 'current-user',
      clientId: selectedClient?.id,
      items: cart,
      total,
      date: new Date().toISOString(),
      status: saleStatus,
      amountPaid: saleStatus === SaleStatus.CREDIT ? Number(amountPaid) : total
    };

    dbService.createSale(sale);
    alert('Venta realizada con éxito.');
    setCart([]);
    setSelectedClient(null);
    setAmountPaid('');
    setSaleStatus(SaleStatus.COMPLETED);
    searchInputRef.current?.focus();
  };

  return (
    <div className="h-full flex flex-col lg:flex-row gap-6 animate-in fade-in duration-500">
      {/* Left: Product Selection */}
      <div className="flex-1 flex flex-col space-y-6">
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm space-y-4">
          <div className="flex items-center justify-between">
            <h3 className="text-lg font-bold text-slate-800 flex items-center gap-2">
              <ScanLine size={20} className="text-blue-500" />
              Buscador / Escáner
            </h3>
            <span className="text-[10px] font-black uppercase bg-blue-100 text-blue-700 px-2 py-1 rounded">Auto-Scan Activo</span>
          </div>
          <div className="relative">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
            <input 
              ref={searchInputRef}
              type="text" 
              placeholder="Escanear código o buscar por nombre..." 
              className="w-full pl-12 pr-4 py-4 bg-slate-50 border border-slate-200 rounded-2xl focus:outline-none focus:ring-2 focus:ring-blue-500 text-lg font-medium transition-all"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === 'Enter' && filteredProducts.length === 1) {
                  addToCart(filteredProducts[0]);
                }
              }}
            />
            {filteredProducts.length > 0 && !products.find(p => p.barcode === searchTerm) && (
              <div className="absolute top-full left-0 right-0 mt-2 bg-white border border-slate-200 rounded-2xl shadow-2xl z-20 max-h-80 overflow-y-auto divide-y divide-slate-100">
                {filteredProducts.map(p => (
                  <button 
                    key={p.id}
                    onClick={() => addToCart(p)}
                    className="w-full px-4 py-4 flex items-center justify-between hover:bg-blue-50 transition-colors"
                  >
                    <div className="text-left">
                      <p className="font-bold text-slate-800">{p.name}</p>
                      <p className="text-xs text-slate-500">SKU: {p.barcode || 'N/A'} • Stock: {p.stock}</p>
                    </div>
                    <span className="font-black text-blue-600 text-lg">${p.price.toLocaleString()}</span>
                  </button>
                ))}
              </div>
            )}
          </div>
        </div>

        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm space-y-4">
          <h3 className="text-lg font-bold text-slate-800 flex items-center gap-2">
            <User size={20} className="text-blue-500" />
            Asignar Cliente {selectedClient && <span className="text-emerald-600 ml-2 text-sm">(✓ {selectedClient.name})</span>}
          </h3>
          {!selectedClient ? (
            <div className="relative">
              <input 
                type="text" 
                placeholder="Buscar cliente..." 
                className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-blue-500"
                value={clientSearch}
                onChange={(e) => setClientSearch(e.target.value)}
              />
              {filteredClients.length > 0 && (
                <div className="absolute top-full left-0 right-0 mt-2 bg-white border border-slate-200 rounded-xl shadow-xl z-20 overflow-hidden divide-y divide-slate-50">
                  {filteredClients.map(c => (
                    <button 
                      key={c.id}
                      onClick={() => { setSelectedClient(c); setClientSearch(''); }}
                      className="w-full px-4 py-3 text-left hover:bg-blue-50 transition-colors"
                    >
                      <p className="font-bold text-slate-800">{c.name}</p>
                      <p className="text-xs text-slate-400">{c.phone}</p>
                    </button>
                  ))}
                </div>
              )}
            </div>
          ) : (
            <div className="flex items-center justify-between p-4 bg-emerald-50 rounded-2xl border border-emerald-100">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 rounded-full bg-emerald-200 flex items-center justify-center text-emerald-700 font-bold">
                  {selectedClient.name.charAt(0)}
                </div>
                <div>
                  <p className="font-bold text-emerald-900">{selectedClient.name}</p>
                  <p className="text-xs text-emerald-600 font-medium">Deuda: ${selectedClient.currentDebt.toLocaleString()}</p>
                </div>
              </div>
              <button onClick={() => setSelectedClient(null)} className="text-xs font-bold text-rose-600 bg-white px-3 py-1 rounded-lg border border-rose-100 shadow-sm">Cambiar</button>
            </div>
          )}
        </div>
      </div>

      {/* Right: Cart and Summary */}
      <div className="w-full lg:w-[420px] flex flex-col h-full gap-6">
        <div className="flex-1 bg-white rounded-3xl border border-slate-200 flex flex-col overflow-hidden shadow-xl">
          <div className="p-5 bg-slate-50 border-b border-slate-200 flex items-center justify-between">
            <h3 className="font-black text-slate-800 flex items-center gap-2 uppercase tracking-wider text-sm">
              <ShoppingCart size={18} className="text-blue-600" /> Detalle de Venta
            </h3>
            <span className="text-xs font-black bg-blue-600 text-white px-2.5 py-1 rounded-full">{cart.length}</span>
          </div>

          <div className="flex-1 overflow-y-auto p-5 space-y-4 scroll-smooth">
            {cart.map(item => (
              <div key={item.productId} className="flex items-center justify-between group">
                <div className="flex-1">
                  <p className="text-sm font-bold text-slate-800 group-hover:text-blue-600 transition-colors">{item.name}</p>
                  <p className="text-xs text-slate-500 font-medium">${item.price.toLocaleString()} x {item.quantity}</p>
                </div>
                <div className="flex items-center gap-2 bg-slate-100 rounded-xl p-1.5 border border-slate-200/50">
                  <button onClick={() => updateQuantity(item.productId, -1)} className="p-1 hover:bg-white hover:text-rose-600 rounded-lg transition-all text-slate-500 shadow-sm"><Minus size={14}/></button>
                  <span className="text-sm font-black w-8 text-center text-slate-800">{item.quantity}</span>
                  <button onClick={() => updateQuantity(item.productId, 1)} className="p-1 hover:bg-white hover:text-emerald-600 rounded-lg transition-all text-slate-500 shadow-sm"><Plus size={14}/></button>
