import { supabase } from '../supabaseClient';
import { Product, Client, Sale, Expense, SaleStatus } from '../types';

export const dbService = {
  // Productos
  async getProducts(): Promise<Product[]> {
    const { data, error } = await supabase
      .from('products')
      .select('*')
      .order('name', { ascending: true });

    if (error) throw error;
    return data || [];
  },

  async saveProduct(product: Partial<Product>) {
    const { data: userData } = await supabase.auth.getUser();
    if (!userData.user) throw new Error("No autenticado");

    const productData = { ...product, user_id: userData.user.id };

    const { error } = await supabase
      .from('products')
      .upsert(productData);

    if (error) throw error;
  },

  async deleteProduct(id: string) {
    const { error } = await supabase
      .from('products')
      .delete()
      .eq('id', id);
    if (error) throw error;
  },

  // Clientes
  async getClients(): Promise<Client[]> {
    const { data, error } = await supabase
      .from('clients')
      .select('*');
    if (error) throw error;
    return data || [];
  },

  async saveClient(client: Partial<Client>) {
    const { data: userData } = await supabase.auth.getUser();
    const { error } = await supabase
      .from('clients')
      .upsert({ ...client, user_id: userData.user?.id });
    if (error) throw error;
  },

  // Ventas (Transaccional)
  async createSale(sale: Partial<Sale>) {
    const { data: userData } = await supabase.auth.getUser();

    // 1. Insertar la venta
    const { data: newSale, error: saleError } = await supabase
      .from('sales')
      .insert({
        user_id: userData.user?.id,
        client_id: sale.clientId,
        total: sale.total,
        amount_paid: sale.amountPaid,
        status: sale.status
      })
      .select()
      .single();

    if (saleError) throw saleError;

    // 2. Actualizar Stock (Simulado aquí, idealmente usar una Database Function/Trigger en Supabase)
    for (const item of sale.items || []) {
      const { data: prod } = await supabase.from('products').select('stock').eq('id', item.productId).single();
      if (prod) {
        await supabase.from('products').update({ stock: prod.stock - item.quantity }).eq('id', item.productId);
      }
    }

    // 3. Si es crédito, actualizar deuda del cliente
    if (sale.status === SaleStatus.CREDIT && sale.clientId) {
      const pending = (sale.total || 0) - (sale.amountPaid || 0);
      const { data: client } = await supabase.from('clients').select('current_debt').eq('id', sale.clientId).single();
      if (client) {
        await supabase.from('clients').update({ current_debt: client.current_debt + pending }).eq('id', sale.clientId);
      }
    }

    return newSale;
  },

  // Egresos
  async getExpenses(): Promise<Expense[]> {
    const { data, error } = await supabase.from('expenses').select('*');
    if (error) throw error;
    return data || [];
  },

  async saveExpense(expense: Partial<Expense>) {
    const { data: userData } = await supabase.auth.getUser();
    const { error } = await supabase
      .from('expenses')
      .insert({ ...expense, user_id: userData.user?.id });
    if (error) throw error;
  }
};

