const CreditView: React.FC = () => {
  const [sales, setSales] = useState<Sale[]>([]);
  const [clients, setClients] = useState<Client[]>([]);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [allSales, allClients] = await Promise.all([
          dbService.getSales(),
          dbService.getClients()
        ]);
        setSales(allSales.filter(s => s.status === SaleStatus.CREDIT));
        setClients(allClients);
      } catch (err) {
        console.error("Error fetching credit data:", err);
      }
    };
    fetchData();
  }, []);

  const getClientName = (id?: string) => {
    if (!id) return 'Cliente Genérico';
    return clients.find(c => c.id === id)?.name || 'Desconocido';
  };

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-2xl font-bold text-slate-800">Control de Crédito</h1>
        <p className="text-slate-500">Monitorea deudas pendientes y pagos.</p>
      </div>

      <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
        <table className="w-full text-left">
          <thead>
            <tr className="bg-slate-50 text-slate-500 text-xs font-bold uppercase tracking-wider">
              <th className="px-6 py-4">Cliente</th>
              <th className="px-6 py-4">Fecha de Venta</th>
              <th className="px-6 py-4">Total</th>
              <th className="px-6 py-4">Pendiente</th>
              <th className="px-6 py-4 text-center">Estado</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {sales.map(sale => {
              const pending = sale.total - sale.amountPaid;
              return (
                <tr key={sale.id} className="hover:bg-slate-50/50 transition-colors">
                  <td className="px-6 py-4">
                    <div className="flex items-center gap-2">
                      <div className="w-8 h-8 rounded-full bg-amber-100 text-amber-600 flex items-center justify-center font-bold text-xs uppercase">
                        {getClientName(sale.clientId).charAt(0)}
                      </div>
                      <span className="font-bold text-slate-800">{getClientName(sale.clientId)}</span>
                    </div>
                  </td>
                  <td className="px-6 py-4 text-sm text-slate-500">{new Date(sale.date).toLocaleDateString()}</td>
                  <td className="px-6 py-4 font-medium">${sale.total.toLocaleString()}</td>
                  <td className="px-6 py-4">
                    <span className="font-bold text-rose-600">${pending.toLocaleString()}</span>
                  </td>
                  <td className="px-6 py-4 text-center">
                    <span className={`px-3 py-1 rounded-full text-[10px] font-black uppercase ${pending > 0 ? 'bg-amber-100 text-amber-700' : 'bg-emerald-100 text-emerald-700'}`}>
                      {pending > 0 ? 'Moroso' : 'Pagado'}
                    </span>
                  </td>
                </tr>
              );
            })}
            {sales.length === 0 && (
              <tr>
                <td colSpan={5} className="py-20 text-center">
                  <AlertCircle className="mx-auto text-slate-200 mb-4" size={48} />
                  <p className="text-slate-400">No hay cuentas a crédito pendientes.</p>
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
};

