import React, { useState } from 'react';
import { supabase } from '../supabaseClient';
import { Store, ArrowRight, ShieldCheck, Loader2, Mail, Lock, CheckCircle2, Building2 } from 'lucide-react';

type AuthStep = 'initial' | 'verification' | 'profile_setup' | 'login';

const AuthView: React.FC<{ onLogin: () => void }> = ({ onLogin }) => {
  const [step, setStep] = useState<AuthStep>('initial');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [code, setCode] = useState('');
  const [businessName, setBusinessName] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const handleSignUp = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    try {
      const { data, error } = await supabase.auth.signUp({
        email,
        password,
      });

      if (error) throw error;

      if (data.user && data.user.identities?.length === 0) {
        setError('Este correo ya está registrado. Intenta iniciar sesión.');
        setLoading(false);
        return;
      }

      setStep('verification');
    } catch (err: any) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  const handleVerifyOtp = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    try {
      const { data, error } = await supabase.auth.verifyOtp({
        email,
        token: code,
        type: 'signup',
      });

      if (error) throw error;

      // Si la verificación es exitosa, vamos al paso del nombre de empresa
      setStep('profile_setup');
    } catch (err: any) {
      setError('Código inválido o expirado. Inténtalo de nuevo.');
    } finally {
      setLoading(false);
    }
  };

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    try {
      const { error } = await supabase.auth.signInWithPassword({
        email,
        password,
      });

      if (error) throw error;
      // El componente App detectará el cambio de sesión automáticamente
    } catch (err: any) {
      setError('Credenciales inválidas. Verifica tu correo y contraseña.');
    } finally {
      setLoading(false);
    }
  };

  const handleCompleteProfile = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) throw new Error("No se encontró el usuario");

      const { error: profileError } = await supabase
        .from('profiles')
        .insert({
          id: user.id,
          business_name: businessName,
          email: user.email
        });

      if (profileError) throw profileError;

      window.location.reload(); // Recargar para entrar a la app con el nuevo perfil
    } catch (err: any) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-4">
      <div className="w-full max-w-md bg-white rounded-3xl shadow-xl p-8 border border-slate-100 relative overflow-hidden transition-all duration-500">

        {/* Header Común */}
        <div className="text-center mb-8">
          <div className="inline-flex items-center justify-center w-16 h-16 bg-blue-600 text-white rounded-2xl mb-4 shadow-lg shadow-blue-200">
            <Store size={32} />
          </div>
          <h1 className="text-2xl font-black text-slate-800 tracking-tight">Caja Registradora</h1>
          <p className="text-slate-500 text-sm mt-1">
            {step === 'initial' && 'Crea tu cuenta de negocio'}
            {step === 'login' && 'Bienvenido de nuevo'}
            {step === 'verification' && 'Verifica tu identidad'}
            {step === 'profile_setup' && 'Configura tu empresa'}
          </p>
        </div>

        {error && (
          <div className="mb-6 p-4 bg-rose-50 border border-rose-100 text-rose-600 text-xs font-bold rounded-xl animate-in fade-in slide-in-from-top-1">
            {error}
          </div>
        )}

        {/* PASO 1: REGISTRO INICIAL */}
        {step === 'initial' && (
          <form onSubmit={handleSignUp} className="space-y-4">
            <div className="space-y-1">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Correo Electrónico</label>
              <div className="relative">
                <Mail className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                <input 
                  required type="email" placeholder="tu@email.com" 
                  className="w-full pl-12 pr-4 py-4 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 focus:ring-blue-500 outline-none transition-all"
                  value={email} onChange={(e) => setEmail(e.target.value)}
                />
              </div>
            </div>
            <div className="space-y-1">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Contraseña</label>
              <div className="relative">
                <Lock className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                <input 
                  required type="password" placeholder="••••••••" 
                  className="w-full pl-12 pr-4 py-4 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 focus:ring-blue-500 outline-none transition-all"
                  value={password} onChange={(e) => setPassword(e.target.value)}
                />
              </div>
            </div>
            <button 
              disabled={loading} type="submit" 
              className="w-full bg-blue-600 hover:bg-blue-700 text-white py-4 rounded-2xl font-black flex items-center justify-center gap-2 shadow-lg shadow-blue-100 disabled:opacity-50 transition-all active:scale-[0.98]"
            >
              {loading ? <Loader2 className="animate-spin" /> : 'Registrarme ahora'}
              {!loading && <ArrowRight size={20} />}
            </button>
            <p className="text-center text-sm text-slate-500 mt-4">
              ¿Ya tienes cuenta? <button type="button" onClick={() => setStep('login')} className="text-blue-600 font-bold hover:underline">Inicia sesión</button>
            </p>
          </form>
        )}

        {/* PASO LOGIN */}
        {step === 'login' && (
          <form onSubmit={handleLogin} className="space-y-4">
            <div className="space-y-1">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Correo Electrónico</label>
              <div className="relative">
                <Mail className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                <input 
                  required type="email" placeholder="tu@email.com" 
                  className="w-full pl-12 pr-4 py-4 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 focus:ring-blue-500 outline-none transition-all"
                  value={email} onChange={(e) => setEmail(e.target.value)}
                />
              </div>
            </div>
            <div className="space-y-1">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Contraseña</label>
              <div className="relative">
                <Lock className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                <input 
                  required type="password" placeholder="••••••••" 
                  className="w-full pl-12 pr-4 py-4 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 focus:ring-blue-500 outline-none transition-all"
                  value={password} onChange={(e) => setPassword(e.target.value)}
                />
              </div>
            </div>
            <button 
              disabled={loading} type="submit" 
              className="w-full bg-slate-800 hover:bg-slate-900 text-white py-4 rounded-2xl font-black flex items-center justify-center gap-2 shadow-lg disabled:opacity-50 transition-all active:scale-[0.98]"
            >
              {loading ? <Loader2 className="animate-spin" /> : 'Entrar a mi cuenta'}
              {!loading && <ArrowRight size={20} />}
            </button>
            <p className="text-center text-sm text-slate-500 mt-4">
              ¿No tienes cuenta? <button type="button" onClick={() => setStep('initial')} className="text-blue-600 font-bold hover:underline">Regístrate</button>
            </p>
          </form>
        )}

        {/* PASO 2: VERIFICACIÓN OTP */}
        {step === 'verification' && (
          <form onSubmit={handleVerifyOtp} className="space-y-6 text-center animate-in zoom-in-95 duration-300">
            <div className="p-4 bg-blue-50 rounded-2xl border border-blue-100 mb-4">
              <p className="text-xs text-blue-700 font-medium">Hemos enviado un código de verificación a su correo. Por favor, revise su bandeja de entrada (y la carpeta de spam).</p>
            </div>
            <div className="space-y-1">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Ingresa el código de 6 dígitos</label>
              <input 
                required type="text" maxLength={6} placeholder="000000"
                className="w-full text-center text-3xl font-black tracking-[0.5em] py-5 bg-slate-50 border-2 border-slate-200 rounded-2xl focus:border-blue-500 focus:ring-4 focus:ring-blue-500/10 outline-none transition-all"
                value={code} onChange={(e) => setCode(e.target.value.replace(/\D/g, ''))}
              />
            </div>
            <button 
              disabled={loading || code.length < 6} type="submit" 
              className="w-full bg-emerald-600 hover:bg-emerald-700 text-white py-4 rounded-2xl font-black flex items-center justify-center gap-2 shadow-lg shadow-emerald-100 disabled:opacity-50 transition-all"
            >
              {loading ? <Loader2 className="animate-spin" /> : 'Verificar Correo'}
              {!loading && <CheckCircle2 size={20} />}
            </button>
            <button type="button" onClick={() => setStep('initial')} className="text-xs font-bold text-slate-400 hover:text-slate-600 uppercase tracking-widest">
              Volver atrás
            </button>
          </form>
        )}

        {/* PASO 3: CONFIGURACIÓN DE PERFIL */}
        {step === 'profile_setup' && (
          <form onSubmit={handleCompleteProfile} className="space-y-6 animate-in slide-in-from-right duration-500">
            <div className="space-y-1">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Nombre de tu Empresa / Negocio</label>
              <div className="relative">
                <Building2 className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                <input 
                  required type="text" placeholder="Ej: Distribuidora Central" 
                  className="w-full pl-12 pr-4 py-4 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 focus:ring-blue-500 outline-none transition-all"
                  value={businessName} onChange={(e) => setBusinessName(e.target.value)}
                />
              </div>
            </div>
            <button 
              disabled={loading || !businessName} type="submit" 
              className="w-full bg-blue-600 hover:bg-blue-700 text-white py-5 rounded-2xl font-black text-lg flex items-center justify-center gap-2 shadow-xl shadow-blue-100 transition-all active:scale-[0.98]"
            >
              {loading ? <Loader2 className="animate-spin" /> : 'Comenzar a usar la App'}
              {!loading && <ArrowRight size={22} />}
            </button>
          </form>
        )}

        <div className="mt-10 pt-6 border-t border-slate-100 flex items-center justify-center gap-2 text-slate-400">
          <ShieldCheck size={16} className="text-emerald-500" />
          <p className="text-[10px] font-bold uppercase tracking-widest">Seguridad Postgres • 2FA Ready</p>
        </div>
      </div>

      <p className="mt-8 text-slate-400 text-[10px] font-black uppercase tracking-widest">© 2024 Caja Registradora Cloud • Venezuela</p>
    </div>
  );
};

