        email,
        password,
      });

      if (signUpError) throw signUpError;

      // Si el usuario ya existe pero no está verificado
      if (data.user && data.user.identities?.length === 0) {
        setError('Este correo ya está registrado. Intenta iniciar sesión.');
        setLoading(false);
        return;
      }

      setStep('verification');
    } catch (err: any) {
      setError(err.message === 'User already registered' ? 'El correo ya está registrado.' : err.message);
    } finally {
      setLoading(false);
    }
  };

  // 2. Verificación del código OTP
  const handleVerifyOtp = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    try {
      const { data, error: verifyError } = await supabase.auth.verifyOtp({
        email,
        token: code,
        type: 'signup',
      });

      if (verifyError) throw verifyError;

      // Verificación exitosa, vamos a configurar el negocio
      setStep('profile_setup');
    } catch (err: any) {
      setError('Código incorrecto o expirado. Verifica tu correo.');
    } finally {
      setLoading(false);
    }
  };

  // 3. Inicio de sesión (para usuarios existentes)
  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    try {
      const { error: loginError } = await supabase.auth.signInWithPassword({
