  // 1. Registro Directo
  const handleSignUp = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    try {
      const { data, error: signUpError } = await supabase.auth.signUp({
        email,
        password,
      });

      if (signUpError) throw signUpError;

      // Si el registro es exitoso y tenemos sesión (Confirm Email desactivado en Supabase)
      if (data.session) {
        setStep('profile_setup');
      } else {
        setError('El registro fue exitoso pero requiere confirmación. Desactiva "Confirm Email" en el panel de Supabase para entrar directo.');
      }
    } catch (err: any) {
      if (err.message.includes('already registered')) {
        setError('Este correo ya tiene una cuenta. Intenta iniciar sesión.');
      } else {
        setError(err.message);
      }
    } finally {
      setLoading(false);
    }
  };

  // 2. Inicio de Sesión
  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    try {
      const { data, error: loginError } = await supabase.auth.signInWithPassword({
        email,
        password,
      });

      if (loginError) throw loginError;

      // Verificar si el usuario ya tiene perfil
      const { data: profile } = await supabase
        .from('profiles')
        .select('id')
        .eq('id', data.user.id)
        .single();

      if (!profile) {
        setStep('profile_setup');
      } else {
        // App.tsx recargará automáticamente al detectar la sesión
        onLogin();
      }
    } catch (err: any) {
      setError('Credenciales incorrectas o cuenta no verificada.');
    } finally {
      setLoading(false);
    }
  };

  // 3. Crear perfil de negocio
  const handleCompleteProfile = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) throw new Error("Sesión no encontrada");

      const { error: profileError } = await supabase
        .from('profiles')
        .insert({
          id: user.id,
          business_name: businessName,
          email: user.email
        });

      if (profileError) throw profileError;

      // Recargar para entrar a la aplicación
      window.location.reload();
    } catch (err: any) {
      setError('Error al guardar los datos del negocio. Intenta de nuevo.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-4">
