        <div className="absolute -bottom-24 -left-24 w-48 h-48 bg-emerald-50 rounded-full blur-3xl opacity-50" />

        <div className="relative z-10">
          <div className="text-center mb-10">
            <div className="inline-flex items-center justify-center w-20 h-20 bg-blue-600 text-white rounded-3xl mb-6 shadow-xl shadow-blue-200">
              <Store size={40} />
            </div>
            <h1 className="text-3xl font-black text-slate-800 tracking-tight">Caja Registradora</h1>
            <p className="text-slate-500 mt-2 font-medium">
              {step === 'initial' && 'Crea tu cuenta gratis'}
              {step === 'login' && 'Bienvenido de nuevo'}
              {step === 'profile_setup' && 'Configura tu negocio'}
            </p>
          </div>

          {error && (
            <div className="mb-6 p-4 bg-rose-50 border border-rose-100 text-rose-600 text-sm font-bold rounded-2xl animate-in fade-in slide-in-from-top-2">
              {error}
            </div>
          )}

          {/* REGISTRO */}
          {step === 'initial' && (
