          <div className="p-6 border-t border-slate-100 bg-slate-50/30 space-y-6">
            <div className="flex items-center justify-between border-t border-slate-200 pt-4">
              <span className="font-black text-slate-900 uppercase tracking-widest text-sm">Monto Total</span>
              <span className="font-black text-3xl text-blue-600 tracking-tighter">${total.toLocaleString()}</span>
            </div>

            <div className="space-y-3">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Método de Pago</p>
              <div className="grid grid-cols-2 gap-3">
                <button 
                  onClick={() => setSaleStatus(SaleStatus.COMPLETED)}
                  className={`flex flex-col items-center justify-center py-4 rounded-2xl border-2 transition-all shadow-sm ${saleStatus === SaleStatus.COMPLETED ? 'border-blue-600 bg-blue-50 text-blue-700' : 'border-slate-100 bg-white text-slate-400'}`}
                >
                  <Wallet size={24} className="mb-1.5" />
                  <span className="text-xs font-black uppercase">Contado</span>
                </button>
                <button 
                  onClick={() => setSaleStatus(SaleStatus.CREDIT)}
                  className={`flex flex-col items-center justify-center py-4 rounded-2xl border-2 transition-all shadow-sm ${saleStatus === SaleStatus.CREDIT ? 'border-amber-500 bg-amber-50 text-amber-700' : 'border-slate-100 bg-white text-slate-400'}`}
                >
                  <CreditCard size={24} className="mb-1.5" />
                  <span className="text-xs font-black uppercase">Crédito</span>
