              </div>
            </div>

            {saleStatus === SaleStatus.CREDIT && (
              <div className="space-y-1 animate-in slide-in-from-top-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Abono Inicial ($)</label>
                <input 
                  type="number" 
                  placeholder="0.00" 
                  className="w-full px-4 py-3 bg-white border border-slate-200 rounded-xl text-lg font-bold shadow-inner"
                  value={amountPaid}
                  onChange={(e) => setAmountPaid(e.target.value)}
                />
              </div>
            )}

            <button 
              onClick={handleProcessSale}
              disabled={cart.length === 0}
              className="w-full bg-blue-600 hover:bg-blue-700 disabled:bg-slate-200 disabled:text-slate-400 text-white py-5 rounded-2xl font-black text-xl transition-all shadow-xl shadow-blue-200 active:scale-95 uppercase tracking-widest"
            >
              Cerrar Venta
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

