import React, { useState, useEffect } from 'react';
import { supabase } from './supabaseClient';
import { 
  LayoutDashboard, 
  Package, 
  ShoppingCart, 
  History,
  Users, 
  CreditCard, 
  Settings, 
  LogOut, 
  Menu, 
  TrendingDown,
  RefreshCw,
  Store,
  Loader2
} from 'lucide-react';
import { ViewType, UserProfile } from './types';
import DashboardView from './views/DashboardView';
import InventoryView from './views/InventoryView';
import SalesView from './views/SalesView';
import SalesHistoryView from './views/SalesHistoryView';
import ClientsView from './views/ClientsView';
import CreditView from './views/CreditView';
import ExpensesView from './views/ExpensesView';
import SettingsView from './views/SettingsView';
import AuthView from './views/AuthView';

const App: React.FC = () => {
  const [session, setSession] = useState<any>(null);
  const [profile, setProfile] = useState<UserProfile | null>(null);
  const [loading, setLoading] = useState(true);
  const [currentView, setCurrentView] = useState<ViewType>('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [syncing, setSyncing] = useState(false);

  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      setSession(session);
      if (session) fetchProfile(session.user.id);
      else setLoading(false);
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setSession(session);
      if (session) fetchProfile(session.user.id);
      else {
        setProfile(null);
        setLoading(false);
      }
    });

    return () => subscription.unsubscribe();
  }, []);

  const fetchProfile = async (userId: string) => {
    try {
      const { data, error } = await supabase
        .from('profiles')
        .select('*')
        .eq('id', userId)
        .single();

      if (data) {
        setProfile({
          id: data.id,
          businessName: data.business_name,
          email: data.email,
          sheetsUrl: data.sheets_url
        });
      } else {
        setProfile(null);
      }
    } catch (err) {
      console.error("Error fetching profile:", err);
    } finally {
      setLoading(false);
    }
  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-slate-50 flex items-center justify-center">
        <Loader2 className="animate-spin text-blue-600" size={40} />
      </div>
    );
  }

  if (!session || (!profile && session)) {
    return <AuthView onLogin={() => {}} />;
  }

  const renderView = () => {
    switch (currentView) {
      case 'dashboard': return <DashboardView />;
      case 'inventory': return <InventoryView />;
      case 'sales': return <SalesView />;
      case 'sales_history': return <SalesHistoryView />;
      case 'clients': return <ClientsView />;
      case 'credit': return <CreditView />;
      case 'expenses': return <ExpensesView />;
      case 'settings': return <SettingsView user={profile!} onUpdateUser={setProfile} />;
      default: return <DashboardView />;
    }
  };

  const NavItem = ({ view, icon: Icon, label }: { view: ViewType, icon: any, label: string }) => (
    <button
      onClick={() => { setCurrentView(view); setIsSidebarOpen(false); }}
      className={`w-full flex items-center space-x-3 px-4 py-3 rounded-lg transition-colors ${
        currentView === view 
          ? 'bg-blue-600 text-white shadow-lg' 
          : 'text-slate-600 hover:bg-slate-100'
      }`}
    >
      <Icon size={20} />
      <span className="font-medium">{label}</span>
    </button>
  );

  return (
    <div className="flex h-screen bg-slate-50 overflow-hidden font-sans">
      {isSidebarOpen && (
        <div className="fixed inset-0 bg-black/50 z-40 lg:hidden" onClick={() => setIsSidebarOpen(false)} />
      )}

      <aside className={`fixed lg:static inset-y-0 left-0 w-64 bg-white border-r border-slate-200 z-50 transform transition-transform duration-300 lg:translate-x-0 ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="flex flex-col h-full p-4">
          <div className="flex items-center space-x-2 px-2 mb-8">
            <div className="bg-blue-600 p-2 rounded-lg text-white"><Store size={24} /></div>
            <h1 className="text-xl font-bold tracking-tight text-slate-800">Caja Pro</h1>
          </div>
          <nav className="flex-1 space-y-1 overflow-y-auto hide-scrollbar">
            <NavItem view="dashboard" icon={LayoutDashboard} label="Dashboard" />
            <NavItem view="sales" icon={ShoppingCart} label="Nueva Venta" />
            <NavItem view="sales_history" icon={History} label="Historial Ventas" />
            <NavItem view="inventory" icon={Package} label="Inventario" />
            <NavItem view="clients" icon={Users} label="Clientes" />
            <NavItem view="credit" icon={CreditCard} label="Crédito & Deudas" />
            <NavItem view="expenses" icon={TrendingDown} label="Egresos" />
            <div className="my-4 border-t border-slate-100" />
            <NavItem view="settings" icon={Settings} label="Configuración" />
          </nav>
          <div className="pt-4 border-t border-slate-100">
            <div className="bg-blue-50 rounded-xl p-4 mb-4">
              <p className="text-xs text-blue-600 font-semibold uppercase mb-1">Tu Negocio</p>
              <p className="text-sm font-bold text-slate-800 truncate">{profile?.businessName}</p>
            </div>
            <button onClick={handleLogout} className="w-full flex items-center space-x-3 px-4 py-3 rounded-lg text-red-600 hover:bg-red-50 transition-colors">
              <LogOut size={20} />
              <span className="font-medium">Cerrar Sesión</span>
            </button>
          </div>
        </div>
      </aside>

      <main className="flex-1 flex flex-col h-full overflow-hidden">
        <header className="h-16 bg-white border-b border-slate-200 flex items-center justify-between px-4 lg:px-8 flex-shrink-0">
          <div className="flex items-center space-x-4">
            <button onClick={() => setIsSidebarOpen(true)} className="lg:hidden p-2 text-slate-600 hover:bg-slate-100 rounded-md"><Menu size={24} /></button>
            <h2 className="text-lg font-bold text-slate-800 lg:text-xl">{profile?.businessName}</h2>
          </div>
          <div className="flex items-center space-x-3">
             <button disabled={syncing} className="flex items-center space-x-2 bg-emerald-50 text-emerald-700 px-3 py-1.5 rounded-full text-sm font-medium hover:bg-emerald-100 transition-colors">
                <RefreshCw size={16} className={syncing ? 'animate-spin' : ''} />
                <span className="hidden sm:inline">Nube Supabase</span>
             </button>
             <div className="w-8 h-8 rounded-full bg-slate-200 flex items-center justify-center text-slate-600 font-bold uppercase">{profile?.businessName.charAt(0)}</div>
          </div>
        </header>
        <div className="flex-1 overflow-y-auto p-4 lg:p-8 bg-slate-50 hide-scrollbar">
          <div className="max-w-6xl mx-auto h-full">{renderView()}</div>
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useMemo, useState, useEffect } from 'react';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer, 
  AreaChart, 
  Area 
} from 'recharts';
import { dbService } from '../services/dbService';
import { DollarSign, TrendingUp, TrendingDown, Package, Users, AlertCircle, PieChart } from 'lucide-react';
import { Sale, Expense, Product, Client } from '../types';

const DashboardView: React.FC = () => {
  const [sales, setSales] = useState<Sale[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [clients, setClients] = useState<Client[]>([]);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [s, e, p, c] = await Promise.all([
          dbService.getSales(),
          dbService.getExpenses(),
          dbService.getProducts(),
          dbService.getClients()
        ]);
        setSales(s);
        setExpenses(e);
        setProducts(p);
        setClients(c);
      } catch (err) {
        console.error("Error fetching dashboard data:", err);
      }
    };
    fetchData();
  }, []);

  const stats = useMemo(() => {
    const totalRevenue = sales.reduce((acc, s) => acc + s.total, 0);
    const totalExpenses = expenses.reduce((acc, e) => acc + e.amount, 0);
    const lowStockCount = products.filter(p => p.stock <= 5).length;
    const pendingCredits = clients.reduce((acc, c) => acc + c.currentDebt, 0);

    // Cálculo de Utilidad Bruta Real: (Precio Venta - Costo) * Cantidad
    let totalGrossProfit = 0;
    sales.forEach(sale => {
      sale.items.forEach(item => {
        const prod = products.find(p => p.id === item.productId);
        const cost = prod ? prod.cost : 0;
        totalGrossProfit += (item.price - cost) * item.quantity;
      });
    });

    const netIncome = totalGrossProfit - totalExpenses;

    return {
      revenue: totalRevenue,
      expenses: totalExpenses,
      profit: netIncome,
      lowStock: lowStockCount,
      pendingCredits
    };
  }, [sales, expenses, products, clients]);

  const chartData = useMemo(() => {
    const last7Days = [...Array(7)].map((_, i) => {
      const d = new Date();
      d.setDate(d.getDate() - i);
      return d.toISOString().split('T')[0];
    }).reverse();

    return last7Days.map(date => {
      const daySales = sales.filter(s => s.date.startsWith(date));
      const revenue = daySales.reduce((acc, s) => acc + s.total, 0);
      const dayExpenses = expenses.filter(e => e.date.startsWith(date)).reduce((acc, e) => acc + e.amount, 0);

      let dayGrossProfit = 0;
      daySales.forEach(sale => {
        sale.items.forEach(item => {
          const prod = products.find(p => p.id === item.productId);
          dayGrossProfit += (item.price - (prod?.cost || 0)) * item.quantity;
        });
      });

      return {
        name: date.slice(5),
        ventas: revenue,
        utilidad: dayGrossProfit - dayExpenses
      };
    });
  }, [sales, expenses, products]);

  const StatCard = ({ title, value, icon: Icon, color, isProfit }: any) => (
    <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 flex items-start justify-between">
      <div>
        <p className="text-xs font-black text-slate-400 uppercase tracking-widest mb-1">{title}</p>
        <h3 className={`text-2xl font-black ${isProfit && value < 0 ? 'text-rose-600' : 'text-slate-800'}`}>
          ${value.toLocaleString()}
        </h3>
        {isProfit && (
          <p className="text-[10px] font-bold mt-2 text-slate-400">
            {value >= 0 ? 'Margen Operativo Positivo' : 'Alerta: Pérdida Neta'}
          </p>
        )}
      </div>
      <div className={`p-3 rounded-2xl ${color} shadow-lg shadow-current/10`}>
        <Icon size={24} />
      </div>
    </div>
  );

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-black text-slate-800 tracking-tight">Panel de Control</h1>
          <p className="text-slate-500 font-medium">Analítica avanzada basada en costos reales.</p>
        </div>
        <div className="flex bg-white p-1 rounded-xl border border-slate-200 shadow-sm">
          <button className="px-5 py-2 text-xs font-black uppercase tracking-widest bg-blue-600 text-white rounded-lg shadow-lg shadow-blue-200">Semana</button>
          <button className="px-5 py-2 text-xs font-black uppercase tracking-widest text-slate-400 hover:text-slate-600">Mes</button>
          <button className="px-5 py-2 text-xs font-black uppercase tracking-widest text-slate-400 hover:text-slate-600">Año</button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard title="Ingresos Brutos" value={stats.revenue} icon={DollarSign} color="bg-blue-50 text-blue-600" />
        <StatCard title="Gastos Operativos" value={stats.expenses} icon={TrendingDown} color="bg-rose-50 text-rose-600" />
        <StatCard title="Utilidad Neta" value={stats.profit} icon={PieChart} color="bg-emerald-50 text-emerald-600" isProfit={true} />
        <StatCard title="Deuda Clientes" value={stats.pendingCredits} icon={Users} color="bg-amber-50 text-amber-600" />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 bg-white p-8 rounded-3xl border border-slate-100 shadow-sm">
          <div className="flex items-center justify-between mb-8">
            <h3 className="text-lg font-black text-slate-800 uppercase tracking-widest">Rendimiento Financiero</h3>
            <div className="flex gap-4">
              <div className="flex items-center gap-2">
                <div className="w-3 h-3 rounded-full bg-blue-600" />
                <span className="text-[10px] font-black uppercase text-slate-400">Ventas</span>
              </div>
              <div className="flex items-center gap-2">
                <div className="w-3 h-3 rounded-full bg-emerald-500" />
                <span className="text-[10px] font-black uppercase text-slate-400">Utilidad</span>
              </div>
            </div>
          </div>
          <div className="h-80 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={chartData}>
                <defs>
                  <linearGradient id="colorVentas" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.1}/>
                    <stop offset="95%" stopColor="#3b82f6" stopOpacity={0}/>
                  </linearGradient>
                  <linearGradient id="colorUtilidad" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#10b981" stopOpacity={0.1}/>
                    <stop offset="95%" stopColor="#10b981" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 10, fontWeight: 700}} dy={10} />
                <YAxis axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 10, fontWeight: 700}} />
                <Tooltip 
                  contentStyle={{borderRadius: '16px', border: 'none', boxShadow: '0 20px 25px -5px rgb(0 0 0 / 0.1)', padding: '12px'}}
                  itemStyle={{fontSize: '12px', fontWeight: 900}}
                />
                <Area type="monotone" dataKey="ventas" stroke="#3b82f6" strokeWidth={3} fillOpacity={1} fill="url(#colorVentas)" />
                <Area type="monotone" dataKey="utilidad" stroke="#10b981" strokeWidth={3} fillOpacity={1} fill="url(#colorUtilidad)" />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="space-y-6">
          <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm">
            <h3 className="text-sm font-black text-slate-800 uppercase tracking-widest mb-6 flex items-center gap-2">
              <AlertCircle className="text-amber-500" size={18} />
              Stock Crítico
            </h3>
            {stats.lowStock > 0 ? (
              <div className="space-y-3">
                {products.filter(p => p.stock <= 5).slice(0, 4).map(p => (
                  <div key={p.id} className="flex items-center justify-between p-4 bg-slate-50 rounded-2xl border border-slate-100">
                    <div>
                      <p className="text-sm font-black text-slate-800">{p.name}</p>
                      <p className="text-[10px] font-bold text-rose-500 uppercase">Quedan {p.stock} uds</p>
                    </div>
                    <button className="text-[10px] font-black text-white bg-slate-800 px-3 py-1.5 rounded-lg uppercase tracking-wider">Reponer</button>
                  </div>
                ))}
              </div>
            ) : (
              <div className="text-center py-10">
                <Package className="mx-auto text-slate-200 mb-4" size={48} />
                <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">Todo en orden</p>
              </div>
            )}
          </div>

          <div className="bg-slate-900 p-8 rounded-3xl text-white relative overflow-hidden group">
            <div className="absolute top-0 right-0 w-32 h-32 bg-blue-500/20 rounded-full -mr-16 -mt-16 transition-transform group-hover:scale-110" />
            <h3 className="font-black text-lg mb-2 uppercase tracking-tight">Seguridad Total</h3>
            <p className="text-slate-400 text-xs font-medium leading-relaxed mb-6">Tus márgenes de ganancia y costos están cifrados y respaldados en la nube.</p>
            <div className="flex items-center gap-3">
              <div className="w-2 h-2 rounded-full bg-emerald-400 animate-pulse" />
              <span className="text-[10px] font-black uppercase tracking-[0.2em] text-emerald-400">Cloud Sync Active</span>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

