import React, { useState, useEffect, useMemo } from 'react';
import { dbService } from '../services/dbService';
import { Sale, Client } from '../types';
import { History, Calendar, Search, Filter, ArrowUpRight, ShoppingBag, User } from 'lucide-react';

type TimeRange = 'hoy' | 'semana' | 'mes' | 'año' | 'todos';

const SalesHistoryView: React.FC = () => {
  const [sales, setSales] = useState<Sale[]>([]);
  const [clients, setClients] = useState<Client[]>([]);
  const [timeRange, setTimeRange] = useState<TimeRange>('semana');
  const [searchTerm, setSearchTerm] = useState('');

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [allSales, allClients] = await Promise.all([
          dbService.getSales(),
          dbService.getClients()
        ]);
        setSales(allSales);
        setClients(allClients);
      } catch (err) {
        console.error("Error fetching history:", err);
      }
    };
    fetchData();
  }, []);

  const filteredSales = useMemo(() => {
    const now = new Date();
    const startOfToday = new Date(now.getFullYear(), now.getMonth(), now.getDate());

    return sales.filter(sale => {
      const saleDate = new Date(sale.date);
      let rangeMatch = true;

      if (timeRange === 'hoy') {
        rangeMatch = saleDate >= startOfToday;
      } else if (timeRange === 'semana') {
        const lastWeek = new Date();
        lastWeek.setDate(now.getDate() - 7);
        rangeMatch = saleDate >= lastWeek;
      } else if (timeRange === 'mes') {
        const lastMonth = new Date();
        lastMonth.setMonth(now.getMonth() - 1);
        rangeMatch = saleDate >= lastMonth;
      } else if (timeRange === 'año') {
        const lastYear = new Date();
        lastYear.setFullYear(now.getFullYear() - 1);
        rangeMatch = saleDate >= lastYear;
      }

      const client = clients.find(c => c.id === sale.clientId);
      const clientName = client ? client.name.toLowerCase() : 'contado';
      const searchMatch = clientName.includes(searchTerm.toLowerCase()) || 
                          sale.id.includes(searchTerm);

      return rangeMatch && searchMatch;
    });
  }, [sales, timeRange, searchTerm, clients]);

  const getClientName = (id?: string) => {
    if (!id) return 'Venta de Contado';
    return clients.find(c => c.id === id)?.name || 'Cliente Desconocido';
  };

  const totals = useMemo(() => {
    return filteredSales.reduce((acc, s) => acc + s.total, 0);
  }, [filteredSales]);

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
        <div>
          <h1 className="text-2xl font-black text-slate-800 tracking-tight">Historial de Ventas</h1>
          <p className="text-slate-500 font-medium">Revisa el detalle de tus operaciones comerciales.</p>
        </div>
        <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm flex items-center gap-4">
          <div className="p-2.5 bg-blue-50 text-blue-600 rounded-xl">
            <ShoppingBag size={20} />
          </div>
          <div>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Total del Periodo</p>
            <p className="text-xl font-black text-slate-800">${totals.toLocaleString()}</p>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        <div className="relative">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
          <input 
            type="text" 
            placeholder="Buscar por cliente o ID de venta..." 
            className="w-full pl-12 pr-4 py-4 bg-white border border-slate-200 rounded-2xl focus:ring-2 focus:ring-blue-500 outline-none font-medium shadow-sm transition-all"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
        <div className="flex bg-white p-1 rounded-2xl border border-slate-200 shadow-sm overflow-x-auto hide-scrollbar">
          {(['hoy', 'semana', 'mes', 'año', 'todos'] as TimeRange[]).map((range) => (
            <button
              key={range}
              onClick={() => setTimeRange(range)}
              className={`flex-1 min-w-[80px] px-4 py-3 text-[10px] font-black uppercase tracking-widest rounded-xl transition-all ${
                timeRange === range ? 'bg-blue-600 text-white shadow-lg shadow-blue-200' : 'text-slate-400 hover:text-slate-600'
              }`}
            >
              {range}
            </button>
          ))}
        </div>
      </div>

      <div className="bg-white border border-slate-200 rounded-[2rem] overflow-hidden shadow-xl">
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-slate-50 text-slate-400 text-[10px] font-black uppercase tracking-[0.2em]">
                <th className="px-8 py-6">Fecha & Hora</th>
                <th className="px-8 py-6">Cliente / Tipo</th>
                <th className="px-8 py-6">Items</th>
                <th className="px-8 py-6">Importe</th>
                <th className="px-8 py-6">Estado</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredSales.map((sale) => (
                <tr key={sale.id} className="hover:bg-slate-50/80 transition-all group">
                  <td className="px-8 py-6">
                    <div className="flex items-center gap-3">
                      <div className="p-2 bg-slate-100 rounded-lg text-slate-400 group-hover:bg-blue-50 group-hover:text-blue-500 transition-colors">
                        <Calendar size={14} />
                      </div>
                      <div>
                        <p className="text-sm font-black text-slate-800">
                          {new Date(sale.date).toLocaleDateString('es-VE', { day: '2-digit', month: 'short' })}
                        </p>
                        <p className="text-[10px] text-slate-400 font-bold uppercase">
                          {new Date(sale.date).toLocaleTimeString('es-VE', { hour: '2-digit', minute: '2-digit' })}
                        </p>
                      </div>
                    </div>
                  </td>
                  <td className="px-8 py-6">
                    <div className="flex items-center gap-3">
                      <div className={`w-8 h-8 rounded-lg flex items-center justify-center font-black text-xs ${sale.clientId ? 'bg-amber-100 text-amber-600' : 'bg-blue-100 text-blue-600'}`}>
                        {sale.clientId ? <User size={14} /> : <ArrowUpRight size={14} />}
                      </div>
                      <p className="text-sm font-black text-slate-700">{getClientName(sale.clientId)}</p>
                    </div>
                  </td>
                  <td className="px-8 py-6">
                    <div className="flex -space-x-2">
                      {sale.items.slice(0, 3).map((item, idx) => (
                        <div key={idx} className="w-8 h-8 rounded-full border-2 border-white bg-slate-200 flex items-center justify-center text-[10px] font-black text-slate-600 shadow-sm" title={item.name}>
                          {item.name.charAt(0)}
                        </div>
                      ))}
                      {sale.items.length > 3 && (
                        <div className="w-8 h-8 rounded-full border-2 border-white bg-slate-800 flex items-center justify-center text-[8px] font-black text-white">
                          +{sale.items.length - 3}
                        </div>
                      )}
                    </div>
                  </td>
                  <td className="px-8 py-6 font-black text-slate-900 text-lg tracking-tight">
                    ${sale.total.toLocaleString()}
                  </td>
                  <td className="px-8 py-6">
                    <span className={`px-4 py-1.5 rounded-xl text-[10px] font-black uppercase tracking-widest shadow-sm ${
                      sale.status === 'COMPLETED' ? 'bg-emerald-100 text-emerald-700' : 'bg-amber-100 text-amber-700'
                    }`}>
                      {sale.status === 'COMPLETED' ? 'Contado' : 'Crédito'}
                    </span>
                  </td>
                </tr>
              ))}
              {filteredSales.length === 0 && (
                <tr>
                  <td colSpan={5} className="py-24 text-center">
                    <div className="flex flex-col items-center opacity-30">
                      <History size={64} className="text-slate-200 mb-4" />
                      <p className="text-xs font-black text-slate-400 uppercase tracking-widest">No se encontraron registros</p>
                    </div>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default SalesHistoryView;

import { supabase } from '../supabaseClient';
import { Product, Client, Sale, Expense, SaleStatus } from '../types';

export const dbService = {
  // Productos
  async getProducts(): Promise<Product[]> {
    const { data, error } = await supabase
      .from('products')
      .select('*')
      .order('name', { ascending: true });

    if (error) throw error;
    return (data || []).map(p => ({
      id: p.id,
      userId: p.user_id,
      name: p.name,
      price: p.price,
      cost: p.cost,
      stock: p.stock,
      barcode: p.barcode,
      category: p.category
    }));
  },

  async saveProduct(product: Partial<Product>) {
    const { data: userData } = await supabase.auth.getUser();
    if (!userData.user) throw new Error("No autenticado");

    const productData = { 
      id: product.id,
      name: product.name,
      price: product.price,
      cost: product.cost,
      stock: product.stock,
      barcode: product.barcode,
      category: product.category,
      user_id: userData.user.id 
    };

    const { error } = await supabase
      .from('products')
      .upsert(productData);

    if (error) throw error;
  },

  async updateStockAndRecordExpense(productId: string, quantityToAdd: number, cost: number, productName: string) {
    const { data: userData } = await supabase.auth.getUser();

    // 1. Actualizar Stock
    const { data: prod } = await supabase.from('products').select('stock').eq('id', productId).single();
    if (prod) {
      await supabase.from('products').update({ stock: prod.stock + quantityToAdd }).eq('id', productId);
    }

    // 2. Registrar Egreso
    const totalCost = quantityToAdd * cost;
    await supabase.from('expenses').insert({
      user_id: userData.user?.id,
      description: `Reposición Stock: ${productName} (+${quantityToAdd} uds)`,
      amount: totalCost,
      date: new Date().toISOString()
    });
  },

  async deleteProduct(id: string) {
    const { error } = await supabase
      .from('products')
      .delete()
      .eq('id', id);
    if (error) throw error;
  },

  // Clientes
  async getClients(): Promise<Client[]> {
    const { data, error } = await supabase
      .from('clients')
      .select('*');
    if (error) throw error;
    return (data || []).map(c => ({
      id: c.id,
      userId: c.user_id,
      name: c.name,
      phone: c.phone,
      email: c.email,
      creditLimit: c.credit_limit,
      currentDebt: c.current_debt
    }));
  },

  async saveClient(client: Partial<Client>) {
    const { data: userData } = await supabase.auth.getUser();
    const { error } = await supabase
      .from('clients')
      .upsert({ 
        id: client.id,
        name: client.name,
        phone: client.phone,
        email: client.email,
        credit_limit: client.creditLimit,
        current_debt: client.currentDebt || 0,
        user_id: userData.user?.id 
      });
    if (error) throw error;
  },

  async addPaymentToClient(clientId: string, amount: number) {
    const { data: client } = await supabase.from('clients').select('current_debt').eq('id', clientId).single();
    if (client) {
      await supabase.from('clients').update({ current_debt: Math.max(0, client.current_debt - amount) }).eq('id', clientId);
    }
  },

  // Ventas
  async getSales(): Promise<Sale[]> {
    const { data, error } = await supabase
      .from('sales')
      .select('*')
      .order('date', { ascending: false });

    if (error) throw error;
    return (data || []).map(s => ({
      id: s.id,
      userId: s.user_id,
      clientId: s.client_id,
      items: s.items || [],
      total: s.total,
      date: s.date,
      status: s.status,
      amountPaid: s.amount_paid
    }));
  },

  async createSale(sale: Partial<Sale>) {
    const { data: userData } = await supabase.auth.getUser();

    const { data: newSale, error: saleError } = await supabase
      .from('sales')
      .insert({
        user_id: userData.user?.id,
        client_id: sale.clientId,
        total: sale.total,
        amount_paid: sale.amountPaid,
        status: sale.status,
        items: sale.items
      })
      .select()
      .single();

    if (saleError) throw saleError;

    for (const item of sale.items || []) {
      const { data: prod } = await supabase.from('products').select('stock').eq('id', item.productId).single();
      if (prod) {
        await supabase.from('products').update({ stock: prod.stock - item.quantity }).eq('id', item.productId);
      }
    }

    if (sale.status === SaleStatus.CREDIT && sale.clientId) {
      const pending = (sale.total || 0) - (sale.amountPaid || 0);
      const { data: client } = await supabase.from('clients').select('current_debt').eq('id', sale.clientId).single();
      if (client) {
        await supabase.from('clients').update({ current_debt: client.current_debt + pending }).eq('id', sale.clientId);
      }
    }

    return newSale;
  },

  async deleteSale(saleId: string) {
    // 1. Obtener datos de la venta para revertir stock y deudas
    const { data: sale } = await supabase.from('sales').select('*').eq('id', saleId).single();
    if (!sale) return;

    // 2. Revertir Stock
    for (const item of sale.items || []) {
      const { data: prod } = await supabase.from('products').select('stock').eq('id', item.productId).single();
      if (prod) {
        await supabase.from('products').update({ stock: prod.stock + item.quantity }).eq('id', item.productId);
      }
    }

    // 3. Revertir Deuda si era crédito
    if (sale.status === SaleStatus.CREDIT && sale.client_id) {
      const pending = sale.total - sale.amount_paid;
      const { data: client } = await supabase.from('clients').select('current_debt').eq('id', sale.client_id).single();
      if (client) {
        await supabase.from('clients').update({ current_debt: Math.max(0, client.current_debt - pending) }).eq('id', sale.client_id);
      }
    }

    // 4. Eliminar venta
    const { error } = await supabase.from('sales').delete().eq('id', saleId);
    if (error) throw error;
  },

  // Egresos
  async getExpenses(): Promise<Expense[]> {
    const { data, error } = await supabase.from('expenses').select('*').order('date', { ascending: false });
    if (error) throw error;
    return (data || []).map(e => ({
      id: e.id,
      userId: e.user_id,
      amount: e.amount,
      description: e.description,
      date: e.date
    }));
  },

  async saveExpense(expense: Partial<Expense>) {
    const { data: userData } = await supabase.auth.getUser();
    const { error } = await supabase
      .from('expenses')
      .insert({ 
        description: expense.description,
        amount: expense.amount,
        user_id: userData.user?.id,
        date: expense.date || new Date().toISOString()
      });
    if (error) throw error;
  }
};

import React, { useMemo, useState, useEffect } from 'react';
import { 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer, 
  AreaChart, 
  Area 
} from 'recharts';
import { dbService } from '../services/dbService';
import { DollarSign, TrendingDown, Package, Users, FileText, PieChart, Download } from 'lucide-react';
import { Sale, Expense, Product, Client } from '../types';

type DashboardPeriod = 'semana' | 'mes' | 'año';

const DashboardView: React.FC = () => {
  const [sales, setSales] = useState<Sale[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [clients, setClients] = useState<Client[]>([]);
  const [period, setPeriod] = useState<DashboardPeriod>('semana');

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [s, e, p, c] = await Promise.all([
          dbService.getSales(),
          dbService.getExpenses(),
          dbService.getProducts(),
          dbService.getClients()
        ]);
        setSales(s);
        setExpenses(e);
        setProducts(p);
        setClients(c);
      } catch (err) {
        console.error("Error fetching dashboard data:", err);
      }
    };
    fetchData();
  }, []);

  const filteredData = useMemo(() => {
    const now = new Date();
    let startDate = new Date();

    if (period === 'semana') startDate.setDate(now.getDate() - 7);
    else if (period === 'mes') startDate.setMonth(now.getMonth() - 1);
    else if (period === 'año') startDate.setFullYear(now.getFullYear() - 1);

    const fSales = sales.filter(s => new Date(s.date) >= startDate);
    const fExpenses = expenses.filter(e => new Date(e.date) >= startDate);

    return { fSales, fExpenses };
  }, [sales, expenses, period]);

  const stats = useMemo(() => {
    const totalRevenue = filteredData.fSales.reduce((acc, s) => acc + s.total, 0);
    const totalExpenses = filteredData.fExpenses.reduce((acc, e) => acc + e.amount, 0);
    const lowStockCount = products.filter(p => p.stock <= 5).length;
    const pendingCredits = clients.reduce((acc, c) => acc + c.currentDebt, 0);

    // Ganancia Neta Solicitada: Ingresos - Egresos
    const netIncome = totalRevenue - totalExpenses;

    return {
      revenue: totalRevenue,
      expenses: totalExpenses,
      profit: netIncome,
      lowStock: lowStockCount,
      pendingCredits
    };
  }, [filteredData, products, clients]);

  const chartData = useMemo(() => {
    const days = period === 'semana' ? 7 : period === 'mes' ? 30 : 12;
    const data = [];

    for (let i = days; i >= 0; i--) {
      const d = new Date();
      if (period === 'año') d.setMonth(d.getMonth() - i);
      else d.setDate(d.getDate() - i);

      const dateKey = period === 'año' 
        ? d.toLocaleString('es-VE', { month: 'short' }) 
        : d.toISOString().split('T')[0].slice(5);

      const daySales = sales.filter(s => {
        const sd = new Date(s.date);
        return period === 'año' 
          ? sd.getMonth() === d.getMonth() && sd.getFullYear() === d.getFullYear()
          : sd.toISOString().split('T')[0] === d.toISOString().split('T')[0];
      });

      const dayExpenses = expenses.filter(e => {
        const ed = new Date(e.date);
        return period === 'año'
          ? ed.getMonth() === d.getMonth() && ed.getFullYear() === d.getFullYear()
          : ed.toISOString().split('T')[0] === d.toISOString().split('T')[0];
      });

      data.push({
        name: dateKey,
        ventas: daySales.reduce((acc, s) => acc + s.total, 0),
        gastos: dayExpenses.reduce((acc, e) => acc + e.amount, 0)
      });
    }
    return data;
  }, [sales, expenses, period]);

  const handlePrintReport = () => {
    window.print();
  };

  const StatCard = ({ title, value, icon: Icon, color, isProfit }: any) => (
    <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 flex items-start justify-between">
      <div>
        <p className="text-xs font-black text-slate-400 uppercase tracking-widest mb-1">{title}</p>
        <h3 className={`text-2xl font-black ${isProfit && value < 0 ? 'text-rose-600' : 'text-slate-800'}`}>
          ${value.toLocaleString()}
        </h3>
      </div>
      <div className={`p-3 rounded-2xl ${color} shadow-lg shadow-current/10`}>
        <Icon size={24} />
      </div>
    </div>
  );

  return (
    <div className="space-y-8 animate-in fade-in duration-500 print:bg-white print:p-0">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 print:hidden">
        <div>
          <h1 className="text-2xl font-black text-slate-800 tracking-tight">Panel de Control</h1>
          <p className="text-slate-500 font-medium">Análisis de rendimiento: {period.toUpperCase()}</p>
        </div>
        <div className="flex items-center gap-4">
          <button 
            onClick={handlePrintReport}
            className="flex items-center gap-2 bg-slate-800 text-white px-4 py-2 rounded-xl text-xs font-black uppercase tracking-widest hover:bg-slate-700 transition-all shadow-lg shadow-slate-200"
          >
            <Download size={16} /> Balance PDF
          </button>
          <div className="flex bg-white p-1 rounded-xl border border-slate-200 shadow-sm">
            {(['semana', 'mes', 'año'] as DashboardPeriod[]).map(p => (
              <button 
                key={p}
                onClick={() => setPeriod(p)}
                className={`px-5 py-2 text-xs font-black uppercase tracking-widest rounded-lg transition-all ${period === p ? 'bg-blue-600 text-white shadow-lg shadow-blue-200' : 'text-slate-400 hover:text-slate-600'}`}
              >
                {p}
              </button>
            ))}
          </div>
        </div>
      </div>

      {/* Vista de Impresión (Oculta en pantalla) */}
      <div className="hidden print:block mb-8">
        <h1 className="text-3xl font-black text-slate-900 mb-2">BALANCE COMERCIAL DETALLADO</h1>
        <p className="text-slate-500 font-bold uppercase tracking-widest text-xs">Periodo: {period} | Generado: {new Date().toLocaleString()}</p>
        <div className="grid grid-cols-3 gap-8 mt-10 border-t-2 border-b-2 border-slate-900 py-6">
          <div>
            <p className="text-[10px] font-black uppercase text-slate-500">Ingresos Totales</p>
            <p className="text-2xl font-black">${stats.revenue.toLocaleString()}</p>
          </div>
          <div>
            <p className="text-[10px] font-black uppercase text-slate-500">Egresos Totales</p>
            <p className="text-2xl font-black">${stats.expenses.toLocaleString()}</p>
          </div>
          <div>
            <p className="text-[10px] font-black uppercase text-slate-500">Resultado Neto</p>
            <p className="text-2xl font-black text-blue-600">${stats.profit.toLocaleString()}</p>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 print:grid-cols-2">
        <StatCard title="Ingresos" value={stats.revenue} icon={DollarSign} color="bg-blue-50 text-blue-600" />
        <StatCard title="Egresos" value={stats.expenses} icon={TrendingDown} color="bg-rose-50 text-rose-600" />
        <StatCard title="Ganancia Neta" value={stats.profit} icon={PieChart} color="bg-emerald-50 text-emerald-600" isProfit={true} />
        <StatCard title="Deuda Clientes" value={stats.pendingCredits} icon={Users} color="bg-amber-50 text-amber-600" />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 bg-white p-8 rounded-3xl border border-slate-100 shadow-sm print:border-none print:shadow-none">
          <h3 className="text-sm font-black text-slate-800 uppercase tracking-widest mb-8">Flujo de Caja</h3>
          <div className="h-80 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={chartData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 10, fontWeight: 700}} dy={10} />
                <YAxis axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 10, fontWeight: 700}} />
                <Tooltip 
                   contentStyle={{borderRadius: '16px', border: 'none', boxShadow: '0 20px 25px -5px rgb(0 0 0 / 0.1)', padding: '12px'}}
                   itemStyle={{fontSize: '12px', fontWeight: 900}}
                />
                <Area type="monotone" dataKey="ventas" stroke="#3b82f6" strokeWidth={3} fill="#3b82f6" fillOpacity={0.05} />
                <Area type="monotone" dataKey="gastos" stroke="#f43f5e" strokeWidth={3} fill="#f43f5e" fillOpacity={0.05} />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm print:hidden">
          <h3 className="text-xs font-black text-slate-800 uppercase tracking-[0.2em] mb-6 flex items-center gap-2">
            <FileText className="text-blue-500" size={16} /> Resumen Contador
          </h3>
          <div className="space-y-4">
            <div className="p-4 bg-slate-50 rounded-2xl">
              <p className="text-[10px] font-black text-slate-400 uppercase">Margen de Ganancia</p>
              <p className="text-lg font-black text-slate-800">
                {stats.revenue > 0 ? ((stats.profit / stats.revenue) * 100).toFixed(1) : 0}%
              </p>
            </div>
            <div className="p-4 bg-slate-50 rounded-2xl">
              <p className="text-[10px] font-black text-slate-400 uppercase">Ticket Promedio</p>
              <p className="text-lg font-black text-slate-800">
                ${filteredData.fSales.length > 0 ? (stats.revenue / filteredData.fSales.length).toFixed(2) : 0}
              </p>
            </div>
            <button 
              onClick={handlePrintReport}
              className="w-full mt-4 py-4 border-2 border-slate-100 rounded-2xl text-[10px] font-black uppercase tracking-widest text-slate-500 hover:bg-slate-50 transition-all"
            >
              Exportar Detalle Auditoría
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default DashboardView;

import React, { useState, useMemo, useEffect } from 'react';
import { dbService } from '../services/dbService';
import { Product } from '../types';
import { Plus, Search, Filter, Edit2, Trash2, Camera, Package, RefreshCw, Loader2 } from 'lucide-react';

const InventoryView: React.FC = () => {
  const [products, setProducts] = useState<Product[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isReplenishOpen, setIsReplenishOpen] = useState(false);
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    dbService.getProducts().then(setProducts).catch(console.error);
  }, []);

  const filteredProducts = useMemo(() => {
    return products.filter(p => 
      p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
      (p.barcode && p.barcode.includes(searchTerm))
    );
  }, [products, searchTerm]);

  const handleSaveProduct = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setLoading(true);
    const formData = new FormData(e.currentTarget);
    const newProduct: Partial<Product> = {
      id: editingProduct?.id || crypto.randomUUID(),
      name: formData.get('name') as string,
      barcode: formData.get('barcode') as string,
      category: formData.get('category') as string,
      price: Number(formData.get('price')),
      cost: Number(formData.get('cost')),
      stock: Number(formData.get('stock')),
    };
    try {
      await dbService.saveProduct(newProduct as Product);
      const updated = await dbService.getProducts();
      setProducts(updated);
      setIsModalOpen(false);
      setEditingProduct(null);
    } catch (err) {
      alert("Error al guardar producto");
    } finally {
      setLoading(false);
    }
  };

  const handleReplenishStock = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!editingProduct) return;
    setLoading(true);
    const formData = new FormData(e.currentTarget);
    const qty = Number(formData.get('qty'));

    try {
      await dbService.updateStockAndRecordExpense(
        editingProduct.id, 
        qty, 
        editingProduct.cost, 
        editingProduct.name
      );
      const updated = await dbService.getProducts();
      setProducts(updated);
      setIsReplenishOpen(false);
      setEditingProduct(null);
      alert('Stock actualizado y egreso registrado con éxito.');
    } catch (err) {
      alert("Error al reponer stock");
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (id: string) => {
    if (confirm('¿Estás seguro de eliminar este producto?')) {
      try {
        await dbService.deleteProduct(id);
        const updated = await dbService.getProducts();
        setProducts(updated);
      } catch (err) {
        alert("Error al eliminar producto");
      }
    }
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-black text-slate-800 tracking-tight">Inventario Global</h1>
          <p className="text-slate-500 font-medium">Control total de stock y costos base.</p>
        </div>
        <button 
          onClick={() => { setEditingProduct(null); setIsModalOpen(true); }}
          className="bg-blue-600 hover:bg-blue-700 text-white px-6 py-3 rounded-2xl font-black text-sm uppercase tracking-widest flex items-center justify-center gap-2 shadow-xl shadow-blue-200 transition-all active:scale-95"
        >
          <Plus size={18} /> Nuevo Item
        </button>
      </div>

      <div className="flex flex-col md:flex-row gap-4">
        <div className="relative flex-1">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
          <input 
            type="text" 
            placeholder="Buscar por nombre o EAN-13..." 
            className="w-full pl-12 pr-4 py-4 bg-white border border-slate-200 rounded-2xl focus:ring-2 focus:ring-blue-500 transition-all font-medium shadow-sm outline-none"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
      </div>

      <div className="bg-white border border-slate-200 rounded-[2rem] overflow-hidden shadow-xl">
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-slate-50 text-slate-400 text-[10px] font-black uppercase tracking-[0.2em]">
                <th className="px-8 py-6">Producto & Código</th>
                <th className="px-8 py-6">Costo / P.Venta</th>
                <th className="px-8 py-6">Inventario</th>
                <th className="px-8 py-6">Acciones</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredProducts.map((p) => (
                <tr key={p.id} className="hover:bg-slate-50/80 transition-all group">
                  <td className="px-8 py-6">
                    <div>
                      <p className="font-black text-slate-800">{p.name}</p>
                      <p className="text-[10px] text-slate-400 font-black uppercase tracking-wider flex items-center gap-1">
                        <Camera size={10} /> {p.barcode || 'SIN EAN'} • {p.category}
                      </p>
                    </div>
                  </td>
                  <td className="px-8 py-6">
                    <div className="flex flex-col">
                      <span className="text-xs font-bold text-slate-400">C: ${p.cost.toLocaleString()}</span>
                      <span className="text-sm font-black text-blue-600">V: ${p.price.toLocaleString()}</span>
                    </div>
                  </td>
                  <td className="px-8 py-6">
                    <div className="flex items-center gap-3">
                      <div className={`w-2.5 h-2.5 rounded-full ${p.stock <= 5 ? 'bg-rose-500 animate-pulse' : 'bg-emerald-500'}`} />
                      <span className={`text-sm font-black ${p.stock <= 5 ? 'text-rose-600' : 'text-slate-800'}`}>
                        {p.stock} uds
                      </span>
                    </div>
                  </td>
                  <td className="px-8 py-6">
                    <div className="flex items-center gap-2">
                      <button 
                        onClick={() => { setEditingProduct(p); setIsReplenishOpen(true); }}
                        className="p-2.5 text-blue-600 bg-blue-50 hover:bg-blue-100 rounded-xl transition-all"
                        title="Reponer Stock"
                      >
                        <RefreshCw size={16} />
                      </button>
                      <button 
                        onClick={() => { setEditingProduct(p); setIsModalOpen(true); }}
                        className="p-2.5 text-slate-400 hover:text-slate-900 bg-slate-50 hover:bg-slate-100 rounded-xl transition-all"
                      >
                        <Edit2 size={16} />
                      </button>
                      <button 
                        onClick={() => handleDelete(p.id)}
                        className="p-2.5 text-rose-300 hover:text-rose-600 hover:bg-rose-50 rounded-xl transition-all"
                      >
                        <Trash2 size={16} />
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
              {filteredProducts.length === 0 && (
                <tr>
                  <td colSpan={4} className="py-24 text-center">
                    <Package className="mx-auto text-slate-100 mb-4" size={64} />
                    <p className="text-xs font-black text-slate-400 uppercase tracking-widest">Sin coincidencias</p>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Modal Reponer Stock */}
      {isReplenishOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/40 backdrop-blur-sm animate-in fade-in duration-200" onClick={() => setIsReplenishOpen(false)} />
          <div className="relative bg-white w-full max-w-sm rounded-[2rem] shadow-2xl p-8 animate-in zoom-in-95 duration-200">
            <h3 className="text-xl font-black text-slate-800 mb-2">Ingresar Mercancía</h3>
            <p className="text-xs text-slate-500 font-medium mb-6">Se generará un egreso de ${editingProduct?.cost} por cada unidad añadida.</p>
            <form onSubmit={handleReplenishStock} className="space-y-4">
              <div className="space-y-1">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Cantidad a Añadir</label>
                <input name="qty" type="number" required autoFocus className="w-full px-4 py-4 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 focus:ring-blue-500 outline-none font-black text-xl" placeholder="0" />
              </div>
