import React, { useState, useMemo, useEffect } from 'react';
import { dbService } from '../services/dbService';
import { Product } from '../types';
import { Plus, Search, Filter, Edit2, Trash2, Camera, Package, RefreshCw, Loader2, Calculator } from 'lucide-react';

const InventoryView: React.FC = () => {
  const [products, setProducts] = useState<Product[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isReplenishOpen, setIsReplenishOpen] = useState(false);
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);
  const [loading, setLoading] = useState(false);

  // Estados para el modal de reposición inteligente
  const [replenishQty, setReplenishQty] = useState<number>(0);
  const [unitCost, setUnitCost] = useState<number>(0);
  const [totalCost, setTotalCost] = useState<number>(0);

  useEffect(() => {
    dbService.getProducts().then(setProducts).catch(console.error);
  }, []);

  // Sincronizar estados cuando se abre el modal de reposición
  useEffect(() => {
    if (editingProduct && isReplenishOpen) {
      setUnitCost(editingProduct.cost);
      setReplenishQty(0);
      setTotalCost(0);
    }
  }, [editingProduct, isReplenishOpen]);

  const filteredProducts = useMemo(() => {
    return products.filter(p => 
      p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
      (p.barcode && p.barcode.includes(searchTerm))
    );
  }, [products, searchTerm]);

  const handleSaveProduct = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setLoading(true);
    const formData = new FormData(e.currentTarget);
    const newProduct: Partial<Product> = {
      id: editingProduct?.id || crypto.randomUUID(),
      name: formData.get('name') as string,
      barcode: formData.get('barcode') as string,
      category: formData.get('category') as string,
      price: Number(formData.get('price')),
      cost: Number(formData.get('cost')),
      stock: Number(formData.get('stock')),
    };
    try {
      await dbService.saveProduct(newProduct as Product);
      const updated = await dbService.getProducts();
      setProducts(updated);
      setIsModalOpen(false);
      setEditingProduct(null);
    } catch (err) {
      alert("Error al guardar producto");
    } finally {
      setLoading(false);
    }
  };

  const handleReplenishStock = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!editingProduct || replenishQty <= 0) return;
    setLoading(true);

    try {
      // Usamos el unitCost que puede haber sido modificado manualmente o calculado
      await dbService.updateStockAndRecordExpense(
        editingProduct.id, 
        replenishQty, 
        unitCost, 
        editingProduct.name
      );

      // Actualizar también el costo base del producto para futuras ventas/reposiciones
      await dbService.saveProduct({
        ...editingProduct,
        cost: unitCost
      });

      const updated = await dbService.getProducts();
      setProducts(updated);
      setIsReplenishOpen(false);
      setEditingProduct(null);
      alert('Stock actualizado, costo base ajustado y egreso registrado.');
    } catch (err) {
      alert("Error al reponer stock");
    } finally {
      setLoading(false);
    }
  };

  const calculateFromTotal = (total: number) => {
    setTotalCost(total);
    if (replenishQty > 0) {
      setUnitCost(Number((total / replenishQty).toFixed(2)));
    }
  };

  const calculateFromUnit = (unit: number) => {
    setUnitCost(unit);
    if (replenishQty > 0) {
      setTotalCost(Number((unit * replenishQty).toFixed(2)));
    }
  };

  const handleQtyChange = (qty: number) => {
    setReplenishQty(qty);
    // Si ya tenemos un costo unitario, actualizamos el total
    if (unitCost > 0) {
      setTotalCost(Number((unitCost * qty).toFixed(2)));
    }
  };

  const handleDelete = async (id: string) => {
    if (confirm('¿Estás seguro de eliminar este producto?')) {
      try {
        await dbService.deleteProduct(id);
        const updated = await dbService.getProducts();
        setProducts(updated);
      } catch (err) {
        alert("Error al eliminar producto");
      }
    }
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-black text-slate-800 tracking-tight">Inventario Global</h1>
          <p className="text-slate-500 font-medium">Control total de stock y costos base.</p>
        </div>
        <button 
          onClick={() => { setEditingProduct(null); setIsModalOpen(true); }}
          className="bg-blue-600 hover:bg-blue-700 text-white px-6 py-3 rounded-2xl font-black text-sm uppercase tracking-widest flex items-center justify-center gap-2 shadow-xl shadow-blue-200 transition-all active:scale-95"
