import { supabase } from '../supabaseClient';
import { Product, Client, Sale, Expense, SaleStatus } from '../types';

export const dbService = {
  // Productos
  async getProducts(): Promise<Product[]> {
    const { data, error } = await supabase
      .from('products')
      .select('*')
      .order('name', { ascending: true });

    if (error) throw error;
    return (data || []).map(p => ({
      id: p.id,
      userId: p.user_id,
      name: p.name,
      price: p.price,
      cost: p.cost,
      stock: p.stock,
      barcode: p.barcode,
      category: p.category
    }));
  },

  async saveProduct(product: Partial<Product>) {
    const { data: userData } = await supabase.auth.getUser();
    if (!userData.user) throw new Error("No autenticado");

    const productData = { 
      id: product.id,
      name: product.name,
      price: product.price,
      cost: product.cost,
      stock: product.stock,
      barcode: product.barcode,
      category: product.category,
      user_id: userData.user.id 
    };

    const { error } = await supabase
      .from('products')
      .upsert(productData);

    if (error) throw error;
  },

  async updateStockAndRecordExpense(productId: string, quantityToAdd: number, cost: number, productName: string) {
    const { data: userData } = await supabase.auth.getUser();
    if (!userData.user) throw new Error("No autenticado");

    const { data: prod, error: fetchError } = await supabase
      .from('products')
      .select('stock')
      .eq('id', productId)
      .single();

    if (fetchError || !prod) throw new Error("Producto no encontrado");

    const { error: updateError } = await supabase
      .from('products')
      .update({ 
        stock: prod.stock + quantityToAdd,
        cost: cost 
      })
      .eq('id', productId);

    if (updateError) throw updateError;

    const totalCost = quantityToAdd * cost;
    const { error: expenseError } = await supabase.from('expenses').insert({
      user_id: userData.user.id,
      description: `Reposición Stock: ${productName} (+${quantityToAdd} uds)`,
      amount: totalCost,
      date: new Date().toISOString()
    });

    if (expenseError) throw expenseError;
  },

  async deleteProduct(id: string) {
    const { error } = await supabase
      .from('products')
      .delete()
      .eq('id', id);
    if (error) throw error;
  },

  // Clientes
  async getClients(): Promise<Client[]> {
    const { data, error } = await supabase
      .from('clients')
      .select('*');
    if (error) throw error;
    return (data || []).map(c => ({
      id: c.id,
      userId: c.user_id,
      name: c.name,
      phone: c.phone || '',
      email: c.email || '',
      currentDebt: c.current_debt || 0
    }));
  },

  async saveClient(client: Partial<Client>): Promise<Client> {
    const { data: userData } = await supabase.auth.getUser();
    const { error, data } = await supabase
      .from('clients')
      .upsert({ 
        id: client.id || crypto.randomUUID(),
        name: client.name,
        phone: client.phone || '',
        email: client.email || '',
        current_debt: client.currentDebt || 0,
        user_id: userData.user?.id 
      })
      .select()
      .single();

    if (error) throw error;

    // Mapeo manual para asegurar compatibilidad con la interfaz Client
    return {
      id: data.id,
      userId: data.user_id,
      name: data.name,
      phone: data.phone || '',
      email: data.email || '',
      currentDebt: data.current_debt || 0
    };
  },

  async deleteClient(id: string) {
    const { error } = await supabase.from('clients').delete().eq('id', id);
    if (error) throw error;
  },

  async addPaymentToClient(clientId: string, amount: number) {
    const { data: client } = await supabase.from('clients').select('current_debt').eq('id', clientId).single();
    if (client) {
      await supabase.from('clients').update({ current_debt: Math.max(0, client.current_debt - amount) }).eq('id', clientId);
    }
  },

  // Nueva lógica de procesamiento de abonos distribuidos
  async processDistributedAbono(clientId: string, totalAmount: number, saleIds: string[]) {
    const { data: sales, error: fetchError } = await supabase
      .from('sales')
      .select('*')
      .in('id', saleIds)
      .order('date', { ascending: true });

    if (fetchError) throw fetchError;

    let remainingPayment = totalAmount;

    for (const sale of sales) {
      if (remainingPayment <= 0) break;

      const pending = sale.total - sale.amount_paid;
      const paymentToApply = Math.min(remainingPayment, pending);
      const newAmountPaid = sale.amount_paid + paymentToApply;
      const newStatus = newAmountPaid >= sale.total ? SaleStatus.COMPLETED : SaleStatus.CREDIT;

      const { error: updateError } = await supabase
        .from('sales')
        .update({
          amount_paid: newAmountPaid,
          status: newStatus
        })
        .eq('id', sale.id);

      if (updateError) throw updateError;
      remainingPayment -= paymentToApply;
    }

    const { data: client } = await supabase.from('clients').select('current_debt').eq('id', clientId).single();
    if (client) {
      await supabase.from('clients').update({ 
        current_debt: Math.max(0, client.current_debt - totalAmount) 
      }).eq('id', clientId);
    }
  },

  // Ventas
  async getSales(): Promise<Sale[]> {
    const { data, error } = await supabase
      .from('sales')
      .select('*')
      .order('date', { ascending: false });

    if (error) throw error;
    return (data || []).map(s => ({
      id: s.id,
      userId: s.user_id,
      clientId: s.client_id,
      items: s.items || [],
      total: s.total,
      date: s.date,
      status: s.status,
      amountPaid: s.amount_paid
    }));
  },

  async createSale(sale: Partial<Sale>) {
    const { data: userData } = await supabase.auth.getUser();

    const { data: newSale, error: saleError } = await supabase
      .from('sales')
      .insert({
        user_id: userData.user?.id,
        client_id: sale.clientId,
        total: sale.total,
        amount_paid: sale.amountPaid,
        status: sale.status,
        items: sale.items
      })
      .select()
      .single();

    if (saleError) throw saleError;

    for (const item of sale.items || []) {
      const { data: prod } = await supabase.from('products').select('stock').eq('id', item.productId).single();
      if (prod) {
        await supabase.from('products').update({ stock: prod.stock - item.quantity }).eq('id', item.productId);
      }
    }

    if (sale.status === SaleStatus.CREDIT && sale.clientId) {
      const pending = (sale.total || 0) - (sale.amountPaid || 0);
      const { data: client } = await supabase.from('clients').select('current_debt').eq('id', sale.clientId).single();
      if (client) {
        await supabase.from('clients').update({ current_debt: client.current_debt + pending }).eq('id', sale.clientId);
      }
    }

    return newSale;
  },

  async deleteSale(saleId: string) {
    const { data: sale } = await supabase.from('sales').select('*').eq('id', saleId).single();
    if (!sale) return;

    for (const item of sale.items || []) {
      const { data: prod } = await supabase.from('products').select('stock').eq('id', item.productId).single();
      if (prod) {
        await supabase.from('products').update({ stock: prod.stock + item.quantity }).eq('id', item.productId);
      }
    }

    if (sale.status === SaleStatus.CREDIT && sale.client_id) {
      const pending = sale.total - sale.amount_paid;
      const { data: client } = await supabase.from('clients').select('current_debt').eq('id', sale.client_id).single();
      if (client) {
        await supabase.from('clients').update({ current_debt: Math.max(0, client.current_debt - pending) }).eq('id', sale.client_id);
      }
    }

    const { error } = await supabase.from('sales').delete().eq('id', saleId);
    if (error) throw error;
  },

  // Egresos / Gastos
  async getExpenses(): Promise<Expense[]> {
    const { data, error } = await supabase.from('expenses').select('*').order('date', { ascending: false });
    if (error) throw error;
    return (data || []).map(e => ({
      id: e.id,
      userId: e.user_id,
      amount: e.amount,
      description: e.description,
      date: e.date
    }));
  },

  async saveExpense(expense: Partial<Expense>) {
    const { data: userData } = await supabase.auth.getUser();
    if (!userData.user) throw new Error("No autenticado");

    const expenseData = {
      description: expense.description,
      amount: expense.amount,
      user_id: userData.user.id,
      date: expense.date || new Date().toISOString()
    };

    if (expense.id) {
      const { error } = await supabase
        .from('expenses')
        .update(expenseData)
        .eq('id', expense.id);
      if (error) throw error;
    } else {
      const { error } = await supabase
        .from('expenses')
        .insert(expenseData);
      if (error) throw error;
    }
  },

  async deleteExpense(id: string) {
    const { error } = await supabase.from('expenses').delete().eq('id', id);
    if (error) throw error;
  }
};

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { dbService } from '../services/dbService';
import { Product, Client, SaleItem, SaleStatus, Sale } from '../types';
import { ShoppingCart, Search, User, Trash2, Plus, Minus, CreditCard, Wallet, AlertTriangle, ScanLine, UserPlus, Loader2 } from 'lucide-react';

const SalesView: React.FC = () => {
  const [products, setProducts] = useState<Product[]>([]);
  const [clients, setClients] = useState<Client[]>([]);
  const [cart, setCart] = useState<SaleItem[]>([]);
  const [selectedClient, setSelectedClient] = useState<Client | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [clientSearch, setClientSearch] = useState('');
  const [saleStatus, setSaleStatus] = useState<SaleStatus>(SaleStatus.COMPLETED);
  const [amountPaid, setAmountPaid] = useState<string>('');
  const [isCreatingClient, setIsCreatingClient] = useState(false);
  const searchInputRef = useRef<HTMLInputElement>(null);

  const lastProcessedRef = useRef<number>(0);

  useEffect(() => {
    dbService.getProducts().then(setProducts).catch(console.error);
    dbService.getClients().then(setClients).catch(console.error);
  }, []);

  useEffect(() => {
    searchInputRef.current?.focus();
  }, []);

  const addToCart = (product: Product) => {
    const now = Date.now();
    if (now - lastProcessedRef.current < 200) return;
    lastProcessedRef.current = now;

    setCart(prev => {
      const existing = prev.find(item => item.productId === product.id);
      if (existing) {
        return prev.map(item => item.productId === product.id ? { ...item, quantity: item.quantity + 1 } : item);
      }
      return [...prev, { productId: product.id, name: product.name, price: product.price, quantity: 1 }];
    });

    setSearchTerm('');
    setTimeout(() => {
      searchInputRef.current?.focus();
    }, 10);
  };

  const filteredProducts = useMemo(() => {
    if (!searchTerm || searchTerm.length < 2) return [];
    return products.filter(p => 
      p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
      (p.barcode && p.barcode.includes(searchTerm))
    );
  }, [products, searchTerm]);

  const filteredClients = useMemo(() => {
    if (!clientSearch) return [];
    return clients.filter(c => c.name.toLowerCase().includes(clientSearch.toLowerCase()));
  }, [clients, clientSearch]);

  const total = useMemo(() => cart.reduce((acc, item) => acc + (item.price * item.quantity), 0), [cart]);

  const updateQuantity = (id: string, delta: number) => {
    setCart(prev => prev.map(item => {
      if (item.productId === id) {
        const newQty = Math.max(0, item.quantity + delta);
        return { ...item, quantity: newQty };
      }
      return item;
    }).filter(item => item.quantity > 0));
  };

  const handleQuickCreateClient = async () => {
    if (!clientSearch.trim()) return;
    setIsCreatingClient(true);
    try {
      const newClient = await dbService.saveClient({
        name: clientSearch.trim(),
        phone: '',
        email: '',
        currentDebt: 0
      });
      // Recargar la lista de clientes completa
      const updatedClients = await dbService.getClients();
      setClients(updatedClients);
      // Seleccionar el nuevo cliente (saveClient ya devuelve el formato correcto ahora)
      setSelectedClient(newClient);
      setClientSearch('');
    } catch (err) {
      console.error(err);
      alert("Error al crear cliente rápido");
    } finally {
      setIsCreatingClient(false);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      const val = searchTerm.trim();
      if (!val) return;

      const exactMatch = products.find(p => p.barcode === val);
      if (exactMatch) {
        addToCart(exactMatch);
        return;
      }

      if (filteredProducts.length === 1) {
        addToCart(filteredProducts[0]);
      }
    }
  };

  const handleProcessSale = async () => {
    if (cart.length === 0) return;
    if (saleStatus === SaleStatus.CREDIT && !selectedClient) {
      alert('Debes seleccionar un cliente para ventas a crédito');
      return;
    }

    const sale: Partial<Sale> = {
      id: crypto.randomUUID(),
      clientId: selectedClient?.id,
      items: cart,
      total,
      date: new Date().toISOString(),
      status: saleStatus,
      amountPaid: saleStatus === SaleStatus.CREDIT ? Number(amountPaid) : total
    };

    try {
      await dbService.createSale(sale);
      alert('¡Venta registrada con éxito!');
      setCart([]);
      setSelectedClient(null);
      setAmountPaid('');
      setSaleStatus(SaleStatus.COMPLETED);
      const updatedProds = await dbService.getProducts();
      setProducts(updatedProds);
      searchInputRef.current?.focus();
    } catch (err) {
      alert("Error al procesar la venta");
      console.error(err);
    }
  };

  return (
    <div className="h-full flex flex-col lg:flex-row gap-6 animate-in fade-in duration-500">
      <div className="flex-1 flex flex-col space-y-6">
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm space-y-4">
          <div className="flex items-center justify-between">
            <h3 className="text-lg font-black text-slate-800 flex items-center gap-2 uppercase tracking-widest text-sm">
              <ScanLine size={20} className="text-blue-500" />
              Terminal de Ventas
            </h3>
            <span className="text-[10px] font-black uppercase bg-slate-900 text-white px-3 py-1 rounded-lg tracking-wider">Listo para Escanear</span>
          </div>
          <div className="relative">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
            <input 
              ref={searchInputRef}
              type="text" 
              placeholder="Escribe o escanea producto..." 
              className="w-full pl-12 pr-4 py-4 bg-slate-50 border border-slate-200 rounded-2xl focus:outline-none focus:ring-2 focus:ring-blue-500 text-lg font-medium transition-all"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              onKeyDown={handleKeyDown}
            />

            {filteredProducts.length > 0 && (
              <div className="absolute top-full left-0 right-0 mt-2 bg-white border border-slate-200 rounded-2xl shadow-2xl z-20 max-h-80 overflow-y-auto divide-y divide-slate-100 overflow-hidden">
                {filteredProducts.map(p => (
                  <button 
                    key={p.id}
                    onClick={() => addToCart(p)}
                    className="w-full px-4 py-4 flex items-center justify-between hover:bg-blue-50 transition-colors"
                  >
                    <div className="text-left">
                      <p className="font-black text-slate-800">{p.name}</p>
                      <p className={`text-xs font-bold ${p.stock <= 5 ? 'text-rose-500' : 'text-slate-400'}`}>
                        Stock: {p.stock} unidades {p.stock <= 0 && '(AGOTADO)'}
                      </p>
                    </div>
                    <span className="font-black text-blue-600 text-lg">${p.price.toLocaleString()}</span>
                  </button>
                ))}
              </div>
            )}
          </div>
        </div>

        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm space-y-4">
          <h3 className="text-sm font-black text-slate-800 flex items-center gap-2 uppercase tracking-widest">
            <User size={20} className="text-blue-500" />
            Cliente Asociado
          </h3>
          {!selectedClient ? (
            <div className="relative">
              <input 
                type="text" 
                placeholder="Buscar cliente por nombre..." 
                className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-blue-500 font-medium"
                value={clientSearch}
                onChange={(e) => setClientSearch(e.target.value)}
              />
              {(filteredClients.length > 0 || clientSearch.length > 1) && (
                <div className="absolute top-full left-0 right-0 mt-2 bg-white border border-slate-200 rounded-xl shadow-xl z-20 overflow-hidden divide-y divide-slate-50">
                  {filteredClients.map(c => (
                    <button 
                      key={c.id}
                      onClick={() => { setSelectedClient(c); setClientSearch(''); }}
                      className="w-full px-4 py-3 text-left hover:bg-blue-50 transition-colors flex items-center justify-between"
                    >
                      <div>
                        <p className="font-bold text-slate-800">{c.name}</p>
                        <p className="text-[10px] text-slate-400 font-black uppercase">{c.phone || 'Sin teléfono'}</p>
                      </div>
                      <Plus size={16} className="text-blue-400" />
                    </button>
                  ))}
                  {clientSearch.length > 1 && (
                    <button 
                      onClick={handleQuickCreateClient}
                      disabled={isCreatingClient}
                      className="w-full px-4 py-4 text-left hover:bg-blue-600 hover:text-white bg-blue-50 transition-all flex items-center gap-3 text-blue-700"
                    >
                      {isCreatingClient ? <Loader2 size={18} className="animate-spin" /> : <UserPlus size={18} />}
                      <span className="font-black text-sm uppercase tracking-widest">Registrar "{clientSearch}" como nuevo</span>
                    </button>
                  )}
                </div>
              )}
            </div>
          ) : (
            <div className="flex items-center justify-between p-4 bg-emerald-50 rounded-2xl border border-emerald-100 shadow-sm shadow-emerald-100/50">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 rounded-xl bg-emerald-200 flex items-center justify-center text-emerald-700 font-black">
                  {selectedClient.name?.charAt(0) || 'U'}
                </div>
                <div>
                  <p className="font-black text-emerald-900 leading-tight">{selectedClient.name}</p>
                  <p className="text-[10px] text-emerald-600 font-black uppercase tracking-wider">
                    Deuda: ${(selectedClient.currentDebt || 0).toLocaleString()}
                  </p>
                </div>
              </div>
              <button onClick={() => setSelectedClient(null)} className="text-[10px] font-black text-rose-600 bg-white px-3 py-1.5 rounded-lg border border-rose-100 shadow-sm hover:bg-rose-50 transition-colors uppercase tracking-widest">Cambiar</button>
            </div>
          )}
        </div>
      </div>

      <div className="w-full lg:w-[420px] flex flex-col h-full gap-6">
        <div className="flex-1 bg-white rounded-[2.5rem] border border-slate-200 flex flex-col overflow-hidden shadow-2xl">
          <div className="p-6 bg-slate-50 border-b border-slate-200 flex items-center justify-between">
            <h3 className="font-black text-slate-800 flex items-center gap-2 uppercase tracking-widest text-xs">
              <ShoppingCart size={18} className="text-blue-600" /> Detalle de Compra
            </h3>
            <span className="text-xs font-black bg-blue-600 text-white px-3 py-1 rounded-full">{cart.length}</span>
          </div>

          <div className="flex-1 overflow-y-auto p-6 space-y-6">
            {cart.map(item => {
              const productInfo = products.find(p => p.id === item.productId);
              const isOverstock = productInfo && item.quantity > productInfo.stock;

              return (
                <div key={item.productId} className="flex items-start justify-between group animate-in slide-in-from-right-4 duration-300">
                  <div className="flex-1 pr-2">
                    <p className="text-sm font-black text-slate-800 leading-tight mb-0.5">{item.name}</p>
                    <p className="text-xs text-slate-500 font-bold">${item.price.toLocaleString()} c/u</p>
                    {isOverstock && (
                      <p className="text-[10px] font-black text-amber-500 flex items-center gap-1 mt-1 bg-amber-50 px-2 py-0.5 rounded border border-amber-100 animate-pulse">
                        <AlertTriangle size={10} /> ¡Cantidad excede el stock disponible!
                      </p>
                    )}
                  </div>
                  <div className="flex items-center gap-2 bg-slate-100 rounded-2xl p-1.5 border border-slate-200/50">
                    <button onClick={() => updateQuantity(item.productId, -1)} className="p-1 hover:bg-white hover:text-rose-600 rounded-xl transition-all text-slate-500 shadow-sm"><Minus size={14}/></button>
                    <span className="text-sm font-black w-8 text-center text-slate-800">{item.quantity}</span>
                    <button onClick={() => updateQuantity(item.productId, 1)} className="p-1 hover:bg-white hover:text-emerald-600 rounded-xl transition-all text-slate-500 shadow-sm"><Plus size={14}/></button>
                  </div>
                </div>
              );
            })}
            {cart.length === 0 && (
              <div className="h-full flex flex-col items-center justify-center text-slate-300 py-12">
                <ShoppingCart size={64} className="opacity-10 mb-4" />
                <p className="text-sm font-black text-slate-400 uppercase tracking-widest">Esperando Productos...</p>
              </div>
            )}
          </div>

          <div className="p-8 border-t border-slate-100 bg-slate-50/50 space-y-6">
            <div className="flex items-center justify-between border-t border-slate-200 pt-6">
              <span className="font-black text-slate-400 uppercase tracking-widest text-[10px]">Importe Total</span>
              <span className="font-black text-4xl text-blue-600 tracking-tighter">${total.toLocaleString()}</span>
            </div>

            <div className="space-y-4">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] ml-1">Modalidad de Cobro</p>
              <div className="grid grid-cols-2 gap-4">
                <button 
                  onClick={() => setSaleStatus(SaleStatus.COMPLETED)}
                  className={`flex flex-col items-center justify-center py-5 rounded-[1.5rem] border-2 transition-all shadow-sm ${saleStatus === SaleStatus.COMPLETED ? 'border-blue-600 bg-blue-50 text-blue-700 ring-4 ring-blue-50' : 'border-slate-100 bg-white text-slate-400'}`}
                >
                  <Wallet size={24} className="mb-2" />
                  <span className="text-[10px] font-black uppercase tracking-wider">De Contado</span>
                </button>
                <button 
                  onClick={() => setSaleStatus(SaleStatus.CREDIT)}
                  className={`flex flex-col items-center justify-center py-5 rounded-[1.5rem] border-2 transition-all shadow-sm ${saleStatus === SaleStatus.CREDIT ? 'border-amber-500 bg-amber-50 text-amber-700 ring-4 ring-amber-50' : 'border-slate-100 bg-white text-slate-400'}`}
                >
                  <CreditCard size={24} className="mb-2" />
                  <span className="text-[10px] font-black uppercase tracking-wider">A Crédito</span>
                </button>
              </div>
            </div>

            {saleStatus === SaleStatus.CREDIT && (
              <div className="space-y-2 animate-in slide-in-from-top-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Abono Inicial</label>
                <div className="relative">
                  <span className="absolute left-4 top-1/2 -translate-y-1/2 font-bold text-slate-400">$</span>
                  <input 
                    type="number" 
                    placeholder="0.00" 
                    className="w-full pl-8 pr-4 py-4 bg-white border border-slate-200 rounded-2xl text-lg font-black shadow-inner focus:ring-2 focus:ring-amber-500 outline-none"
                    value={amountPaid}
                    onChange={(e) => setAmountPaid(e.target.value)}
                  />
                </div>
              </div>
            )}

            <button 
              onClick={handleProcessSale}
              disabled={cart.length === 0}
              className="w-full bg-blue-600 hover:bg-blue-700 disabled:bg-slate-200 disabled:text-slate-400 text-white py-6 rounded-2xl font-black text-xl transition-all shadow-2xl shadow-blue-200 active:scale-95 uppercase tracking-widest"
            >
              Registrar Transacción
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default SalesView;

import { supabase } from '../supabaseClient';
import { Product, Client, Sale, Expense, SaleStatus } from '../types';

export const dbService = {
  // Productos
  async getProducts(): Promise<Product[]> {
    const { data, error } = await supabase
      .from('products')
      .select('*')
      .order('name', { ascending: true });

    if (error) throw error;
    return (data || []).map(p => ({
      id: p.id,
      userId: p.user_id,
      name: p.name,
      price: p.price,
      cost: p.cost,
      stock: p.stock,
      barcode: p.barcode,
      category: p.category
    }));
  },

  async saveProduct(product: Partial<Product>, isNew: boolean = false) {
    const { data: userData } = await supabase.auth.getUser();
    if (!userData.user) throw new Error("No autenticado");

    const productData = { 
      id: product.id || crypto.randomUUID(),
      name: product.name,
      price: product.price,
      cost: product.cost,
      stock: product.stock,
      barcode: product.barcode,
      category: product.category,
      user_id: userData.user.id 
    };

    const { error: productError } = await supabase
      .from('products')
      .upsert(productData);

    if (productError) throw productError;

    // Si es un producto nuevo y tiene stock, registramos el gasto inicial
    if (isNew && product.stock && product.stock > 0 && product.cost) {
      const totalCost = product.stock * product.cost;
      const { error: expenseError } = await supabase.from('expenses').insert({
        user_id: userData.user.id,
        description: `Inversión Inicial: ${product.name} (${product.stock} uds)`,
        amount: totalCost,
        date: new Date().toISOString()
      });
      if (expenseError) console.error("Error registrando gasto inicial:", expenseError);
    }
  },

  async updateStockAndRecordExpense(productId: string, quantityToAdd: number, cost: number, productName: string) {
    const { data: userData } = await supabase.auth.getUser();
    if (!userData.user) throw new Error("No autenticado");

    const { data: prod, error: fetchError } = await supabase
      .from('products')
      .select('stock')
      .eq('id', productId)
      .single();

    if (fetchError || !prod) throw new Error("Producto no encontrado");

    const { error: updateError } = await supabase
      .from('products')
      .update({ 
        stock: prod.stock + quantityToAdd,
        cost: cost 
      })
      .eq('id', productId);

    if (updateError) throw updateError;

    const totalCost = quantityToAdd * cost;
    const { error: expenseError } = await supabase.from('expenses').insert({
      user_id: userData.user.id,
      description: `Reposición Stock: ${productName} (+${quantityToAdd} uds)`,
      amount: totalCost,
      date: new Date().toISOString()
    });

    if (expenseError) throw expenseError;
  },

  async deleteProduct(id: string) {
    const { error } = await supabase
      .from('products')
      .delete()
      .eq('id', id);
    if (error) throw error;
  },

  // Clientes
  async getClients(): Promise<Client[]> {
    const { data, error } = await supabase
      .from('clients')
      .select('*');
    if (error) throw error;
    return (data || []).map(c => ({
      id: c.id,
      userId: c.user_id,
      name: c.name,
      phone: c.phone || '',
      email: c.email || '',
      currentDebt: c.current_debt || 0
    }));
  },

  async saveClient(client: Partial<Client>): Promise<Client> {
    const { data: userData } = await supabase.auth.getUser();
    const { error, data } = await supabase
      .from('clients')
      .upsert({ 
        id: client.id || crypto.randomUUID(),
        name: client.name,
        phone: client.phone || '',
        email: client.email || '',
        current_debt: client.currentDebt || 0,
        user_id: userData.user?.id 
      })
      .select()
      .single();

    if (error) throw error;

    return {
      id: data.id,
      userId: data.user_id,
      name: data.name,
      phone: data.phone || '',
      email: data.email || '',
      currentDebt: data.current_debt || 0
    };
  },

  async deleteClient(id: string) {
    const { error } = await supabase.from('clients').delete().eq('id', id);
    if (error) throw error;
  },

  async addPaymentToClient(clientId: string, amount: number) {
    const { data: client } = await supabase.from('clients').select('current_debt').eq('id', clientId).single();
    if (client) {
      await supabase.from('clients').update({ current_debt: Math.max(0, client.current_debt - amount) }).eq('id', clientId);
    }
  },

  async processDistributedAbono(clientId: string, totalAmount: number, saleIds: string[]) {
    const { data: sales, error: fetchError } = await supabase
      .from('sales')
      .select('*')
      .in('id', saleIds)
      .order('date', { ascending: true });

    if (fetchError) throw fetchError;

    let remainingPayment = totalAmount;

    for (const sale of sales) {
      if (remainingPayment <= 0) break;

      const pending = sale.total - sale.amount_paid;
      const paymentToApply = Math.min(remainingPayment, pending);
      const newAmountPaid = sale.amount_paid + paymentToApply;
      const newStatus = newAmountPaid >= sale.total ? SaleStatus.COMPLETED : SaleStatus.CREDIT;

      const { error: updateError } = await supabase
        .from('sales')
        .update({
          amount_paid: newAmountPaid,
          status: newStatus
        })
        .eq('id', sale.id);

      if (updateError) throw updateError;
      remainingPayment -= paymentToApply;
    }

    const { data: client } = await supabase.from('clients').select('current_debt').eq('id', clientId).single();
    if (client) {
      await supabase.from('clients').update({ 
        current_debt: Math.max(0, client.current_debt - totalAmount) 
      }).eq('id', clientId);
    }
  },

  // Ventas
  async getSales(): Promise<Sale[]> {
    const { data, error } = await supabase
      .from('sales')
      .select('*')
      .order('date', { ascending: false });

    if (error) throw error;
    return (data || []).map(s => ({
      id: s.id,
      userId: s.user_id,
      clientId: s.client_id,
      items: s.items || [],
      total: s.total,
      date: s.date,
      status: s.status,
      amountPaid: s.amount_paid
    }));
  },

  async createSale(sale: Partial<Sale>) {
    const { data: userData } = await supabase.auth.getUser();

    const { data: newSale, error: saleError } = await supabase
      .from('sales')
      .insert({
        user_id: userData.user?.id,
        client_id: sale.clientId,
        total: sale.total,
        amount_paid: sale.amountPaid,
        status: sale.status,
        items: sale.items
      })
      .select()
      .single();

    if (saleError) throw saleError;

    for (const item of sale.items || []) {
      const { data: prod } = await supabase.from('products').select('stock').eq('id', item.productId).single();
      if (prod) {
        await supabase.from('products').update({ stock: prod.stock - item.quantity }).eq('id', item.productId);
      }
    }

    if (sale.status === SaleStatus.CREDIT && sale.clientId) {
      const pending = (sale.total || 0) - (sale.amountPaid || 0);
      const { data: client } = await supabase.from('clients').select('current_debt').eq('id', sale.clientId).single();
      if (client) {
        await supabase.from('clients').update({ current_debt: client.current_debt + pending }).eq('id', sale.clientId);
      }
    }

    return newSale;
  },

  async deleteSale(saleId: string) {
    const { data: sale } = await supabase.from('sales').select('*').eq('id', saleId).single();
    if (!sale) return;

    for (const item of sale.items || []) {
      const { data: prod } = await supabase.from('products').select('stock').eq('id', item.productId).single();
      if (prod) {
        await supabase.from('products').update({ stock: prod.stock + item.quantity }).eq('id', item.productId);
      }
    }

    if (sale.status === SaleStatus.CREDIT && sale.client_id) {
      const pending = sale.total - sale.amount_paid;
      const { data: client } = await supabase.from('clients').select('current_debt').eq('id', sale.client_id).single();
      if (client) {
        await supabase.from('clients').update({ current_debt: Math.max(0, client.current_debt - pending) }).eq('id', sale.client_id);
      }
    }

    const { error } = await supabase.from('sales').delete().eq('id', saleId);
    if (error) throw error;
  },

  // Egresos / Gastos
  async getExpenses(): Promise<Expense[]> {
    const { data, error } = await supabase.from('expenses').select('*').order('date', { ascending: false });
    if (error) throw error;
    return (data || []).map(e => ({
      id: e.id,
      userId: e.user_id,
      amount: e.amount,
      description: e.description,
      date: e.date
    }));
  },

  async saveExpense(expense: Partial<Expense>) {
    const { data: userData } = await supabase.auth.getUser();
    if (!userData.user) throw new Error("No autenticado");

    const expenseData = {
      description: expense.description,
      amount: expense.amount,
      user_id: userData.user.id,
      date: expense.date || new Date().toISOString()
    };

    if (expense.id) {
      const { error } = await supabase
        .from('expenses')
        .update(expenseData)
        .eq('id', expense.id);
      if (error) throw error;
    } else {
      const { error } = await supabase
        .from('expenses')
        .insert(expenseData);
      if (error) throw error;
    }
  },

  async deleteExpense(id: string) {
    const { error } = await supabase.from('expenses').delete().eq('id', id);
    if (error) throw error;
  }
};

import React, { useState, useMemo, useEffect } from 'react';
import { dbService } from '../services/dbService';
import { Product } from '../types';
import { Plus, Search, Filter, Edit2, Trash2, Camera, Package, RefreshCw, Loader2, Calculator, X } from 'lucide-react';

const InventoryView: React.FC = () => {
  const [products, setProducts] = useState<Product[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isReplenishOpen, setIsReplenishOpen] = useState(false);
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);
  const [loading, setLoading] = useState(false);

  // Estados compartidos para calculadoras (Reposición y Nuevo Item)
  const [calcQty, setCalcQty] = useState<number>(0);
  const [calcUnitCost, setCalcUnitCost] = useState<number>(0);
  const [calcTotalCost, setCalcTotalCost] = useState<number>(0);

  useEffect(() => {
    dbService.getProducts().then(setProducts).catch(console.error);
  }, []);

  // Limpiar estados de calculadora al abrir modal de nuevo producto
  useEffect(() => {
    if (isModalOpen && !editingProduct) {
      setCalcQty(0);
      setCalcUnitCost(0);
      setCalcTotalCost(0);
    } else if (isModalOpen && editingProduct) {
      setCalcQty(editingProduct.stock);
      setCalcUnitCost(editingProduct.cost);
      setCalcTotalCost(editingProduct.stock * editingProduct.cost);
    }
  }, [isModalOpen, editingProduct]);

  // Limpiar estados al abrir modal de reposición
  useEffect(() => {
    if (editingProduct && isReplenishOpen) {
      setCalcUnitCost(editingProduct.cost);
      setCalcQty(0);
      setCalcTotalCost(0);
    }
  }, [editingProduct, isReplenishOpen]);

  const filteredProducts = useMemo(() => {
    return products.filter(p => 
      p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
      (p.barcode && p.barcode.includes(searchTerm))
    );
  }, [products, searchTerm]);

  // Lógica de cálculo automática
  const handleQtyChange = (qty: number) => {
    setCalcQty(qty);
    if (calcUnitCost > 0) {
      setCalcTotalCost(Number((calcUnitCost * qty).toFixed(2)));
    } else if (calcTotalCost > 0 && qty > 0) {
      setCalcUnitCost(Number((calcTotalCost / qty).toFixed(2)));
    }
  };

  const handleUnitCostChange = (unit: number) => {
    setCalcUnitCost(unit);
    if (calcQty > 0) {
      setCalcTotalCost(Number((unit * calcQty).toFixed(2)));
    }
  };

  const handleTotalCostChange = (total: number) => {
    setCalcTotalCost(total);
    if (calcQty > 0) {
      setCalcUnitCost(Number((total / calcQty).toFixed(2)));
    }
  };

  const handleSaveProduct = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setLoading(true);
    const formData = new FormData(e.currentTarget);
    const isNew = !editingProduct;

    const productData: Partial<Product> = {
      id: editingProduct?.id || crypto.randomUUID(),
      name: formData.get('name') as string,
      barcode: formData.get('barcode') as string,
      category: formData.get('category') as string,
      price: Number(formData.get('price')),
      cost: calcUnitCost, // Usamos el valor de la calculadora
      stock: calcQty,     // Usamos el valor de la calculadora
    };

    try {
      await dbService.saveProduct(productData, isNew);
      const updated = await dbService.getProducts();
      setProducts(updated);
      setIsModalOpen(false);
      setEditingProduct(null);
      if (isNew && calcQty > 0) alert('¡Producto creado y egreso de inversión registrado!');
    } catch (err) {
      alert("Error al guardar producto");
    } finally {
      setLoading(false);
    }
  };

  const handleReplenishStock = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!editingProduct || calcQty <= 0) return;
    setLoading(true);

    try {
      await dbService.updateStockAndRecordExpense(
        editingProduct.id, 
        calcQty, 
        calcUnitCost, 
        editingProduct.name
      );

      const updated = await dbService.getProducts();
      setProducts(updated);
      setIsReplenishOpen(false);
      setEditingProduct(null);
      alert('¡Stock sumado y egreso registrado con éxito!');
    } catch (err: any) {
      alert("Error al reponer stock: " + err.message);
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (id: string) => {
    if (confirm('¿Estás seguro de eliminar este producto?')) {
      try {
        await dbService.deleteProduct(id);
        const updated = await dbService.getProducts();
        setProducts(updated);
      } catch (err) {
        alert("Error al eliminar producto");
      }
    }
  };

