          .stat-box { border: 1px solid #e2e8f0; padding: 20px; border-radius: 12px; }
          table { width: 100%; border-collapse: collapse; margin-top: 20px; }
          th { background: #f8fafc; text-align: left; padding: 12px; font-size: 10px; text-transform: uppercase; letter-spacing: 0.1em; color: #64748b; }
          td { padding: 12px; border-bottom: 1px solid #f1f5f9; font-size: 12px; }
        </style>
      </head>
      <body class="p-10">
        <div class="report-header flex justify-between items-end">
          <div>
            <h1 class="text-3xl font-black uppercase tracking-tighter">${businessName}</h1>
            <p class="text-slate-500 font-bold uppercase text-[10px] tracking-widest">Reporte Consolidado de Balance</p>
          </div>
          <div class="text-right">
            <p class="text-[10px] font-black uppercase text-slate-400">Fecha de Emisión</p>
            <p class="text-sm font-bold">${new Date().toLocaleString()}</p>
          </div>
        </div>

        <div class="grid grid-cols-3 gap-6 mb-10">
          <div class="stat-box">
            <p class="text-[10px] font-black uppercase text-slate-400 mb-1">Ingresos Totales</p>
            <p class="text-2xl font-black text-blue-600">$${stats.revenue.toLocaleString()}</p>
          </div>
          <div class="stat-box">
            <p class="text-[10px] font-black uppercase text-slate-400 mb-1">Gastos Totales</p>
            <p class="text-2xl font-black text-rose-600">$${stats.expenses.toLocaleString()}</p>
          </div>
          <div class="stat-box bg-slate-900 text-white border-none">
            <p class="text-[10px] font-black uppercase text-slate-400 mb-1">Resultado Neto</p>
            <p class="text-2xl font-black text-emerald-400">$${stats.profit.toLocaleString()}</p>
          </div>
        </div>

        <div class="mb-10">
          <h2 class="text-sm font-black uppercase tracking-widest border-l-4 border-blue-600 pl-3 mb-4">Resumen de Ventas (${period})</h2>
          <table>
