                <th>Concepto</th>
                <th>Estado</th>
                <th class="text-right">Monto</th>
              </tr>
            </thead>
            <tbody>
              ${filteredData.fSales.length > 0 ? filteredData.fSales.map(s => `
                <tr>
                  <td>${new Date(s.date).toLocaleDateString()}</td>
                  <td>Venta #${s.id.slice(0, 8)}</td>
                  <td>${s.status}</td>
                  <td class="text-right font-bold">$${s.total.toLocaleString()}</td>
                </tr>
              `).join('') : '<tr><td colspan="4" class="text-center py-4 text-slate-400">No hay movimientos</td></tr>'}
            </tbody>
          </table>
        </div>

        <div>
          <h2 class="text-sm font-black uppercase tracking-widest border-l-4 border-rose-600 pl-3 mb-4">Resumen de Gastos (${period})</h2>
          <table>
            <thead>
              <tr>
                <th>Fecha</th>
                <th>Descripción</th>
                <th class="text-right">Monto</th>
              </tr>
            </thead>
            <tbody>
              ${filteredData.fExpenses.length > 0 ? filteredData.fExpenses.map(e => `
                <tr>
                  <td>${new Date(e.date).toLocaleDateString()}</td>
                  <td>${e.description}</td>
                  <td class="text-right font-bold text-rose-600">$${e.amount.toLocaleString()}</td>
                </tr>
              `).join('') : '<tr><td colspan="3" class="text-center py-4 text-slate-400">No hay egresos registrados</td></tr>'}
