          </table>
        </div>

        <div class="mt-20 pt-10 border-t border-slate-100 flex justify-between items-center opacity-50">
          <p class="text-[9px] font-black uppercase tracking-widest">Sistema de Gestión Caja Pro v1.0</p>
          <p class="text-[9px] font-black uppercase tracking-widest">Copia de Auditoría Interna</p>
        </div>

        <script>
          window.onload = () => {
            setTimeout(() => {
              window.print();
              // window.close(); // Opcional: cerrar después de imprimir
            }, 500);
          };
        </script>
      </body>
      </html>
    `;

    printWindow.document.write(htmlContent);
    printWindow.document.close();
  };

  const StatCard = ({ title, value, icon: Icon, color, isProfit }: any) => (
    <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 flex items-start justify-between">
      <div>
        <p className="text-xs font-black text-slate-400 uppercase tracking-widest mb-1">{title}</p>
        <h3 className={`text-2xl font-black ${isProfit && value < 0 ? 'text-rose-600' : 'text-slate-800'}`}>
          ${value.toLocaleString()}
        </h3>
      </div>
      <div className={`p-3 rounded-2xl ${color} shadow-lg shadow-current/10`}>
        <Icon size={24} />
      </div>
    </div>
  );

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-black text-slate-800 tracking-tight">Panel de Control</h1>
          <p className="text-slate-500 font-medium">Análisis de rendimiento: {period.toUpperCase()}</p>
        </div>
        <div className="flex items-center gap-4">
          <button 
            onClick={handlePrintReport}
            className="flex items-center gap-2 bg-slate-900 text-white px-6 py-3 rounded-2xl text-xs font-black uppercase tracking-widest hover:bg-slate-800 transition-all shadow-xl active:scale-95"
          >
            <Printer size={16} /> Ver Balance Imprimible
          </button>
          <div className="flex bg-white p-1 rounded-xl border border-slate-200 shadow-sm">
            {(['semana', 'mes', 'año'] as DashboardPeriod[]).map(p => (
              <button 
                key={p}
                onClick={() => setPeriod(p)}
                className={`px-5 py-2 text-xs font-black uppercase tracking-widest rounded-lg transition-all ${period === p ? 'bg-blue-600 text-white shadow-lg shadow-blue-200' : 'text-slate-400 hover:text-slate-600'}`}
              >
                {p}
              </button>
            ))}
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard title="Ingresos" value={stats.revenue} icon={DollarSign} color="bg-blue-50 text-blue-600" />
        <StatCard title="Egresos" value={stats.expenses} icon={TrendingDown} color="bg-rose-50 text-rose-600" />
        <StatCard title="Ganancia Neta" value={stats.profit} icon={PieChart} color="bg-emerald-50 text-emerald-600" isProfit={true} />
        <StatCard title="Deuda Clientes" value={stats.pendingCredits} icon={Users} color="bg-amber-50 text-amber-600" />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 bg-white p-8 rounded-3xl border border-slate-100 shadow-sm">
          <h3 className="text-sm font-black text-slate-800 uppercase tracking-widest mb-8 flex items-center gap-2">
             <TrendingDown className="text-blue-600" size={18} /> Tendencia del Periodo
          </h3>
          <div className="h-80 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={useMemo(() => {
                const days = period === 'semana' ? 7 : period === 'mes' ? 30 : 12;
                const data = [];
                for (let i = days; i >= 0; i--) {
                  const d = new Date();
                  if (period === 'año') d.setMonth(d.getMonth() - i);
                  else d.setDate(d.getDate() - i);
                  data.push({
                    name: period === 'año' ? d.toLocaleString('es-VE', { month: 'short' }) : d.toISOString().split('T')[0].slice(5),
                    ventas: sales.filter(s => new Date(s.date).toDateString() === d.toDateString()).reduce((acc, s) => acc + s.total, 0),
                    gastos: expenses.filter(e => new Date(e.date).toDateString() === d.toDateString()).reduce((acc, e) => acc + e.amount, 0)
                  });
                }
                return data;
              }, [sales, expenses, period])}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
