import React, { useState, useMemo, useEffect, useRef } from 'react';
import { dbService } from '../services/dbService';
import { Product } from '../types';
import { Plus, Search, Filter, Edit2, Trash2, Camera, Package, RefreshCw, Loader2, Calculator, X, AlertTriangle, ChevronDown } from 'lucide-react';

const InventoryView: React.FC = () => {
  const [products, setProducts] = useState<Product[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isReplenishOpen, setIsReplenishOpen] = useState(false);
  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);
  const [productToDelete, setProductToDelete] = useState<Product | null>(null);
  const [loading, setLoading] = useState(false);

  // Estados para categorías
  const [categoryInput, setCategoryInput] = useState('');
  const [showCategorySuggestions, setShowCategorySuggestions] = useState(false);
  const categoryRef = useRef<HTMLDivElement>(null);

  // Estados compartidos para calculadoras
  const [calcQty, setCalcQty] = useState<number>(0);
  const [calcUnitCost, setCalcUnitCost] = useState<number>(0);
  const [calcTotalCost, setCalcTotalCost] = useState<number>(0);

  useEffect(() => {
    dbService.getProducts().then(setProducts).catch(console.error);

    // Cerrar sugerencias al hacer clic fuera
    const handleClickOutside = (event: MouseEvent) => {
      if (categoryRef.current && !categoryRef.current.contains(event.target as Node)) {
        setShowCategorySuggestions(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  useEffect(() => {
    if (isModalOpen) {
      if (editingProduct) {
        setCalcQty(editingProduct.stock);
        setCalcUnitCost(editingProduct.cost);
        setCalcTotalCost(Number((editingProduct.stock * editingProduct.cost).toFixed(2)));
        setCategoryInput(editingProduct.category || '');
      } else {
        setCalcQty(0);
        setCalcUnitCost(0);
        setCalcTotalCost(0);
        setCategoryInput('');
      }
    }
  }, [isModalOpen, editingProduct]);

  useEffect(() => {
    if (isReplenishOpen && editingProduct) {
      setCalcUnitCost(editingProduct.cost);
      setCalcQty(0);
      setCalcTotalCost(0);
    }
  }, [isReplenishOpen, editingProduct]);

  const uniqueCategories = useMemo(() => {
    const cats = products.map(p => p.category).filter(Boolean);
    return Array.from(new Set(cats)).sort();
  }, [products]);

  const filteredCategories = useMemo(() => {
    if (!categoryInput) return uniqueCategories;
    return uniqueCategories.filter(c => 
      c.toLowerCase().includes(categoryInput.toLowerCase())
    );
  }, [uniqueCategories, categoryInput]);

  const filteredProducts = useMemo(() => {
    return products.filter(p => 
      p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
      (p.barcode && p.barcode.includes(searchTerm))
    );
  }, [products, searchTerm]);

  const handleQtyChange = (qty: number) => {
    setCalcQty(qty);
    if (qty > 0) {
      if (calcUnitCost > 0) setCalcTotalCost(Number((calcUnitCost * qty).toFixed(2)));
      else if (calcTotalCost > 0) setCalcUnitCost(Number((calcTotalCost / qty).toFixed(2)));
    }
  };

  const handleUnitCostChange = (unit: number) => {
    setCalcUnitCost(unit);
    if (calcQty > 0) setCalcTotalCost(Number((unit * calcQty).toFixed(2)));
  };

  const handleTotalCostChange = (total: number) => {
    setCalcTotalCost(total);
    if (calcQty > 0) setCalcUnitCost(Number((total / calcQty).toFixed(2)));
  };

  const handleSaveProduct = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setLoading(true);
    const formData = new FormData(e.currentTarget);
    const isNew = !editingProduct;

    const productData: Partial<Product> = {
      id: editingProduct?.id || crypto.randomUUID(),
      name: formData.get('name') as string,
      barcode: (formData.get('barcode') as string) || '',
      category: categoryInput || 'General',
      price: Number(formData.get('price')),
      cost: calcUnitCost,
      stock: calcQty,
    };

    try {
      await dbService.saveProduct(productData, isNew);
      const updated = await dbService.getProducts();
      setProducts(updated);
      setIsModalOpen(false);
      setEditingProduct(null);
    } catch (err) {
      alert("Error al guardar producto");
    } finally {
      setLoading(false);
    }
  };

  const handleReplenishStock = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!editingProduct || calcQty <= 0) return;
    setLoading(true);

    try {
      await dbService.updateStockAndRecordExpense(
        editingProduct.id, 
        calcQty, 
        calcUnitCost, 
        editingProduct.name
      );
      const updated = await dbService.getProducts();
      setProducts(updated);
      setIsReplenishOpen(false);
      setEditingProduct(null);
    } catch (err: any) {
      alert("Error al reponer stock: " + err.message);
    } finally {
      setLoading(false);
    }
  };

  const confirmDeleteProduct = async () => {
    if (!productToDelete) return;
    setLoading(true);
    try {
      await dbService.deleteProduct(productToDelete.id);
      const updated = await dbService.getProducts();
      setProducts(updated);
      setIsDeleteModalOpen(false);
      setProductToDelete(null);
    } catch (err) {
      alert("Error al eliminar producto");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-black text-slate-800 tracking-tight">Inventario Global</h1>
          <p className="text-slate-500 font-medium">Control total de stock y costos base.</p>
        </div>
        <button 
          onClick={() => { setEditingProduct(null); setIsModalOpen(true); }}
          className="bg-blue-600 hover:bg-blue-700 text-white px-6 py-3 rounded-2xl font-black text-sm uppercase tracking-widest flex items-center justify-center gap-2 shadow-xl shadow-blue-200 transition-all active:scale-95"
        >
          <Plus size={18} /> Nuevo Item
        </button>
      </div>

      <div className="flex flex-col md:flex-row gap-4">
        <div className="relative flex-1">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
          <input 
            type="text" 
            placeholder="Buscar por nombre o EAN-13..." 
            className="w-full pl-12 pr-4 py-4 bg-white border border-slate-200 rounded-2xl focus:ring-2 focus:ring-blue-500 transition-all font-medium shadow-sm outline-none"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
      </div>

      <div className="bg-white border border-slate-200 rounded-[2rem] overflow-hidden shadow-xl">
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-slate-50 text-slate-400 text-[10px] font-black uppercase tracking-[0.2em]">
                <th className="px-8 py-6">Producto & Código</th>
                <th className="px-8 py-6">Costo / P.Venta</th>
                <th className="px-8 py-6">Inventario</th>
                <th className="px-8 py-6">Acciones</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredProducts.map((p) => (
                <tr key={p.id} className="hover:bg-slate-50/80 transition-all group">
                  <td className="px-8 py-6">
                    <div>
                      <p className="font-black text-slate-800">{p.name}</p>
                      <p className="text-[10px] text-slate-400 font-black uppercase tracking-wider flex items-center gap-1">
                        <Camera size={10} /> {p.barcode || 'SIN EAN'} • {p.category}
                      </p>
                    </div>
                  </td>
                  <td className="px-8 py-6">
                    <div className="flex flex-col">
                      <span className="text-xs font-bold text-slate-400">C: ${p.cost.toLocaleString()}</span>
                      <span className="text-sm font-black text-blue-600">V: ${p.price.toLocaleString()}</span>
                    </div>
                  </td>
                  <td className="px-8 py-6">
                    <div className="flex items-center gap-3">
                      <div className={`w-2.5 h-2.5 rounded-full ${p.stock <= 5 ? 'bg-rose-500 animate-pulse' : 'bg-emerald-500'}`} />
                      <span className={`text-sm font-black ${p.stock <= 5 ? 'text-rose-600' : 'text-slate-800'}`}>
                        {p.stock} uds
                      </span>
                    </div>
                  </td>
                  <td className="px-8 py-6">
                    <div className="flex items-center gap-2">
                      <button 
                        onClick={() => { setEditingProduct(p); setIsReplenishOpen(true); }}
                        className="p-2.5 text-blue-600 bg-blue-50 hover:bg-blue-100 rounded-xl transition-all"
                        title="Reponer Stock"
                      >
                        <RefreshCw size={16} />
                      </button>
                      <button 
                        onClick={() => { setEditingProduct(p); setIsModalOpen(true); }}
                        className="p-2.5 text-slate-400 hover:text-slate-900 bg-slate-50 hover:bg-slate-100 rounded-xl transition-all"
                      >
                        <Edit2 size={16} />
                      </button>
                      <button 
                        onClick={() => { setProductToDelete(p); setIsDeleteModalOpen(true); }}
                        className="p-2.5 text-rose-300 hover:text-rose-600 hover:bg-rose-50 rounded-xl transition-all"
                      >
                        <Trash2 size={16} />
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* Modal Confirmación Borrado Estilizado */}
      {isDeleteModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-md" onClick={() => setIsDeleteModalOpen(false)} />
          <div className="relative bg-white w-full max-w-sm rounded-[2.5rem] p-8 shadow-2xl text-center animate-in zoom-in-95 duration-200">
            <div className="w-20 h-20 bg-rose-50 text-rose-600 rounded-3xl flex items-center justify-center mx-auto mb-6 shadow-inner ring-8 ring-rose-50/50">
              <AlertTriangle size={40} />
            </div>
            <h3 className="text-2xl font-black text-slate-800 tracking-tight mb-2">¿Eliminar Producto?</h3>
            <p className="text-slate-500 font-medium mb-8">
              Estás por borrar <span className="font-black text-slate-800">"{productToDelete?.name}"</span>. Esta acción no se puede deshacer y afectará el historial de inventario.
            </p>
            <div className="flex flex-col gap-3">
              <button 
                onClick={confirmDeleteProduct}
                disabled={loading}
                className="w-full bg-rose-600 hover:bg-rose-700 text-white py-4 rounded-2xl font-black text-lg shadow-xl shadow-rose-100 flex items-center justify-center gap-2 transition-all active:scale-95"
              >
                {loading ? <Loader2 className="animate-spin" /> : 'Sí, Eliminar Permanentemente'}
              </button>
              <button 
                onClick={() => { setIsDeleteModalOpen(false); setProductToDelete(null); }}
                className="w-full bg-slate-100 hover:bg-slate-200 text-slate-600 py-4 rounded-2xl font-black text-sm uppercase tracking-widest transition-all"
              >
                Cancelar
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Modal Nuevo/Editar */}
      {isModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/40 backdrop-blur-sm" onClick={() => setIsModalOpen(false)} />
          <div className="relative bg-white w-full max-w-2xl rounded-[2.5rem] shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200 max-h-[95vh] flex flex-col">
            <div className="px-8 py-6 border-b border-slate-100 flex items-center justify-between bg-slate-50/50">
              <h3 className="text-lg font-black text-slate-800 uppercase tracking-tight">{editingProduct ? 'Modificar Item' : 'Nuevo Producto'}</h3>
              <button onClick={() => setIsModalOpen(false)} className="p-2 text-slate-400 hover:text-slate-600"><X size={24} /></button>
            </div>
            <form onSubmit={handleSaveProduct} className="p-8 space-y-6 overflow-y-auto hide-scrollbar">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-4">
                  <div className="space-y-1">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Nombre Comercial</label>
                    <input name="name" defaultValue={editingProduct?.name} required className="w-full px-5 py-4 bg-slate-50 border border-slate-200 rounded-2xl outline-none font-bold" />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Código de Barras (EAN-13)</label>
                    <div className="relative">
                      <Camera className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" size={18} />
                      <input name="barcode" defaultValue={editingProduct?.barcode} className="w-full pl-12 pr-4 py-4 bg-slate-50 border border-slate-200 rounded-2xl outline-none font-bold shadow-sm" placeholder="Escanea o escribe..." />
                    </div>
                  </div>

                  {/* Campo Categoría con Sugerencias */}
                  <div className="space-y-1 relative" ref={categoryRef}>
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Categoría</label>
                    <div className="relative">
                      <input 
                        type="text"
                        value={categoryInput}
                        onChange={(e) => {
                          setCategoryInput(e.target.value);
                          setShowCategorySuggestions(true);
                        }}
                        onFocus={() => setShowCategorySuggestions(true)}
                        className="w-full px-5 py-4 bg-slate-50 border border-slate-200 rounded-2xl outline-none font-bold pr-10"
                        placeholder="Ej: Víveres, Bebidas..."
                      />
                      <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-300" size={16} />
                    </div>

                    {/* Lista de Sugerencias */}
                    {showCategorySuggestions && filteredCategories.length > 0 && (
                      <div className="absolute z-[60] left-0 right-0 top-full mt-1 bg-white border border-slate-200 rounded-2xl shadow-2xl max-h-48 overflow-y-auto overflow-hidden animate-in fade-in slide-in-from-top-2 duration-200">
                        {filteredCategories.map((cat, idx) => (
                          <button
                            key={idx}
                            type="button"
                            onClick={() => {
                              setCategoryInput(cat);
                              setShowCategorySuggestions(false);
                            }}
                            className="w-full px-5 py-3 text-left hover:bg-blue-50 text-sm font-bold text-slate-700 transition-colors flex items-center justify-between group"
                          >
                            <span>{cat}</span>
                            <span className="text-[10px] font-black uppercase text-blue-600 opacity-0 group-hover:opacity-100">Seleccionar</span>
                          </button>
                        ))}
                      </div>
                    )}
                  </div>

                  <div className="space-y-1">
                    <label className="text-[10px] font-black text-blue-600 uppercase tracking-widest">Precio Venta ($)</label>
                    <input name="price" type="number" step="0.01" defaultValue={editingProduct?.price} required className="w-full px-5 py-4 bg-blue-50 border border-blue-100 rounded-2xl outline-none font-black text-xl text-blue-600" />
                  </div>
                </div>
                <div className="space-y-4 bg-slate-50 p-6 rounded-[2rem] border border-slate-100">
                  <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 flex items-center gap-2"><Calculator size={14}/> Costos e Inversión</h4>
                  <div className="space-y-1">
                    <label className="text-[10px] font-black text-slate-700 uppercase tracking-widest">Stock Inicial</label>
                    <input type="number" required className="w-full px-5 py-3 bg-white border border-slate-200 rounded-xl outline-none font-black" value={calcQty || ''} onChange={(e) => handleQtyChange(Number(e.target.value))} />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-black text-slate-700 uppercase tracking-widest">Costo Unitario ($)</label>
                    <input type="number" step="0.01" className="w-full px-5 py-3 bg-white border border-slate-200 rounded-xl outline-none font-black" value={calcUnitCost || ''} onChange={(e) => handleUnitCostChange(Number(e.target.value))} />
                  </div>
                  <div className="text-center text-[10px] font-black text-slate-300 uppercase">Ó</div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-black text-slate-700 uppercase tracking-widest">Costo Total Compra ($)</label>
                    <input type="number" step="0.01" className="w-full px-5 py-3 bg-white border border-slate-200 rounded-xl outline-none font-black" value={calcTotalCost || ''} onChange={(e) => handleTotalCostChange(Number(e.target.value))} />
                  </div>
                </div>
              </div>
              <button disabled={loading} type="submit" className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black text-lg shadow-xl flex items-center justify-center gap-2 transition-all active:scale-95">
                {loading ? <Loader2 className="animate-spin" /> : (editingProduct ? 'Guardar Cambios' : 'Registrar Producto')}
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default InventoryView;

import React, { useMemo, useState, useEffect } from 'react';
import { 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer, 
  AreaChart, 
  Area,
  BarChart,
  Bar,
  Cell
} from 'recharts';
import { dbService } from '../services/dbService';
import { DollarSign, TrendingDown, Package, Users, FileText, PieChart, Printer, Loader2, ArrowUpRight, BarChart3, Layers } from 'lucide-react';
import { Sale, Expense, Product, Client } from '../types';

type DashboardPeriod = 'semana' | 'mes' | 'año';

const COLORS = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899', '#06b6d4'];

const DashboardView: React.FC = () => {
  const [sales, setSales] = useState<Sale[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [clients, setClients] = useState<Client[]>([]);
  const [period, setPeriod] = useState<DashboardPeriod>('semana');

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [s, e, p, c] = await Promise.all([
          dbService.getSales(),
          dbService.getExpenses(),
          dbService.getProducts(),
          dbService.getClients()
        ]);
        setSales(s);
        setExpenses(e);
        setProducts(p);
        setClients(c);
      } catch (err) {
        console.error("Error fetching dashboard data:", err);
      }
    };
    fetchData();
  }, []);

  const filteredData = useMemo(() => {
    const now = new Date();
    let startDate = new Date();

    if (period === 'semana') startDate.setDate(now.getDate() - 7);
    else if (period === 'mes') startDate.setMonth(now.getMonth() - 1);
    else if (period === 'año') startDate.setFullYear(now.getFullYear() - 1);

    const fSales = sales.filter(s => new Date(s.date) >= startDate);
    const fExpenses = expenses.filter(e => new Date(e.date) >= startDate);

    return { fSales, fExpenses };
  }, [sales, expenses, period]);

  const stats = useMemo(() => {
    const totalRevenue = filteredData.fSales.reduce((acc, s) => acc + (s.amountPaid || 0), 0);
    const totalExpenses = filteredData.fExpenses.reduce((acc, e) => acc + e.amount, 0);
    const netIncome = totalRevenue - totalExpenses;
    const pendingCredits = clients.reduce((acc, c) => acc + c.currentDebt, 0);

    return {
      revenue: totalRevenue,
      expenses: totalExpenses,
      profit: netIncome,
      pendingCredits
    };
  }, [filteredData, clients]);

  // Cálculo de analítica por categorías
  const categoryStats = useMemo(() => {
    const statsMap: Record<string, { category: string, money: number, units: number }> = {};

    // Mapeo rápido de productos para obtener categorías
    const productMap = products.reduce((acc, p) => {
      acc[p.id] = p.category || 'Sin Categoría';
      return acc;
    }, {} as Record<string, string>);

    filteredData.fSales.forEach(sale => {
      sale.items.forEach(item => {
        const category = productMap[item.productId] || 'General';
        if (!statsMap[category]) {
          statsMap[category] = { category, money: 0, units: 0 };
        }
        statsMap[category].money += item.price * item.quantity;
        statsMap[category].units += item.quantity;
      });
    });

    return Object.values(statsMap).sort((a, b) => b.money - a.money);
  }, [filteredData.fSales, products]);

  const handlePrintReport = () => {
    const businessName = localStorage.getItem('cajapro_profile') 
      ? JSON.parse(localStorage.getItem('cajapro_profile')!).businessName 
      : 'Mi Negocio';

    const printWindow = window.open('', '_blank');
    if (!printWindow) return;

    const htmlContent = `
      <!DOCTYPE html>
      <html>
      <head>
        <title>Reporte de Balance Real - ${businessName}</title>
        <script src="https://cdn.tailwindcss.com"></script>
        <style>
          @page { size: A4; margin: 1.5cm; }
          body { font-family: 'Inter', sans-serif; color: #1e293b; background: white; }
          .report-header { border-bottom: 2px solid #e2e8f0; padding-bottom: 20px; margin-bottom: 30px; }
          .stat-card { border: 1px solid #f1f5f9; padding: 15px; border-radius: 12px; background: #f8fafc; }
          table { width: 100%; border-collapse: collapse; margin-top: 15px; }
          th { text-align: left; padding: 10px; font-size: 9px; text-transform: uppercase; color: #64748b; border-bottom: 1px solid #e2e8f0; }
          td { padding: 10px; border-bottom: 1px solid #f8fafc; font-size: 11px; }
          .font-black { font-weight: 900; }
        </style>
      </head>
      <body class="p-8">
        <div class="report-header flex justify-between items-start">
          <div>
            <h1 class="text-2xl font-black text-slate-900">${businessName.toUpperCase()}</h1>
            <p class="text-[9px] font-bold text-slate-400 uppercase tracking-[0.2em]">Balance de Caja e Ingresos Reales</p>
          </div>
          <div class="text-right">
            <p class="text-[9px] font-black text-slate-400 uppercase">Periodo Analizado: ${period.toUpperCase()}</p>
            <p class="text-xs font-bold">${new Date().toLocaleDateString()}</p>
          </div>
        </div>

        <div class="grid grid-cols-3 gap-4 mb-8">
          <div class="stat-card">
            <p class="text-[8px] font-black text-slate-400 uppercase mb-1">Efectivo Ingresado</p>
            <p class="text-xl font-black text-blue-600">$${stats.revenue.toLocaleString()}</p>
          </div>
          <div class="stat-card">
            <p class="text-[8px] font-black text-slate-400 uppercase mb-1">Gastos Operativos</p>
            <p class="text-xl font-black text-rose-600">$${stats.expenses.toLocaleString()}</p>
          </div>
          <div class="stat-card bg-slate-900 text-white">
            <p class="text-[8px] font-black text-slate-400 uppercase mb-1">Utilidad Real</p>
            <p class="text-xl font-black text-emerald-400">$${stats.profit.toLocaleString()}</p>
          </div>
        </div>

        <div class="mb-8">
          <h2 class="text-xs font-black uppercase tracking-widest border-b border-slate-900 pb-2 mb-4">Rendimiento por Categoría</h2>
          <table>
            <thead>
              <tr>
                <th>Categoría</th>
                <th class="text-right">Unidades Vendidas</th>
                <th class="text-right">Dinero Generado ($)</th>
              </tr>
            </thead>
            <tbody>
              ${categoryStats.map(c => `
                <tr>
                  <td class="font-bold">${c.category}</td>
                  <td class="text-right">${c.units} uds</td>
                  <td class="text-right font-black text-blue-600">$${c.money.toLocaleString()}</td>
                </tr>
              `).join('')}
            </tbody>
          </table>
        </div>

        <div class="mt-20 flex justify-between items-center text-[8px] font-bold text-slate-300 uppercase tracking-[0.3em]">
          <p>Caja Pro v1.0 - Gestión Integral</p>
          <p>Documento de Auditoría Interna</p>
        </div>

        <script>
          window.onload = () => {
            setTimeout(() => {
              window.print();
            }, 500);
          };
        </script>
      </body>
      </html>
    `;

    printWindow.document.write(htmlContent);
    printWindow.document.close();
  };

  const StatCard = ({ title, value, icon: Icon, color, isProfit, subtext }: any) => (
    <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 flex items-start justify-between">
      <div>
        <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">{title}</p>
        <h3 className={`text-2xl font-black ${isProfit && value < 0 ? 'text-rose-600' : 'text-slate-800'}`}>
          ${value.toLocaleString()}
        </h3>
        {subtext && <p className="text-[9px] font-bold text-slate-400 mt-1 uppercase">{subtext}</p>}
      </div>
      <div className={`p-3 rounded-2xl ${color} shadow-lg shadow-current/10`}>
        <Icon size={24} />
      </div>
    </div>
  );

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-12">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-black text-slate-800 tracking-tight">Análisis Estratégico</h1>
          <p className="text-slate-500 font-medium">Contabilizando ingresos reales y rendimiento de inventario.</p>
        </div>
        <div className="flex items-center gap-4">
          <button 
            onClick={handlePrintReport}
            className="flex items-center gap-2 bg-slate-900 text-white px-6 py-3 rounded-2xl text-xs font-black uppercase tracking-widest hover:bg-slate-800 transition-all shadow-xl active:scale-95"
          >
            <Printer size={16} /> Reporte PDF Detallado
          </button>
          <div className="flex bg-white p-1 rounded-xl border border-slate-200 shadow-sm">
            {(['semana', 'mes', 'año'] as DashboardPeriod[]).map(p => (
              <button 
                key={p}
                onClick={() => setPeriod(p)}
                className={`px-5 py-2 text-xs font-black uppercase tracking-widest rounded-lg transition-all ${period === p ? 'bg-blue-600 text-white shadow-lg shadow-blue-200' : 'text-slate-400 hover:text-slate-600'}`}
              >
                {p}
              </button>
            ))}
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard title="Ingresos Reales" value={stats.revenue} icon={DollarSign} color="bg-blue-50 text-blue-600" subtext="Cobro Efectivo" />
        <StatCard title="Gastos Operativos" value={stats.expenses} icon={TrendingDown} color="bg-rose-50 text-rose-600" subtext="Compras y Salidas" />
        <StatCard title="Utilidad Liquida" value={stats.profit} icon={PieChart} color="bg-emerald-50 text-emerald-600" isProfit={true} subtext="Cash Flow Neto" />
        <StatCard title="Cartera Clientes" value={stats.pendingCredits} icon={Users} color="bg-amber-50 text-amber-600" subtext="Cuentas por Cobrar" />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm relative overflow-hidden">
          <div className="absolute top-0 right-0 p-8">
             <ArrowUpRight className="text-slate-100" size={120} />
          </div>
          <h3 className="text-sm font-black text-slate-800 uppercase tracking-widest mb-8 flex items-center gap-2 relative z-10">
             <TrendingDown className="text-blue-600" size={18} /> Tendencia de Cobro Real
          </h3>
          <div className="h-80 w-full relative z-10">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={useMemo(() => {
                const days = period === 'semana' ? 7 : period === 'mes' ? 30 : 12;
                const data = [];
                for (let i = days; i >= 0; i--) {
                  const d = new Date();
                  if (period === 'año') d.setMonth(d.getMonth() - i);
                  else d.setDate(d.getDate() - i);

                  const daySales = sales.filter(s => new Date(s.date).toDateString() === d.toDateString());
                  const dayExpenses = expenses.filter(e => new Date(e.date).toDateString() === d.toDateString());

                  data.push({
                    name: period === 'año' ? d.toLocaleString('es-VE', { month: 'short' }) : d.toISOString().split('T')[0].slice(5),
                    ingresos: daySales.reduce((acc, s) => acc + (s.amountPaid || 0), 0),
                    gastos: dayExpenses.reduce((acc, e) => acc + e.amount, 0)
                  });
                }
                return data;
              }, [sales, expenses, period])}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 10, fontWeight: 700}} dy={10} />
                <YAxis axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 10, fontWeight: 700}} />
                <Tooltip contentStyle={{borderRadius: '20px', border: 'none', boxShadow: '0 25px 50px -12px rgb(0 0 0 / 0.15)', padding: '15px'}} />
                <Area type="monotone" dataKey="ingresos" stroke="#3b82f6" strokeWidth={4} fill="#3b82f6" fillOpacity={0.05} />
                <Area type="monotone" dataKey="gastos" stroke="#f43f5e" strokeWidth={4} fill="#f43f5e" fillOpacity={0.05} />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm flex flex-col">
          <h3 className="text-xs font-black text-slate-800 uppercase tracking-[0.2em] mb-6 flex items-center gap-2">
            <FileText className="text-blue-500" size={16} /> Resumen de Liquidez
          </h3>
          <div className="flex-1 space-y-6">
            <div className="p-5 bg-blue-50 rounded-3xl border border-blue-100">
              <p className="text-[10px] font-black text-blue-400 uppercase tracking-wider mb-1">Recaudado vs Facturado</p>
              <div className="flex items-end justify-between">
                <p className="text-2xl font-black text-blue-700">
                  {filteredData.fSales.length > 0 
                    ? ((stats.revenue / filteredData.fSales.reduce((acc, s) => acc + s.total, 0)) * 100).toFixed(1) 
                    : 0}%
                </p>
                <span className="text-[10px] font-bold text-blue-400 mb-1">Eficiencia de Cobro</span>
              </div>
            </div>

            <div className="p-5 bg-amber-50 rounded-3xl border border-amber-100">
              <p className="text-[10px] font-black text-amber-500 uppercase tracking-wider mb-1">Capital en la Calle</p>
              <p className="text-2xl font-black text-amber-700">${stats.pendingCredits.toLocaleString()}</p>
              <p className="text-[9px] text-amber-600/60 font-bold mt-2 leading-tight uppercase">Monto total que clientes tienen pendiente por pagar.</p>
            </div>
          </div>
        </div>
      </div>

      {/* Nuevos Gráficos por Categoría */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm">
          <h3 className="text-sm font-black text-slate-800 uppercase tracking-widest mb-8 flex items-center gap-2">
            <BarChart3 className="text-blue-600" size={18} /> Ingresos por Categoría ($)
          </h3>
          <div className="h-80 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={categoryStats}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="category" axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 10, fontWeight: 700}} dy={10} />
                <YAxis axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 10, fontWeight: 700}} />
                <Tooltip cursor={{fill: '#f8fafc'}} contentStyle={{borderRadius: '20px', border: 'none', boxShadow: '0 20px 25px -5px rgb(0 0 0 / 0.1)'}} />
                <Bar dataKey="money" radius={[8, 8, 0, 0]}>
                  {categoryStats.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm">
          <h3 className="text-sm font-black text-slate-800 uppercase tracking-widest mb-8 flex items-center gap-2">
            <Layers className="text-emerald-600" size={18} /> Unidades por Categoría (Ventas)
          </h3>
          <div className="h-80 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={categoryStats}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="category" axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 10, fontWeight: 700}} dy={10} />
                <YAxis axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 10, fontWeight: 700}} />
                <Tooltip cursor={{fill: '#f8fafc'}} contentStyle={{borderRadius: '20px', border: 'none', boxShadow: '0 20px 25px -5px rgb(0 0 0 / 0.1)'}} />
                <Bar dataKey="units" radius={[8, 8, 0, 0]}>
                  {categoryStats.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={COLORS[(index + 2) % COLORS.length]} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>
    </div>
  );
};

export default DashboardView;

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { dbService } from '../services/dbService';
import { Product } from '../types';
import { Plus, Search, Filter, Edit2, Trash2, Camera, Package, RefreshCw, Loader2, Calculator, X, AlertTriangle, ChevronDown } from 'lucide-react';

const InventoryView: React.FC = () => {
  const [products, setProducts] = useState<Product[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isReplenishOpen, setIsReplenishOpen] = useState(false);
  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);
  const [productToDelete, setProductToDelete] = useState<Product | null>(null);
  const [loading, setLoading] = useState(false);

  // Estados para categorías
  const [categoryInput, setCategoryInput] = useState('');
  const [showCategorySuggestions, setShowCategorySuggestions] = useState(false);
  const categoryRef = useRef<HTMLDivElement>(null);

  // Estados compartidos para calculadoras
  const [calcQty, setCalcQty] = useState<number>(0);
  const [calcUnitCost, setCalcUnitCost] = useState<number>(0);
  const [calcTotalCost, setCalcTotalCost] = useState<number>(0);

  useEffect(() => {
    dbService.getProducts().then(setProducts).catch(console.error);

    // Cerrar sugerencias al hacer clic fuera
    const handleClickOutside = (event: MouseEvent) => {
      if (categoryRef.current && !categoryRef.current.contains(event.target as Node)) {
        setShowCategorySuggestions(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  useEffect(() => {
    if (isModalOpen) {
      if (editingProduct) {
        setCalcQty(editingProduct.stock);
        setCalcUnitCost(editingProduct.cost);
        setCalcTotalCost(Number((editingProduct.stock * editingProduct.cost).toFixed(2)));
        setCategoryInput(editingProduct.category || '');
      } else {
        setCalcQty(0);
        setCalcUnitCost(0);
        setCalcTotalCost(0);
        setCategoryInput('');
      }
    }
  }, [isModalOpen, editingProduct]);

  useEffect(() => {
    if (isReplenishOpen && editingProduct) {
      setCalcUnitCost(editingProduct.cost);
      setCalcQty(0);
      setCalcTotalCost(0);
    }
  }, [isReplenishOpen, editingProduct]);

  const uniqueCategories = useMemo(() => {
    const cats = products.map(p => p.category).filter(Boolean);
    return Array.from(new Set(cats)).sort();
  }, [products]);

  const filteredCategories = useMemo(() => {
    if (!categoryInput) return uniqueCategories;
    return uniqueCategories.filter(c => 
      c.toLowerCase().includes(categoryInput.toLowerCase())
    );
  }, [uniqueCategories, categoryInput]);

  const filteredProducts = useMemo(() => {
    return products.filter(p => 
      p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
      (p.barcode && p.barcode.includes(searchTerm))
    );
  }, [products, searchTerm]);

  const handleQtyChange = (qty: number) => {
    setCalcQty(qty);
    if (qty > 0) {
      if (calcUnitCost > 0) setCalcTotalCost(Number((calcUnitCost * qty).toFixed(2)));
      else if (calcTotalCost > 0) setCalcUnitCost(Number((calcTotalCost / qty).toFixed(2)));
    }
  };

  const handleUnitCostChange = (unit: number) => {
    setCalcUnitCost(unit);
    if (calcQty > 0) setCalcTotalCost(Number((unit * calcQty).toFixed(2)));
  };

  const handleTotalCostChange = (total: number) => {
    setCalcTotalCost(total);
    if (calcQty > 0) setCalcUnitCost(Number((total / calcQty).toFixed(2)));
  };

  const handleSaveProduct = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setLoading(true);
    const formData = new FormData(e.currentTarget);
    const isNew = !editingProduct;

    const productData: Partial<Product> = {
      id: editingProduct?.id || crypto.randomUUID(),
      name: formData.get('name') as string,
      barcode: (formData.get('barcode') as string) || '',
      category: categoryInput || 'General',
      price: Number(formData.get('price')),
      cost: calcUnitCost,
      stock: calcQty,
    };

    try {
      await dbService.saveProduct(productData, isNew);
      const updated = await dbService.getProducts();
      setProducts(updated);
      setIsModalOpen(false);
      setEditingProduct(null);
    } catch (err) {
      alert("Error al guardar producto");
    } finally {
      setLoading(false);
    }
  };

  const handleReplenishStock = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!editingProduct || calcQty <= 0) return;
    setLoading(true);

    try {
      await dbService.updateStockAndRecordExpense(
        editingProduct.id, 
        calcQty, 
        calcUnitCost, 
        editingProduct.name
      );
      const updated = await dbService.getProducts();
      setProducts(updated);
      setIsReplenishOpen(false);
      setEditingProduct(null);
    } catch (err: any) {
      alert("Error al reponer stock: " + err.message);
    } finally {
      setLoading(false);
    }
  };

  const confirmDeleteProduct = async () => {
    if (!productToDelete) return;
    setLoading(true);
    try {
      await dbService.deleteProduct(productToDelete.id);
      const updated = await dbService.getProducts();
      setProducts(updated);
      setIsDeleteModalOpen(false);
      setProductToDelete(null);
    } catch (err) {
      alert("Error al eliminar producto");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-black text-slate-800 tracking-tight">Inventario Global</h1>
          <p className="text-slate-500 font-medium">Control total de stock y costos base.</p>
        </div>
        <button 
          onClick={() => { setEditingProduct(null); setIsModalOpen(true); }}
          className="bg-blue-600 hover:bg-blue-700 text-white px-6 py-3 rounded-2xl font-black text-sm uppercase tracking-widest flex items-center justify-center gap-2 shadow-xl shadow-blue-200 transition-all active:scale-95"
        >
          <Plus size={18} /> Nuevo Item
        </button>
      </div>

      <div className="flex flex-col md:flex-row gap-4">
        <div className="relative flex-1">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
          <input 
            type="text" 
            placeholder="Buscar por nombre o EAN-13..." 
            className="w-full pl-12 pr-4 py-4 bg-white border border-slate-200 rounded-2xl focus:ring-2 focus:ring-blue-500 transition-all font-medium shadow-sm outline-none"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
      </div>

      <div className="bg-white border border-slate-200 rounded-[2rem] overflow-hidden shadow-xl">
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-slate-50 text-slate-400 text-[10px] font-black uppercase tracking-[0.2em]">
                <th className="px-8 py-6">Producto & Código</th>
                <th className="px-8 py-6">Costo / P.Venta</th>
                <th className="px-8 py-6">Inventario</th>
                <th className="px-8 py-6">Acciones</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredProducts.map((p) => (
                <tr key={p.id} className="hover:bg-slate-50/80 transition-all group">
                  <td className="px-8 py-6">
                    <div>
                      <p className="font-black text-slate-800">{p.name}</p>
                      <p className="text-[10px] text-slate-400 font-black uppercase tracking-wider flex items-center gap-1">
                        <Camera size={10} /> {p.barcode || 'SIN EAN'} • {p.category}
                      </p>
                    </div>
                  </td>
                  <td className="px-8 py-6">
                    <div className="flex flex-col">
                      <span className="text-xs font-bold text-slate-400">C: ${p.cost.toLocaleString()}</span>
                      <span className="text-sm font-black text-blue-600">V: ${p.price.toLocaleString()}</span>
                    </div>
                  </td>
                  <td className="px-8 py-6">
                    <div className="flex items-center gap-3">
                      <div className={`w-2.5 h-2.5 rounded-full ${p.stock <= 5 ? 'bg-rose-500 animate-pulse' : 'bg-emerald-500'}`} />
                      <span className={`text-sm font-black ${p.stock <= 5 ? 'text-rose-600' : 'text-slate-800'}`}>
                        {p.stock} uds
                      </span>
                    </div>
                  </td>
                  <td className="px-8 py-6">
                    <div className="flex items-center gap-2">
                      <button 
                        onClick={() => { setEditingProduct(p); setIsReplenishOpen(true); }}
                        className="p-2.5 text-blue-600 bg-blue-50 hover:bg-blue-100 rounded-xl transition-all"
                        title="Reponer Stock"
                      >
                        <RefreshCw size={16} />
                      </button>
                      <button 
                        onClick={() => { setEditingProduct(p); setIsModalOpen(true); }}
                        className="p-2.5 text-slate-400 hover:text-slate-900 bg-slate-50 hover:bg-slate-100 rounded-xl transition-all"
                      >
                        <Edit2 size={16} />
                      </button>
                      <button 
                        onClick={() => { setProductToDelete(p); setIsDeleteModalOpen(true); }}
                        className="p-2.5 text-rose-300 hover:text-rose-600 hover:bg-rose-50 rounded-xl transition-all"
                      >
                        <Trash2 size={16} />
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* Modal Reponer Stock (Faltaba en el JSX) */}
      {isReplenishOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/40 backdrop-blur-sm" onClick={() => setIsReplenishOpen(false)} />
          <div className="relative bg-white w-full max-w-md rounded-[2.5rem] shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="px-8 py-6 border-b border-slate-100 flex items-center justify-between bg-slate-50/50">
              <h3 className="text-lg font-black text-slate-800 uppercase tracking-tight">Reponer Inventario</h3>
              <button onClick={() => setIsReplenishOpen(false)} className="p-2 text-slate-400 hover:text-slate-600"><X size={24} /></button>
            </div>
            <form onSubmit={handleReplenishStock} className="p-8 space-y-6">
              <div className="space-y-4">
                <div className="bg-blue-50 p-4 rounded-2xl border border-blue-100">
                  <p className="text-[10px] font-black text-blue-400 uppercase tracking-widest mb-1">Producto Seleccionado</p>
                  <p className="font-black text-blue-700 text-lg">{editingProduct?.name}</p>
                </div>

                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Cantidad a Agregar</label>
                  <input 
                    type="number" 
                    required 
                    min="1"
                    className="w-full px-5 py-4 bg-slate-50 border border-slate-200 rounded-2xl outline-none font-black text-xl" 
                    value={calcQty || ''} 
                    onChange={(e) => handleQtyChange(Number(e.target.value))}
                    placeholder="Ej: 10"
                  />
                </div>

                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Costo Unitario Compra ($)</label>
                  <input 
                    type="number" 
                    step="0.01" 
                    required 
                    className="w-full px-5 py-4 bg-slate-50 border border-slate-200 rounded-2xl outline-none font-black text-xl" 
                    value={calcUnitCost || ''} 
                    onChange={(e) => handleUnitCostChange(Number(e.target.value))}
                    placeholder="0.00"
                  />
                </div>

                <div className="pt-4 border-t border-slate-100 flex justify-between items-center">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Inversión Total</p>
                  <p className="text-2xl font-black text-slate-800">${calcTotalCost.toLocaleString()}</p>
                </div>
              </div>

              <button 
                disabled={loading || calcQty <= 0} 
                type="submit" 
                className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black text-lg shadow-xl flex items-center justify-center gap-2 transition-all active:scale-95"
              >
                {loading ? <Loader2 className="animate-spin" /> : 'Confirmar Reposición'}
              </button>
            </form>
          </div>
        </div>
      )}

      {/* Modal Confirmación Borrado */}
      {isDeleteModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-md" onClick={() => setIsDeleteModalOpen(false)} />
          <div className="relative bg-white w-full max-w-sm rounded-[2.5rem] p-8 shadow-2xl text-center animate-in zoom-in-95 duration-200">
            <div className="w-20 h-20 bg-rose-50 text-rose-600 rounded-3xl flex items-center justify-center mx-auto mb-6 shadow-inner ring-8 ring-rose-50/50">
              <AlertTriangle size={40} />
            </div>
            <h3 className="text-2xl font-black text-slate-800 tracking-tight mb-2">¿Eliminar Producto?</h3>
            <p className="text-slate-500 font-medium mb-8">
              Estás por borrar <span className="font-black text-slate-800">"{productToDelete?.name}"</span>. Esta acción no se puede deshacer y afectará el historial de inventario.
            </p>
            <div className="flex flex-col gap-3">
              <button 
                onClick={confirmDeleteProduct}
                disabled={loading}
                className="w-full bg-rose-600 hover:bg-rose-700 text-white py-4 rounded-2xl font-black text-lg shadow-xl shadow-rose-100 flex items-center justify-center gap-2 transition-all active:scale-95"
              >
                {loading ? <Loader2 className="animate-spin" /> : 'Sí, Eliminar Permanentemente'}
              </button>
              <button 
                onClick={() => { setIsDeleteModalOpen(false); setProductToDelete(null); }}
                className="w-full bg-slate-100 hover:bg-slate-200 text-slate-600 py-4 rounded-2xl font-black text-sm uppercase tracking-widest transition-all"
              >
                Cancelar
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Modal Nuevo/Editar */}
      {isModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/40 backdrop-blur-sm" onClick={() => setIsModalOpen(false)} />
          <div className="relative bg-white w-full max-w-2xl rounded-[2.5rem] shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200 max-h-[95vh] flex flex-col">
            <div className="px-8 py-6 border-b border-slate-100 flex items-center justify-between bg-slate-50/50">
              <h3 className="text-lg font-black text-slate-800 uppercase tracking-tight">{editingProduct ? 'Modificar Item' : 'Nuevo Producto'}</h3>
              <button onClick={() => setIsModalOpen(false)} className="p-2 text-slate-400 hover:text-slate-600"><X size={24} /></button>
            </div>
            <form onSubmit={handleSaveProduct} className="p-8 space-y-6 overflow-y-auto hide-scrollbar">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-4">
                  <div className="space-y-1">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Nombre Comercial</label>
                    <input name="name" defaultValue={editingProduct?.name} required className="w-full px-5 py-4 bg-slate-50 border border-slate-200 rounded-2xl outline-none font-bold" />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Código de Barras (EAN-13)</label>
                    <div className="relative">
                      <Camera className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" size={18} />
                      <input name="barcode" defaultValue={editingProduct?.barcode} className="w-full pl-12 pr-4 py-4 bg-slate-50 border border-slate-200 rounded-2xl outline-none font-bold shadow-sm" placeholder="Escanea o escribe..." />
                    </div>
                  </div>

                  {/* Campo Categoría con Sugerencias */}
                  <div className="space-y-1 relative" ref={categoryRef}>
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Categoría</label>
                    <div className="relative">
                      <input 
                        type="text"
                        value={categoryInput}
                        onChange={(e) => {
                          setCategoryInput(e.target.value);
                          setShowCategorySuggestions(true);
                        }}
                        onFocus={() => setShowCategorySuggestions(true)}
                        className="w-full px-5 py-4 bg-slate-50 border border-slate-200 rounded-2xl outline-none font-bold pr-10"
                        placeholder="Ej: Víveres, Bebidas..."
                      />
                      <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-300" size={16} />
                    </div>

                    {/* Lista de Sugerencias */}
                    {showCategorySuggestions && filteredCategories.length > 0 && (
                      <div className="absolute z-[60] left-0 right-0 top-full mt-1 bg-white border border-slate-200 rounded-2xl shadow-2xl max-h-48 overflow-y-auto overflow-hidden animate-in fade-in slide-in-from-top-2 duration-200">
