import React, { useState, useEffect, useCallback } from 'react';
import { supabase } from './supabaseClient';
import { 
  LayoutDashboard, 
  Package, 
  ShoppingCart, 
  History,
  Users, 
  CreditCard, 
  Settings, 
  LogOut, 
  Menu, 
  TrendingDown,
  RefreshCw,
  Store,
  Loader2
} from 'lucide-react';
import { ViewType, UserProfile } from './types';
import DashboardView from './views/DashboardView';
import InventoryView from './views/InventoryView';
import SalesView from './views/SalesView';
import SalesHistoryView from './views/SalesHistoryView';
import ClientsView from './views/ClientsView';
import CreditView from './views/CreditView';
import ExpensesView from './views/ExpensesView';
import SettingsView from './views/SettingsView';
import AuthView from './views/AuthView';

const App: React.FC = () => {
  const [session, setSession] = useState<any>(null);
  const [profile, setProfile] = useState<UserProfile | null>(() => {
    try {
      const saved = localStorage.getItem('cajapro_profile');
      return saved ? JSON.parse(saved) : null;
    } catch {
      return null;
    }
  });
  const [loading, setLoading] = useState(true);
  const [currentView, setCurrentView] = useState<ViewType>('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [syncing, setSyncing] = useState(false);

  const fetchProfile = useCallback(async (userId: string) => {
    try {
      const { data, error } = await supabase
        .from('profiles')
        .select('*')
        .eq('id', userId)
        .single();

      if (data) {
        const newProfile: UserProfile = {
          id: data.id,
          businessName: data.business_name || 'Mi Negocio',
          email: data.email,
          sheetsUrl: data.sheets_url
        };
        setProfile(newProfile);
        localStorage.setItem('cajapro_profile', JSON.stringify(newProfile));
      } else {
        // If profile doesn't exist but user is logged in, they need setup
        setProfile(null);
      }
    } catch (err) {
      console.error("Error fetching profile:", err);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    // Initial session check
    const checkSession = async () => {
      const { data: { session } } = await supabase.auth.getSession();
      setSession(session);
      if (session) {
        await fetchProfile(session.user.id);
      } else {
        localStorage.removeItem('cajapro_profile');
        setProfile(null);
        setLoading(false);
      }
    };

    checkSession();

    // Listen for auth state changes
    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setSession(session);
      if (session) {
        fetchProfile(session.user.id);
      } else {
        localStorage.removeItem('cajapro_profile');
        setProfile(null);
        setLoading(false);
      }
    });

    return () => subscription.unsubscribe();
  }, [fetchProfile]);

  const handleLogout = async () => {
    await supabase.auth.signOut();
    localStorage.removeItem('cajapro_profile');
    setProfile(null);
    setSession(null);
  };

  const NavItem = ({ view, icon: Icon, label }: { view: ViewType, icon: any, label: string }) => (
    <button
      onClick={() => { setCurrentView(view); setIsSidebarOpen(false); }}
      className={`w-full flex items-center space-x-3 px-4 py-3 rounded-lg transition-colors ${
        currentView === view 
          ? 'bg-blue-600 text-white shadow-lg' 
          : 'text-slate-600 hover:bg-slate-100'
      }`}
    >
      <Icon size={20} />
      <span className="font-medium">{label}</span>
    </button>
  );

  const renderView = () => {
    if (!profile) return null;
    switch (currentView) {
      case 'dashboard': return <DashboardView />;
      case 'inventory': return <InventoryView />;
      case 'sales': return <SalesView />;
      case 'sales_history': return <SalesHistoryView />;
      case 'clients': return <ClientsView />;
      case 'credit': return <CreditView />;
      case 'expenses': return <ExpensesView />;
      case 'settings': return <SettingsView user={profile} onUpdateUser={(p) => {
        setProfile(p);
        localStorage.setItem('cajapro_profile', JSON.stringify(p));
      }} />;
      default: return <DashboardView />;
    }
  };

  // Show global loader only if we have no cached profile and we are still loading
  if (loading && !profile) {
    return (
      <div className="min-h-screen bg-slate-50 flex items-center justify-center">
        <Loader2 className="animate-spin text-blue-600" size={40} />
      </div>
    );
  }

  // If no session, show AuthView
  if (!session) {
    return <AuthView onLogin={() => setLoading(true)} />;
  }

  // If session exists but profile setup is pending, AuthView will handle it via step 'profile_setup'
  if (!profile) {
    return <AuthView onLogin={() => setLoading(true)} />;
  }

  return (
    <div className="flex h-screen bg-slate-50 overflow-hidden font-sans">
      {isSidebarOpen && (
        <div className="fixed inset-0 bg-black/50 z-40 lg:hidden" onClick={() => setIsSidebarOpen(false)} />
      )}

      <aside className={`fixed lg:static inset-y-0 left-0 w-64 bg-white border-r border-slate-200 z-50 transform transition-transform duration-300 lg:translate-x-0 ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="flex flex-col h-full p-4">
          <div className="flex items-center space-x-2 px-2 mb-8">
            <div className="bg-blue-600 p-2 rounded-lg text-white"><Store size={24} /></div>
            <h1 className="text-xl font-bold tracking-tight text-slate-800">Caja Pro</h1>
          </div>
          <nav className="flex-1 space-y-1 overflow-y-auto hide-scrollbar">
            <NavItem view="dashboard" icon={LayoutDashboard} label="Dashboard" />
            <NavItem view="sales" icon={ShoppingCart} label="Nueva Venta" />
            <NavItem view="sales_history" icon={History} label="Historial Ventas" />
            <NavItem view="inventory" icon={Package} label="Inventario" />
            <NavItem view="clients" icon={Users} label="Clientes" />
            <NavItem view="credit" icon={CreditCard} label="Crédito & Deudas" />
            <NavItem view="expenses" icon={TrendingDown} label="Egresos" />
            <div className="my-4 border-t border-slate-100" />
            <NavItem view="settings" icon={Settings} label="Configuración" />
          </nav>
          <div className="pt-4 border-t border-slate-100">
            <div className="bg-blue-50 rounded-xl p-4 mb-4">
              <p className="text-xs text-blue-600 font-semibold uppercase mb-1">Tu Negocio</p>
              <p className="text-sm font-bold text-slate-800 truncate">{profile?.businessName}</p>
            </div>
            <button onClick={handleLogout} className="w-full flex items-center space-x-3 px-4 py-3 rounded-lg text-red-600 hover:bg-red-50 transition-colors">
              <LogOut size={20} />
              <span className="font-medium">Cerrar Sesión</span>
            </button>
          </div>
        </div>
      </aside>

      <main className="flex-1 flex flex-col h-full overflow-hidden">
        <header className="h-16 bg-white border-b border-slate-200 flex items-center justify-between px-4 lg:px-8 flex-shrink-0">
          <div className="flex items-center space-x-4">
            <button onClick={() => setIsSidebarOpen(true)} className="lg:hidden p-2 text-slate-600 hover:bg-slate-100 rounded-md"><Menu size={24} /></button>
            <h2 className="text-lg font-bold text-slate-800 lg:text-xl">{profile?.businessName}</h2>
          </div>
          <div className="flex items-center space-x-3">
             <button disabled={syncing} className="flex items-center space-x-2 bg-emerald-50 text-emerald-700 px-3 py-1.5 rounded-full text-sm font-medium hover:bg-emerald-100 transition-colors">
                <RefreshCw size={16} className={syncing ? 'animate-spin' : ''} />
                <span className="hidden sm:inline">Sesión Activa</span>
             </button>
             <div className="w-8 h-8 rounded-full bg-slate-200 flex items-center justify-center text-slate-600 font-bold uppercase">{(profile?.businessName || 'U').charAt(0)}</div>
          </div>
        </header>
        <div className="flex-1 overflow-y-auto p-4 lg:p-8 bg-slate-50 hide-scrollbar">
          <div className="max-w-6xl mx-auto h-full">{renderView()}</div>
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { dbService } from '../services/dbService';
import { Product } from '../types';
import { Plus, Search, Filter, Edit2, Trash2, Camera, Package, RefreshCw, Loader2, Calculator, X, AlertTriangle, ChevronDown, ArrowRightLeft } from 'lucide-react';

const InventoryView: React.FC = () => {
  const [products, setProducts] = useState<Product[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isReplenishOpen, setIsReplenishOpen] = useState(false);
  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);
  const [productToDelete, setProductToDelete] = useState<Product | null>(null);
  const [loading, setLoading] = useState(false);

  const [categoryInput, setCategoryInput] = useState('');
  const [showCategorySuggestions, setShowCategorySuggestions] = useState(false);
  const categoryRef = useRef<HTMLDivElement>(null);

  const [calcQty, setCalcQty] = useState<number>(0);
  const [calcUnitCost, setCalcUnitCost] = useState<number>(0);
  const [calcTotalCost, setCalcTotalCost] = useState<number>(0);

  useEffect(() => {
    dbService.getProducts().then(setProducts).catch(console.error);

    const handleClickOutside = (event: MouseEvent) => {
      if (categoryRef.current && !categoryRef.current.contains(event.target as Node)) {
        setShowCategorySuggestions(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  useEffect(() => {
    if (isModalOpen) {
      if (editingProduct) {
        setCalcQty(editingProduct.stock);
        setCalcUnitCost(editingProduct.cost);
        setCalcTotalCost(Number((editingProduct.stock * editingProduct.cost).toFixed(2)));
        setCategoryInput(editingProduct.category || '');
      } else {
        setCalcQty(0);
        setCalcUnitCost(0);
        setCalcTotalCost(0);
        setCategoryInput('');
      }
    }
  }, [isModalOpen, editingProduct]);

  useEffect(() => {
    if (isReplenishOpen && editingProduct) {
      setCalcUnitCost(editingProduct.cost);
      setCalcQty(0);
      setCalcTotalCost(0);
    }
  }, [isReplenishOpen, editingProduct]);

  const uniqueCategories = useMemo(() => {
    const cats = products.map(p => p.category).filter(Boolean);
    return Array.from(new Set(cats)).sort();
  }, [products]);

  const filteredCategories = useMemo(() => {
    if (!categoryInput) return uniqueCategories;
    return uniqueCategories.filter(c => 
      c.toLowerCase().includes(categoryInput.toLowerCase())
    );
  }, [uniqueCategories, categoryInput]);

  const filteredProducts = useMemo(() => {
    return products.filter(p => 
      p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
      (p.barcode && p.barcode.includes(searchTerm))
    );
  }, [products, searchTerm]);

  // Lógica de Calculadora Bidireccional
  const handleQtyChange = (qty: number) => {
    setCalcQty(qty);
    if (qty > 0 && calcUnitCost > 0) {
      setCalcTotalCost(Number((calcUnitCost * qty).toFixed(2)));
    }
  };

  const handleUnitCostChange = (unit: number) => {
    setCalcUnitCost(unit);
    if (calcQty > 0) {
      setCalcTotalCost(Number((unit * calcQty).toFixed(2)));
    }
  };

  const handleTotalCostChange = (total: number) => {
    setCalcTotalCost(total);
    if (calcQty > 0) {
      setCalcUnitCost(Number((total / calcQty).toFixed(2)));
    }
  };

  const handleSaveProduct = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setLoading(true);
    const formData = new FormData(e.currentTarget);
    const isNew = !editingProduct;

    const productData: Partial<Product> = {
      id: editingProduct?.id || crypto.randomUUID(),
      name: formData.get('name') as string,
      barcode: (formData.get('barcode') as string) || '',
      category: categoryInput || 'General',
      price: Number(formData.get('price')),
      cost: calcUnitCost,
      stock: calcQty,
    };

    try {
      await dbService.saveProduct(productData, isNew);
      const updated = await dbService.getProducts();
      setProducts(updated);
      setIsModalOpen(false);
      setEditingProduct(null);
    } catch (err) {
      alert("Error al guardar producto");
    } finally {
      setLoading(false);
    }
  };

  const handleReplenishStock = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!editingProduct || calcQty <= 0) return;
    setLoading(true);

    try {
      await dbService.updateStockAndRecordExpense(
        editingProduct.id, 
        calcQty, 
        calcUnitCost, 
        editingProduct.name
      );
      const updated = await dbService.getProducts();
      setProducts(updated);
      setIsReplenishOpen(false);
      setEditingProduct(null);
    } catch (err: any) {
      alert("Error al reponer stock: " + err.message);
    } finally {
      setLoading(false);
    }
  };

  const confirmDeleteProduct = async () => {
    if (!productToDelete) return;
    setLoading(true);
    try {
      await dbService.deleteProduct(productToDelete.id);
      const updated = await dbService.getProducts();
      setProducts(updated);
      setIsDeleteModalOpen(false);
      setProductToDelete(null);
    } catch (err) {
      alert("Error al eliminar producto");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-black text-slate-800 tracking-tight">Inventario Global</h1>
          <p className="text-slate-500 font-medium">Control total de stock y costos base.</p>
        </div>
        <button 
          onClick={() => { setEditingProduct(null); setIsModalOpen(true); }}
          className="bg-blue-600 hover:bg-blue-700 text-white px-6 py-3 rounded-2xl font-black text-sm uppercase tracking-widest flex items-center justify-center gap-2 shadow-xl shadow-blue-200 transition-all active:scale-95"
        >
          <Plus size={18} /> Nuevo Item
        </button>
      </div>

      <div className="flex flex-col md:flex-row gap-4">
        <div className="relative flex-1">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
          <input 
            type="text" 
            placeholder="Buscar por nombre o EAN-13..." 
            className="w-full pl-12 pr-4 py-4 bg-white border border-slate-200 rounded-2xl focus:ring-2 focus:ring-blue-500 transition-all font-medium shadow-sm outline-none"
