                    <input 
                      type="number" 
                      step="0.01" 
                      required 
                      className="w-full px-4 py-3 bg-white border border-slate-200 rounded-xl outline-none font-black text-lg text-emerald-600 focus:ring-2 focus:ring-emerald-500" 
