              </div>

              <button 
                disabled={loading || calcQty <= 0} 
                type="submit" 
                className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black text-lg shadow-xl flex items-center justify-center gap-2 transition-all active:scale-95"
              >
                {loading ? <Loader2 className="animate-spin" /> : 'Confirmar Carga'}
              </button>
            </form>
          </div>
        </div>
      )}

      {/* Modal Nuevo/Editar - CALCULADORA MEJORADA */}
      {isModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/40 backdrop-blur-sm" onClick={() => setIsModalOpen(false)} />
          <div className="relative bg-white w-full max-w-2xl rounded-[2.5rem] shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200 max-h-[95vh] flex flex-col">
            <div className="px-8 py-6 border-b border-slate-100 flex items-center justify-between bg-slate-50/50">
              <h3 className="text-lg font-black text-slate-800 uppercase tracking-tight">{editingProduct ? 'Modificar Item' : 'Nuevo Producto'}</h3>
              <button onClick={() => setIsModalOpen(false)} className="p-2 text-slate-400 hover:text-slate-600"><X size={24} /></button>
            </div>
            <form onSubmit={handleSaveProduct} className="p-8 space-y-6 overflow-y-auto hide-scrollbar">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-4">
                  <div className="space-y-1">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Nombre Comercial</label>
                    <input name="name" defaultValue={editingProduct?.name} required className="w-full px-5 py-4 bg-slate-50 border border-slate-200 rounded-2xl outline-none font-bold focus:ring-2 focus:ring-blue-500" />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Código EAN/Barcode</label>
                    <div className="relative">
                      <Camera className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" size={18} />
                      <input name="barcode" defaultValue={editingProduct?.barcode} className="w-full pl-12 pr-4 py-4 bg-slate-50 border border-slate-200 rounded-2xl outline-none font-bold shadow-sm focus:ring-2 focus:ring-blue-500" placeholder="Escanea..." />
                    </div>
                  </div>

                  <div className="space-y-1 relative" ref={categoryRef}>
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Categoría</label>
                    <div className="relative">
                      <input 
                        type="text"
                        value={categoryInput}
                        onChange={(e) => {
                          setCategoryInput(e.target.value);
                          setShowCategorySuggestions(true);
                        }}
                        onFocus={() => setShowCategorySuggestions(true)}
                        className="w-full px-5 py-4 bg-slate-50 border border-slate-200 rounded-2xl outline-none font-bold pr-10 focus:ring-2 focus:ring-blue-500"
                        placeholder="Categoría"
                      />
                      <ChevronDown className={`absolute right-4 top-1/2 -translate-y-1/2 text-slate-300 transition-transform ${showCategorySuggestions ? 'rotate-180' : ''}`} size={16} />
                    </div>

                    {showCategorySuggestions && filteredCategories.length > 0 && (
                      <div className="absolute z-[60] left-0 right-0 top-full mt-1 bg-white border border-slate-200 rounded-2xl shadow-2xl max-h-48 overflow-y-auto overflow-hidden">
                        {filteredCategories.map((cat, idx) => (
                          <button
                            key={idx}
                            type="button"
                            onClick={() => {
                              setCategoryInput(cat);
                              setShowCategorySuggestions(false);
                            }}
                            className="w-full px-5 py-3 text-left hover:bg-blue-50 text-sm font-bold text-slate-700 transition-colors"
                          >
                            {cat}
                          </button>
                        ))}
                      </div>
                    )}
                  </div>

                  <div className="space-y-1">
                    <label className="text-[10px] font-black text-blue-600 uppercase tracking-widest">Precio Venta al Público ($)</label>
                    <input name="price" type="number" step="0.01" defaultValue={editingProduct?.price} required className="w-full px-5 py-4 bg-blue-50 border border-blue-100 rounded-2xl outline-none font-black text-2xl text-blue-600 focus:ring-2 focus:ring-blue-500" />
                  </div>
                </div>

                <div className="space-y-4 bg-slate-50 p-6 rounded-[2rem] border border-slate-100 flex flex-col justify-center relative">
                  <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 flex items-center gap-2">
                    <Calculator size={14}/> Calculadora de Costos
                  </h4>

                  <div className="space-y-1">
                    <label className="text-[10px] font-black text-slate-700 uppercase tracking-widest">Stock Disponible</label>
                    <input type="number" required className="w-full px-5 py-3 bg-white border border-slate-200 rounded-xl outline-none font-black focus:ring-2 focus:ring-blue-500" value={calcQty || ''} onChange={(e) => handleQtyChange(Number(e.target.value))} />
                  </div>

                  <div className="space-y-4 mt-2">
                    <div className="space-y-1">
                      <label className="text-[10px] font-black text-blue-600 uppercase tracking-widest">Costo por Unidad ($)</label>
                      <input type="number" step="0.01" className="w-full px-5 py-3 bg-white border border-slate-200 rounded-xl outline-none font-black text-blue-700 focus:ring-2 focus:ring-blue-500" value={calcUnitCost || ''} onChange={(e) => handleUnitCostChange(Number(e.target.value))} />
                    </div>

                    <div className="flex justify-center -my-2 opacity-30"><ArrowRightLeft size={14} className="rotate-90" /></div>

                    <div className="space-y-1">
                      <label className="text-[10px] font-black text-emerald-600 uppercase tracking-widest">Costo Total Stock ($)</label>
                      <input type="number" step="0.01" className="w-full px-5 py-3 bg-white border border-slate-200 rounded-xl outline-none font-black text-emerald-700 focus:ring-2 focus:ring-emerald-500" value={calcTotalCost || ''} onChange={(e) => handleTotalCostChange(Number(e.target.value))} />
                    </div>
                  </div>
                </div>
              </div>
              <button disabled={loading} type="submit" className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black text-lg shadow-xl flex items-center justify-center gap-2 transition-all active:scale-95">
                {loading ? <Loader2 className="animate-spin" /> : (editingProduct ? 'Guardar Cambios' : 'Registrar Producto')}
              </button>
            </form>
          </div>
        </div>
      )}

      {/* Modal Confirmación Borrado */}
      {isDeleteModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-md" onClick={() => setIsDeleteModalOpen(false)} />
          <div className="relative bg-white w-full max-w-sm rounded-[2.5rem] p-8 shadow-2xl text-center animate-in zoom-in-95 duration-200">
            <div className="w-20 h-20 bg-rose-50 text-rose-600 rounded-3xl flex items-center justify-center mx-auto mb-6 shadow-inner ring-8 ring-rose-50/50">
              <AlertTriangle size={40} />
            </div>
            <h3 className="text-2xl font-black text-slate-800 tracking-tight mb-2">¿Eliminar Producto?</h3>
            <p className="text-slate-500 font-medium mb-8 leading-relaxed">
              Estás por borrar <span className="font-black text-slate-800">"{productToDelete?.name}"</span>. Esta acción no se puede deshacer.
            </p>
            <div className="flex flex-col gap-3">
              <button 
                onClick={confirmDeleteProduct}
                disabled={loading}
                className="w-full bg-rose-600 hover:bg-rose-700 text-white py-4 rounded-2xl font-black text-lg shadow-xl transition-all active:scale-95"
              >
                {loading ? <Loader2 className="animate-spin" /> : 'Eliminar Permanentemente'}
              </button>
              <button 
                onClick={() => setIsDeleteModalOpen(false)}
                className="w-full bg-slate-100 hover:bg-slate-200 text-slate-600 py-4 rounded-2xl font-black text-sm uppercase tracking-widest transition-all"
              >
                Cancelar
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default InventoryView;

import React, { useState, useEffect, useCallback } from 'react';
import { supabase } from './supabaseClient';
import { 
  LayoutDashboard, 
  Package, 
  ShoppingCart, 
  History,
  Users, 
  CreditCard, 
  Settings, 
  LogOut, 
  Menu, 
  TrendingDown,
  RefreshCw,
  Store,
  Loader2,
  X
} from 'lucide-react';
import { ViewType, UserProfile } from './types';
import DashboardView from './views/DashboardView';
import InventoryView from './views/InventoryView';
import SalesView from './views/SalesView';
import SalesHistoryView from './views/SalesHistoryView';
import ClientsView from './views/ClientsView';
import CreditView from './views/CreditView';
import ExpensesView from './views/ExpensesView';
import SettingsView from './views/SettingsView';
import AuthView from './views/AuthView';

const App: React.FC = () => {
  const [session, setSession] = useState<any>(null);
  const [profile, setProfile] = useState<UserProfile | null>(() => {
    try {
      const saved = localStorage.getItem('cajapro_profile');
      return saved ? JSON.parse(saved) : null;
    } catch {
      return null;
    }
  });
  const [loading, setLoading] = useState(true);
  const [currentView, setCurrentView] = useState<ViewType>('sales'); // Por defecto a ventas para agilidad móvil
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [syncing, setSyncing] = useState(false);

  const fetchProfile = useCallback(async (userId: string) => {
    try {
      const { data, error } = await supabase
        .from('profiles')
        .select('*')
        .eq('id', userId)
        .single();

      if (data) {
        const newProfile: UserProfile = {
          id: data.id,
          businessName: data.business_name || 'Mi Negocio',
          email: data.email,
          sheetsUrl: data.sheets_url
        };
        setProfile(newProfile);
        localStorage.setItem('cajapro_profile', JSON.stringify(newProfile));
      } else {
        setProfile(null);
      }
    } catch (err) {
      console.error("Error fetching profile:", err);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    const checkSession = async () => {
      const { data: { session } } = await supabase.auth.getSession();
      setSession(session);
      if (session) {
        await fetchProfile(session.user.id);
      } else {
        localStorage.removeItem('cajapro_profile');
        setProfile(null);
        setLoading(false);
      }
    };
    checkSession();

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setSession(session);
      if (session) {
        fetchProfile(session.user.id);
      } else {
        localStorage.removeItem('cajapro_profile');
        setProfile(null);
        setLoading(false);
      }
    });
    return () => subscription.unsubscribe();
  }, [fetchProfile]);

  const handleLogout = async () => {
    await supabase.auth.signOut();
    localStorage.removeItem('cajapro_profile');
    setProfile(null);
    setSession(null);
  };

  const NavItem = ({ view, icon: Icon, label, mobile = false }: { view: ViewType, icon: any, label: string, mobile?: boolean }) => {
    const isActive = currentView === view;
    if (mobile) {
      return (
        <button
          onClick={() => setCurrentView(view)}
          className={`flex flex-col items-center justify-center flex-1 h-full transition-all ${
            isActive ? 'text-blue-600' : 'text-slate-400'
          }`}
        >
          <Icon size={20} strokeWidth={isActive ? 3 : 2} />
          <span className="text-[10px] font-bold mt-1 uppercase tracking-tighter">{label}</span>
        </button>
      );
    }
    return (
      <button
        onClick={() => { setCurrentView(view); setIsSidebarOpen(false); }}
        className={`w-full flex items-center space-x-3 px-4 py-3 rounded-xl transition-all ${
          isActive 
            ? 'bg-blue-600 text-white shadow-lg shadow-blue-100' 
            : 'text-slate-600 hover:bg-slate-100'
        }`}
      >
        <Icon size={20} />
        <span className="font-bold">{label}</span>
      </button>
    );
  };

  const renderView = () => {
    if (!profile) return null;
    switch (currentView) {
      case 'dashboard': return <DashboardView />;
      case 'inventory': return <InventoryView />;
      case 'sales': return <SalesView />;
      case 'sales_history': return <SalesHistoryView />;
      case 'clients': return <ClientsView />;
      case 'credit': return <CreditView />;
      case 'expenses': return <ExpensesView />;
      case 'settings': return <SettingsView user={profile} onUpdateUser={(p) => {
        setProfile(p);
        localStorage.setItem('cajapro_profile', JSON.stringify(p));
      }} />;
      default: return <DashboardView />;
    }
  };

  if (loading && !profile) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-6 text-center">
        <Loader2 className="animate-spin text-blue-600 mb-4" size={48} />
        <p className="text-slate-500 font-black uppercase tracking-widest text-xs">Cargando Sistema...</p>
      </div>
    );
  }

  if (!session || !profile) {
    return <AuthView onLogin={() => setLoading(true)} />;
  }

  return (
    <div className="flex h-screen bg-slate-50 overflow-hidden font-sans">
      {/* Mobile Drawer Overlay */}
      {isSidebarOpen && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-50 lg:hidden" onClick={() => setIsSidebarOpen(false)} />
      )}

      {/* Sidebar - Desktop & Tablet */}
      <aside className={`fixed lg:static inset-y-0 left-0 w-72 bg-white border-r border-slate-200 z-[60] transform transition-transform duration-300 lg:translate-x-0 ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="flex flex-col h-full p-6">
          <div className="flex items-center justify-between mb-8">
            <div className="flex items-center space-x-3">
              <div className="bg-blue-600 p-2.5 rounded-2xl text-white shadow-lg shadow-blue-100"><Store size={24} /></div>
              <h1 className="text-xl font-black tracking-tighter text-slate-800">Caja Pro</h1>
            </div>
            <button onClick={() => setIsSidebarOpen(false)} className="lg:hidden p-2 text-slate-400"><X size={20}/></button>
          </div>

          <nav className="flex-1 space-y-1 overflow-y-auto hide-scrollbar">
            <NavItem view="dashboard" icon={LayoutDashboard} label="Dashboard" />
            <NavItem view="sales" icon={ShoppingCart} label="Nueva Venta" />
            <NavItem view="sales_history" icon={History} label="Historial" />
            <NavItem view="inventory" icon={Package} label="Inventario" />
            <NavItem view="clients" icon={Users} label="Clientes" />
            <NavItem view="credit" icon={CreditCard} label="Crédito" />
            <NavItem view="expenses" icon={TrendingDown} label="Egresos" />
            <div className="my-6 border-t border-slate-100" />
            <NavItem view="settings" icon={Settings} label="Ajustes" />
          </nav>

          <div className="pt-6 border-t border-slate-100">
            <button onClick={handleLogout} className="w-full flex items-center space-x-3 px-4 py-3 rounded-xl text-rose-500 hover:bg-rose-50 transition-colors font-bold">
              <LogOut size={20} />
              <span>Salir del Sistema</span>
            </button>
          </div>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col h-full overflow-hidden relative">
        <header className="h-16 lg:h-20 bg-white border-b border-slate-200 flex items-center justify-between px-4 lg:px-10 flex-shrink-0">
          <div className="flex items-center space-x-4">
            <button onClick={() => setIsSidebarOpen(true)} className="lg:hidden p-2.5 bg-slate-50 text-slate-600 rounded-xl"><Menu size={20} /></button>
            <div className="flex flex-col">
              <h2 className="text-sm lg:text-lg font-black text-slate-800 truncate max-w-[150px] lg:max-w-none">{profile?.businessName}</h2>
              <p className="text-[10px] font-black text-emerald-500 uppercase tracking-widest flex items-center gap-1">
                <span className="w-1.5 h-1.5 bg-emerald-500 rounded-full animate-pulse"></span> Terminal Online
              </p>
            </div>
          </div>

          <div className="flex items-center space-x-2">
             <button className="p-2.5 bg-blue-50 text-blue-600 rounded-xl lg:hidden" onClick={() => setCurrentView('settings')}>
                <Settings size={20} />
             </button>
             <div className="hidden lg:flex items-center space-x-3 bg-slate-50 px-4 py-2 rounded-2xl border border-slate-100">
               <div className="w-8 h-8 rounded-xl bg-blue-600 flex items-center justify-center text-white text-xs font-black">
                 {profile?.businessName.charAt(0)}
               </div>
               <span className="text-xs font-bold text-slate-600">{profile?.email}</span>
             </div>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-4 lg:p-10 pb-24 lg:pb-10 bg-slate-50 hide-scrollbar">
          <div className="max-w-7xl mx-auto h-full">{renderView()}</div>
        </div>

        {/* Bottom Navigation for Mobile */}
        <nav className="lg:hidden fixed bottom-0 left-0 right-0 h-16 bg-white border-t border-slate-200 flex items-center justify-around px-2 z-[70] shadow-[0_-4px_20px_rgba(0,0,0,0.05)]">
          <NavItem view="sales" icon={ShoppingCart} label="Venta" mobile />
          <NavItem view="inventory" icon={Package} label="Stock" mobile />
          <NavItem view="sales_history" icon={History} label="Hist" mobile />
          <NavItem view="credit" icon={CreditCard} label="Cobro" mobile />
          <NavItem view="dashboard" icon={LayoutDashboard} label="Dash" mobile />
        </nav>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { dbService } from '../services/dbService';
import { Product } from '../types';
import { Plus, Search, Edit2, Trash2, Camera, Package, RefreshCw, Loader2, Calculator, X, AlertTriangle, ChevronDown, ArrowRightLeft, MoreVertical } from 'lucide-react';

const InventoryView: React.FC = () => {
  const [products, setProducts] = useState<Product[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isReplenishOpen, setIsReplenishOpen] = useState(false);
  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);
  const [productToDelete, setProductToDelete] = useState<Product | null>(null);
  const [loading, setLoading] = useState(false);

  const [categoryInput, setCategoryInput] = useState('');
  const [showCategorySuggestions, setShowCategorySuggestions] = useState(false);
  const categoryRef = useRef<HTMLDivElement>(null);

  const [calcQty, setCalcQty] = useState<number>(0);
  const [calcUnitCost, setCalcUnitCost] = useState<number>(0);
  const [calcTotalCost, setCalcTotalCost] = useState<number>(0);

  useEffect(() => {
    dbService.getProducts().then(setProducts).catch(console.error);
    const handleClickOutside = (event: MouseEvent) => {
      if (categoryRef.current && !categoryRef.current.contains(event.target as Node)) {
        setShowCategorySuggestions(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  useEffect(() => {
    if (isModalOpen) {
      if (editingProduct) {
        setCalcQty(editingProduct.stock);
        setCalcUnitCost(editingProduct.cost);
        setCalcTotalCost(Number((editingProduct.stock * editingProduct.cost).toFixed(2)));
        setCategoryInput(editingProduct.category || '');
      } else {
        setCalcQty(0);
        setCalcUnitCost(0);
        setCalcTotalCost(0);
        setCategoryInput('');
      }
    }
  }, [isModalOpen, editingProduct]);

  useEffect(() => {
    if (isReplenishOpen && editingProduct) {
      setCalcUnitCost(editingProduct.cost);
      setCalcQty(0);
      setCalcTotalCost(0);
    }
  }, [isReplenishOpen, editingProduct]);

  const uniqueCategories = useMemo(() => {
    const cats = products.map(p => p.category).filter(Boolean);
    return Array.from(new Set(cats)).sort();
  }, [products]);

  const filteredCategories = useMemo(() => {
    if (!categoryInput) return uniqueCategories;
    return uniqueCategories.filter(c => 
      c.toLowerCase().includes(categoryInput.toLowerCase())
    );
  }, [uniqueCategories, categoryInput]);

  const filteredProducts = useMemo(() => {
    return products.filter(p => 
      p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
      (p.barcode && p.barcode.includes(searchTerm))
    );
  }, [products, searchTerm]);

  const handleQtyChange = (qty: number) => {
    setCalcQty(qty);
    if (qty > 0 && calcUnitCost > 0) setCalcTotalCost(Number((calcUnitCost * qty).toFixed(2)));
  };

  const handleUnitCostChange = (unit: number) => {
    setCalcUnitCost(unit);
    if (calcQty > 0) setCalcTotalCost(Number((unit * calcQty).toFixed(2)));
  };

  const handleTotalCostChange = (total: number) => {
    setCalcTotalCost(total);
    if (calcQty > 0) setCalcUnitCost(Number((total / calcQty).toFixed(2)));
  };

  const handleSaveProduct = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setLoading(true);
    const formData = new FormData(e.currentTarget);
    const isNew = !editingProduct;
    const productData: Partial<Product> = {
      id: editingProduct?.id || crypto.randomUUID(),
      name: formData.get('name') as string,
      barcode: (formData.get('barcode') as string) || '',
      category: categoryInput || 'General',
      price: Number(formData.get('price')),
      cost: calcUnitCost,
      stock: calcQty,
    };
    try {
      await dbService.saveProduct(productData, isNew);
      const updated = await dbService.getProducts();
      setProducts(updated);
      setIsModalOpen(false);
      setEditingProduct(null);
    } catch (err) {
      alert("Error al guardar");
    } finally {
      setLoading(false);
    }
  };

  const handleReplenishStock = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!editingProduct || calcQty <= 0) return;
    setLoading(true);
    try {
      await dbService.updateStockAndRecordExpense(editingProduct.id, calcQty, calcUnitCost, editingProduct.name);
      const updated = await dbService.getProducts();
      setProducts(updated);
      setIsReplenishOpen(false);
      setEditingProduct(null);
    } catch (err: any) {
      alert("Error: " + err.message);
    } finally {
      setLoading(false);
    }
  };

  const confirmDeleteProduct = async () => {
    if (!productToDelete) return;
    setLoading(true);
    try {
      await dbService.deleteProduct(productToDelete.id);
      const updated = await dbService.getProducts();
      setProducts(updated);
      setIsDeleteModalOpen(false);
      setProductToDelete(null);
    } catch (err) {
      alert("Error al eliminar");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500 pb-10">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-xl lg:text-3xl font-black text-slate-800 tracking-tight">Inventario</h1>
          <p className="text-xs lg:text-base text-slate-500 font-medium tracking-tight">Administra tus existencias y costos base.</p>
        </div>
        <button 
          onClick={() => { setEditingProduct(null); setIsModalOpen(true); }}
          className="bg-blue-600 hover:bg-blue-700 text-white px-5 lg:px-7 py-3 lg:py-4 rounded-2xl font-black text-xs lg:text-sm uppercase tracking-widest flex items-center justify-center gap-2 shadow-lg shadow-blue-100 transition-all active:scale-95"
        >
          <Plus size={18} /> <span className="hidden sm:inline">Nuevo Item</span><span className="sm:hidden">Nuevo</span>
        </button>
      </div>

      <div className="relative">
        <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
        <input 
          type="text" 
          placeholder="Nombre o Código de Barras..." 
          className="w-full pl-12 pr-4 py-3 lg:py-5 bg-white border border-slate-200 rounded-2xl focus:ring-2 focus:ring-blue-500 transition-all font-medium shadow-sm outline-none text-sm lg:text-base"
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
        />
      </div>

      {/* Desktop View (Table) */}
      <div className="hidden lg:block bg-white border border-slate-200 rounded-[2.5rem] overflow-hidden shadow-xl shadow-slate-200/50">
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-slate-50 text-slate-400 text-[10px] font-black uppercase tracking-[0.2em]">
                <th className="px-8 py-6">Producto</th>
                <th className="px-8 py-6">Inversión / Venta</th>
                <th className="px-8 py-6 text-center">Existencia</th>
                <th className="px-8 py-6 text-right">Acciones</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredProducts.map((p) => (
                <tr key={p.id} className="hover:bg-slate-50/50 transition-all group">
                  <td className="px-8 py-6">
                    <div className="flex flex-col">
                      <span className="font-black text-slate-800 text-base">{p.name}</span>
                      <span className="text-[10px] text-slate-400 font-black uppercase tracking-widest">{p.category} • {p.barcode || 'S/C'}</span>
                    </div>
                  </td>
                  <td className="px-8 py-6">
                    <div className="flex flex-col">
                      <span className="text-xs font-bold text-slate-400">Costo: ${p.cost.toLocaleString()}</span>
                      <span className="text-base font-black text-blue-600">PVP: ${p.price.toLocaleString()}</span>
                    </div>
                  </td>
                  <td className="px-8 py-6">
                    <div className="flex flex-col items-center">
                      <div className={`px-4 py-1.5 rounded-full text-xs font-black ${p.stock <= 5 ? 'bg-rose-100 text-rose-600' : 'bg-emerald-100 text-emerald-600'}`}>
                        {p.stock} UNIDADES
                      </div>
                      {p.stock <= 5 && <span className="text-[9px] font-black text-rose-400 mt-1 uppercase animate-pulse">Stock Crítico</span>}
                    </div>
                  </td>
                  <td className="px-8 py-6">
                    <div className="flex items-center justify-end gap-2">
                      <button onClick={() => { setEditingProduct(p); setIsReplenishOpen(true); }} className="p-3 bg-emerald-50 text-emerald-600 rounded-xl hover:bg-emerald-100 transition-all" title="Reponer"><RefreshCw size={18}/></button>
                      <button onClick={() => { setEditingProduct(p); setIsModalOpen(true); }} className="p-3 bg-blue-50 text-blue-600 rounded-xl hover:bg-blue-100 transition-all" title="Editar"><Edit2 size={18}/></button>
                      <button onClick={() => { setProductToDelete(p); setIsDeleteModalOpen(true); }} className="p-3 bg-rose-50 text-rose-300 hover:text-rose-600 rounded-xl transition-all" title="Eliminar"><Trash2 size={18}/></button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* Mobile View (Cards) */}
      <div className="lg:hidden space-y-4">
        {filteredProducts.map((p) => (
          <div key={p.id} className="bg-white p-5 rounded-3xl border border-slate-200 shadow-sm flex flex-col gap-4">
            <div className="flex justify-between items-start">
              <div className="flex-1">
                <span className="text-[10px] font-black text-blue-600 uppercase tracking-widest bg-blue-50 px-2 py-0.5 rounded-md">{p.category}</span>
                <h3 className="font-black text-slate-800 text-lg mt-1">{p.name}</h3>
                <p className="text-[10px] text-slate-400 font-bold tracking-widest mt-0.5">EAN: {p.barcode || 'N/A'}</p>
              </div>
              <div className={`text-right px-3 py-1 rounded-2xl font-black text-xs ${p.stock <= 5 ? 'bg-rose-100 text-rose-600' : 'bg-slate-100 text-slate-600'}`}>
                {p.stock} uds
              </div>
            </div>

            <div className="flex items-center justify-between p-3 bg-slate-50 rounded-2xl">
              <div className="flex flex-col">
                <span className="text-[9px] font-black text-slate-400 uppercase tracking-tighter leading-none">Costo Promedio</span>
                <span className="text-sm font-bold text-slate-700">${p.cost.toLocaleString()}</span>
              </div>
              <div className="flex flex-col text-right">
                <span className="text-[9px] font-black text-blue-400 uppercase tracking-tighter leading-none">Precio Venta</span>
                <span className="text-lg font-black text-blue-600 leading-none">${p.price.toLocaleString()}</span>
              </div>
            </div>

            <div className="flex items-center gap-2 pt-2">
              <button 
                onClick={() => { setEditingProduct(p); setIsReplenishOpen(true); }} 
                className="flex-1 bg-emerald-50 text-emerald-600 py-3 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center justify-center gap-2"
              >
                <RefreshCw size={14}/> Cargar Stock
              </button>
              <button 
                onClick={() => { setEditingProduct(p); setIsModalOpen(true); }} 
                className="p-3 bg-blue-50 text-blue-600 rounded-2xl"
              >
                <Edit2 size={16}/>
              </button>
              <button 
                onClick={() => { setProductToDelete(p); setIsDeleteModalOpen(true); }} 
                className="p-3 bg-rose-50 text-rose-400 rounded-2xl"
              >
                <Trash2 size={16}/>
              </button>
            </div>
          </div>
        ))}
      </div>

      {/* Modals are full-screen or large on mobile */}
      {isReplenishOpen && (
        <div className="fixed inset-0 z-[100] flex items-end sm:items-center justify-center p-0 sm:p-4">
          <div className="absolute inset-0 bg-slate-900/40 backdrop-blur-sm" onClick={() => setIsReplenishOpen(false)} />
          <div className="relative bg-white w-full max-w-md h-[85vh] sm:h-auto rounded-t-[2.5rem] sm:rounded-[2.5rem] shadow-2xl overflow-hidden animate-in slide-in-from-bottom sm:zoom-in-95 duration-300">
             {/* Replenish Content (Same as previous but optimized for touch) */}
             <div className="px-8 py-6 border-b border-slate-100 flex items-center justify-between">
              <h3 className="text-lg font-black text-slate-800 uppercase tracking-tighter">Entrada de Mercancía</h3>
              <button onClick={() => setIsReplenishOpen(false)} className="p-2 text-slate-400 hover:text-slate-600 transition-colors"><X size={24} /></button>
            </div>
            <form onSubmit={handleReplenishStock} className="p-8 space-y-6">
              <div className="bg-blue-50 p-5 rounded-3xl border border-blue-100 mb-6">
                <p className="text-[10px] font-black text-blue-400 uppercase tracking-widest mb-1">Cargando a:</p>
                <p className="font-black text-blue-700 text-lg leading-tight">{editingProduct?.name}</p>
              </div>
              <div className="space-y-5">
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Unidades</label>
                  <input type="number" required min="1" className="w-full px-5 py-4 bg-slate-50 border border-slate-200 rounded-2xl font-black text-2xl outline-none focus:ring-2 focus:ring-blue-500" value={calcQty || ''} onChange={(e) => handleQtyChange(Number(e.target.value))} />
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Costo Unit ($)</label>
                    <input type="number" step="0.01" className="w-full px-4 py-4 bg-slate-50 border border-slate-200 rounded-2xl font-black text-lg outline-none" value={calcUnitCost || ''} onChange={(e) => handleUnitCostChange(Number(e.target.value))} />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Total ($)</label>
                    <input type="number" step="0.01" className="w-full px-4 py-4 bg-slate-50 border border-slate-200 rounded-2xl font-black text-lg outline-none" value={calcTotalCost || ''} onChange={(e) => handleTotalCostChange(Number(e.target.value))} />
                  </div>
                </div>
              </div>
              <button disabled={loading || calcQty <= 0} type="submit" className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black text-lg shadow-xl flex items-center justify-center gap-2 mt-4 active:scale-95 transition-all">
                {loading ? <Loader2 className="animate-spin" /> : 'Confirmar Ingreso'}
              </button>
            </form>
          </div>
        </div>
      )}

      {/* Main Modal (Add/Edit) */}
      {isModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-end sm:items-center justify-center p-0 sm:p-4">
          <div className="absolute inset-0 bg-slate-900/40 backdrop-blur-sm" onClick={() => setIsModalOpen(false)} />
          <div className="relative bg-white w-full max-w-4xl h-[95vh] sm:h-auto rounded-t-[3rem] sm:rounded-[3rem] shadow-2xl overflow-hidden flex flex-col animate-in slide-in-from-bottom sm:zoom-in-95 duration-300">
            <div className="px-8 py-6 border-b border-slate-100 flex items-center justify-between sticky top-0 bg-white z-10">
              <h3 className="text-xl font-black text-slate-800 uppercase tracking-tighter">{editingProduct ? 'Editar Producto' : 'Nuevo Ingreso'}</h3>
              <button onClick={() => setIsModalOpen(false)} className="p-2 text-slate-400 hover:text-slate-600"><X size={28} /></button>
            </div>
            <form onSubmit={handleSaveProduct} className="p-6 lg:p-10 space-y-8 overflow-y-auto hide-scrollbar flex-1">
              <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 lg:gap-12">
                <div className="space-y-6">
                  <div className="space-y-1">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Nombre Comercial</label>
                    <input name="name" defaultValue={editingProduct?.name} required className="w-full px-6 py-4 bg-slate-50 border border-slate-200 rounded-2xl outline-none font-black text-lg focus:ring-2 focus:ring-blue-500" placeholder="Ej: Coca Cola 2L" />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Código (EAN/UPC)</label>
                    <div className="relative">
                      <Camera className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" size={20} />
                      <input name="barcode" defaultValue={editingProduct?.barcode} className="w-full pl-12 pr-4 py-4 bg-slate-50 border border-slate-200 rounded-2xl outline-none font-bold" placeholder="Escanear o Escribir" />
                    </div>
                  </div>
                  <div className="space-y-1 relative" ref={categoryRef}>
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Categoría</label>
                    <div className="relative">
                      <input type="text" value={categoryInput} onChange={(e) => { setCategoryInput(e.target.value); setShowCategorySuggestions(true); }} onFocus={() => setShowCategorySuggestions(true)} className="w-full px-6 py-4 bg-slate-50 border border-slate-200 rounded-2xl outline-none font-bold" placeholder="Categoría" />
                      <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-300" size={18} />
                    </div>
                    {showCategorySuggestions && filteredCategories.length > 0 && (
                      <div className="absolute z-[60] left-0 right-0 top-full mt-2 bg-white border border-slate-200 rounded-2xl shadow-2xl max-h-48 overflow-y-auto">
                        {filteredCategories.map((cat, idx) => (
                          <button key={idx} type="button" onClick={() => { setCategoryInput(cat); setShowCategorySuggestions(false); }} className="w-full px-6 py-4 text-left hover:bg-blue-50 text-sm font-bold text-slate-700 transition-colors border-b border-slate-50 last:border-0">{cat}</button>
                        ))}
                      </div>
                    )}
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-black text-blue-600 uppercase tracking-widest ml-1 font-black">Precio de Venta ($)</label>
                    <input name="price" type="number" step="0.01" defaultValue={editingProduct?.price} required className="w-full px-6 py-5 bg-blue-50 border border-blue-100 rounded-2xl outline-none font-black text-3xl text-blue-600 focus:ring-4 focus:ring-blue-100" />
                  </div>
                </div>

                <div className="bg-slate-50 p-8 rounded-[2.5rem] border border-slate-100 flex flex-col justify-center gap-6">
                  <h4 className="text-[11px] font-black text-slate-400 uppercase tracking-widest mb-2 flex items-center gap-2">
                    <Calculator size={16}/> Calculadora de Márgenes
                  </h4>
                  <div className="space-y-1">
                    <label className="text-[10px] font-black text-slate-700 uppercase tracking-widest">Stock Disponible</label>
                    <input type="number" required className="w-full px-6 py-4 bg-white border border-slate-200 rounded-2xl outline-none font-black text-xl" value={calcQty || ''} onChange={(e) => handleQtyChange(Number(e.target.value))} />
                  </div>
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                    <div className="space-y-1">
                      <label className="text-[10px] font-black text-blue-600 uppercase tracking-widest">Costo Unit ($)</label>
                      <input type="number" step="0.01" className="w-full px-5 py-4 bg-white border border-slate-200 rounded-2xl outline-none font-black text-blue-700" value={calcUnitCost || ''} onChange={(e) => handleUnitCostChange(Number(e.target.value))} />
                    </div>
                    <div className="space-y-1">
                      <label className="text-[10px] font-black text-emerald-600 uppercase tracking-widest">Inversión Total ($)</label>
                      <input type="number" step="0.01" className="w-full px-5 py-4 bg-white border border-slate-200 rounded-2xl outline-none font-black text-emerald-700" value={calcTotalCost || ''} onChange={(e) => handleTotalCostChange(Number(e.target.value))} />
                    </div>
                  </div>
                  {calcQty > 0 && calcUnitCost > 0 && (
                    <div className="mt-4 p-4 bg-white rounded-2xl border border-slate-200 flex items-center justify-between">
                       <span className="text-[10px] font-black text-slate-400 uppercase">Rentabilidad Bruta</span>
                       <span className="font-black text-emerald-500">+{(((Number(editingProduct?.price || 0) - calcUnitCost) / calcUnitCost) * 100).toFixed(1)}%</span>
                    </div>
                  )}
                </div>
              </div>
              <button disabled={loading} type="submit" className="w-full bg-slate-900 text-white py-6 rounded-2xl font-black text-xl shadow-2xl flex items-center justify-center gap-3 transition-all active:scale-[0.98] mt-4 uppercase tracking-widest">
                {loading ? <Loader2 className="animate-spin" /> : (editingProduct ? 'Guardar Cambios' : 'Registrar Producto')}
              </button>
            </form>
          </div>
        </div>
      )}

      {/* Delete Confirmation */}
      {isDeleteModalOpen && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-md" onClick={() => setIsDeleteModalOpen(false)} />
          <div className="relative bg-white w-full max-w-sm rounded-[3rem] p-8 shadow-2xl text-center animate-in zoom-in-95 duration-200">
            <div className="w-24 h-24 bg-rose-50 text-rose-600 rounded-[2.5rem] flex items-center justify-center mx-auto mb-6 shadow-inner ring-8 ring-rose-50/50">
              <AlertTriangle size={48} />
            </div>
            <h3 className="text-2xl font-black text-slate-800 tracking-tight mb-3">¿Borrar Ítem?</h3>
            <p className="text-slate-500 font-medium mb-8 leading-tight">
              Eliminarás permanentemente <span className="font-black text-slate-800">"{productToDelete?.name}"</span> de tu inventario global.
            </p>
            <div className="flex flex-col gap-3">
              <button onClick={confirmDeleteProduct} disabled={loading} className="w-full bg-rose-600 hover:bg-rose-700 text-white py-5 rounded-2xl font-black text-lg shadow-xl transition-all active:scale-95">{loading ? <Loader2 className="animate-spin" /> : 'Sí, Eliminar'}</button>
              <button onClick={() => setIsDeleteModalOpen(false)} className="w-full bg-slate-100 hover:bg-slate-200 text-slate-600 py-4 rounded-2xl font-black text-xs uppercase tracking-widest transition-all">Cancelar</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default InventoryView;

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { dbService } from '../services/dbService';
import { Product, Client, SaleItem, SaleStatus, Sale } from '../types';
import { ShoppingCart, Search, User, Trash2, Plus, Minus, CreditCard, Wallet, AlertTriangle, ScanLine, UserPlus, Loader2, X, ChevronDown, ChevronUp } from 'lucide-react';

const SalesView: React.FC = () => {
  const [products, setProducts] = useState<Product[]>([]);
  const [clients, setClients] = useState<Client[]>([]);
  const [cart, setCart] = useState<SaleItem[]>([]);
  const [selectedClient, setSelectedClient] = useState<Client | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [clientSearch, setClientSearch] = useState('');
  const [saleStatus, setSaleStatus] = useState<SaleStatus>(SaleStatus.COMPLETED);
  const [amountPaid, setAmountPaid] = useState<string>('');
  const [isCreatingClient, setIsCreatingClient] = useState(false);
  const [isCartVisible, setIsCartVisible] = useState(false); // Para mobile drawer
  const searchInputRef = useRef<HTMLInputElement>(null);
  const lastProcessedRef = useRef<number>(0);

  useEffect(() => {
    dbService.getProducts().then(setProducts).catch(console.error);
    dbService.getClients().then(setClients).catch(console.error);
  }, []);

  const addToCart = (product: Product) => {
    const now = Date.now();
    if (now - lastProcessedRef.current < 200) return;
    lastProcessedRef.current = now;
    if (product.stock <= 0) {
      alert("¡Sin Stock disponible!");
      return;
    }
    setCart(prev => {
      const existing = prev.find(item => item.productId === product.id);
      if (existing) {
        return prev.map(item => item.productId === product.id ? { ...item, quantity: item.quantity + 1 } : item);
      }
      return [...prev, { productId: product.id, name: product.name, price: product.price, quantity: 1 }];
    });
    setSearchTerm('');
  };

  const filteredProducts = useMemo(() => {
    if (!searchTerm || searchTerm.length < 2) return [];
    return products.filter(p => p.name.toLowerCase().includes(searchTerm.toLowerCase()) || (p.barcode && p.barcode.includes(searchTerm)));
  }, [products, searchTerm]);

  const filteredClients = useMemo(() => {
    if (!clientSearch) return [];
    return clients.filter(c => c.name.toLowerCase().includes(clientSearch.toLowerCase()));
  }, [clients, clientSearch]);

  const total = useMemo(() => cart.reduce((acc, item) => acc + (item.price * item.quantity), 0), [cart]);

  const updateQuantity = (id: string, delta: number) => {
    setCart(prev => prev.map(item => {
      if (item.productId === id) {
        const newQty = Math.max(0, item.quantity + delta);
        return { ...item, quantity: newQty };
      }
      return item;
    }).filter(item => item.quantity > 0));
  };

  const handleQuickCreateClient = async () => {
    if (!clientSearch.trim()) return;
    setIsCreatingClient(true);
    try {
      const newClient = await dbService.saveClient({ name: clientSearch.trim(), phone: '', email: '', currentDebt: 0 });
      const updatedClients = await dbService.getClients();
      setClients(updatedClients);
      setSelectedClient(newClient);
      setClientSearch('');
    } catch (err) {
      alert("Error al crear cliente");
    } finally { setIsCreatingClient(false); }
  };

  const handleProcessSale = async () => {
    if (cart.length === 0) return;
    if (saleStatus === SaleStatus.CREDIT && !selectedClient) {
      alert('Debes seleccionar un cliente para ventas a crédito');
      return;
    }
    const sale: Partial<Sale> = {
      id: crypto.randomUUID(),
      clientId: selectedClient?.id,
      items: cart,
      total,
      date: new Date().toISOString(),
      status: saleStatus,
      amountPaid: saleStatus === SaleStatus.CREDIT ? Number(amountPaid) : total
    };
    try {
      await dbService.createSale(sale);
      alert('¡Venta Exitosa!');
      setCart([]);
      setSelectedClient(null);
      setAmountPaid('');
      setSaleStatus(SaleStatus.COMPLETED);
      setIsCartVisible(false);
      dbService.getProducts().then(setProducts);
    } catch (err) { alert("Error procesando venta"); }
  };

  return (
    <div className="h-full flex flex-col lg:flex-row gap-6 animate-in fade-in duration-500 pb-20 lg:pb-0">
      {/* Terminal Area */}
      <div className="flex-1 flex flex-col space-y-4 lg:space-y-6">
        <div className="bg-white p-5 lg:p-7 rounded-[2rem] border border-slate-200 shadow-sm space-y-4 lg:space-y-6">
          <div className="flex items-center justify-between">
            <h3 className="text-xs lg:text-sm font-black text-slate-800 flex items-center gap-2 uppercase tracking-[0.2em]">
              <ScanLine size={20} className="text-blue-500" /> Terminal Táctil
            </h3>
            <span className="text-[9px] lg:text-[10px] font-black uppercase bg-emerald-50 text-emerald-600 px-3 py-1 rounded-lg border border-emerald-100">Activo</span>
          </div>
          <div className="relative">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" size={24} />
            <input 
              ref={searchInputRef}
              type="text" 
              placeholder="Producto o EAN..." 
              className="w-full pl-14 pr-4 py-4 lg:py-6 bg-slate-50 border border-slate-200 rounded-3xl focus:ring-4 focus:ring-blue-100 outline-none text-base lg:text-xl font-black transition-all"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />

            {filteredProducts.length > 0 && (
              <div className="absolute top-full left-0 right-0 mt-3 bg-white border border-slate-200 rounded-[2.5rem] shadow-2xl z-[80] max-h-[60vh] overflow-y-auto divide-y divide-slate-50 overflow-hidden animate-in fade-in slide-in-from-top-4">
                {filteredProducts.map(p => (
                  <button key={p.id} onClick={() => addToCart(p)} className="w-full p-5 lg:p-7 flex items-center justify-between hover:bg-blue-50 active:bg-blue-100 transition-all text-left">
                    <div>
                      <p className="font-black text-slate-800 text-base lg:text-xl">{p.name}</p>
                      <div className="flex items-center gap-2 mt-1">
                        <span className="text-[10px] font-black uppercase text-blue-500 bg-blue-50 px-2 py-0.5 rounded">{p.category}</span>
                        <span className={`text-[10px] font-black uppercase ${p.stock <= 5 ? 'text-rose-500' : 'text-slate-400'}`}>Stock: {p.stock} uds</span>
                      </div>
                    </div>
                    <span className="font-black text-blue-600 text-xl lg:text-2xl">${p.price.toLocaleString()}</span>
                  </button>
                ))}
              </div>
            )}
          </div>
        </div>

        <div className="bg-white p-5 lg:p-7 rounded-[2rem] border border-slate-200 shadow-sm space-y-4">
          <h3 className="text-[10px] lg:text-xs font-black text-slate-800 flex items-center gap-2 uppercase tracking-widest">
            <User size={18} className="text-blue-500" /> Vínculo de Cliente
          </h3>
          {!selectedClient ? (
            <div className="relative">
              <input 
                type="text" 
                placeholder="Nombre del cliente..." 
                className="w-full px-5 py-4 bg-slate-50 border border-slate-200 rounded-2xl outline-none font-bold text-sm lg:text-base"
                value={clientSearch}
                onChange={(e) => setClientSearch(e.target.value)}
              />
              {(filteredClients.length > 0 || clientSearch.length > 1) && (
                <div className="absolute bottom-full lg:top-full left-0 right-0 mb-2 lg:mt-2 bg-white border border-slate-200 rounded-3xl shadow-2xl z-[75] overflow-hidden">
                  {filteredClients.map(c => (
                    <button key={c.id} onClick={() => { setSelectedClient(c); setClientSearch(''); }} className="w-full p-4 text-left hover:bg-blue-50 flex items-center justify-between border-b border-slate-50 last:border-0">
                      <div>
                        <p className="font-bold text-slate-800">{c.name}</p>
                        <p className="text-[10px] text-slate-400 font-black uppercase tracking-widest">${c.currentDebt.toLocaleString()} Deuda</p>
                      </div>
                      <Plus size={18} className="text-blue-400" />
                    </button>
                  ))}
                  {clientSearch.length > 1 && (
                    <button onClick={handleQuickCreateClient} disabled={isCreatingClient} className="w-full p-5 bg-blue-600 text-white font-black text-[10px] uppercase tracking-widest flex items-center justify-center gap-2">
                      {isCreatingClient ? <Loader2 size={16} className="animate-spin" /> : <UserPlus size={16} />}
                      Registrar "{clientSearch}"
                    </button>
                  )}
                </div>
              )}
            </div>
          ) : (
            <div className="flex items-center justify-between p-4 bg-blue-50 rounded-3xl border border-blue-100">
              <div className="flex items-center gap-3">
                <div className="w-11 h-11 rounded-2xl bg-blue-600 flex items-center justify-center text-white font-black text-lg shadow-lg shadow-blue-200">{selectedClient.name.charAt(0)}</div>
                <div>
                  <p className="font-black text-blue-900 leading-none">{selectedClient.name}</p>
                  <p className="text-[10px] text-blue-500 font-black uppercase mt-1 tracking-widest">Deuda: ${selectedClient.currentDebt.toLocaleString()}</p>
                </div>
              </div>
              <button onClick={() => setSelectedClient(null)} className="p-2 bg-white text-rose-500 rounded-xl border border-rose-100 hover:bg-rose-50"><X size={18}/></button>
            </div>
          )}
        </div>
      </div>

      {/* Cart Summary (Mobile Floating Button) */}
      <div className="lg:hidden fixed bottom-20 left-4 right-4 z-[90]">
        <button 
          onClick={() => setIsCartVisible(true)}
          disabled={cart.length === 0}
          className={`w-full py-5 rounded-[2rem] font-black text-sm uppercase tracking-widest flex items-center justify-between px-8 shadow-2xl transition-all ${cart.length > 0 ? 'bg-blue-600 text-white animate-bounce-short' : 'bg-slate-200 text-slate-400 opacity-50'}`}
        >
          <div className="flex items-center gap-3">
             <ShoppingCart size={20} />
             <span>Ver Carrito ({cart.length})</span>
          </div>
          <span className="text-lg">${total.toLocaleString()}</span>
        </button>
      </div>

      {/* Checkout Area (Desktop static, Mobile Drawer) */}
      <div className={`fixed lg:static inset-0 z-[100] lg:z-auto bg-slate-900/60 lg:bg-transparent backdrop-blur-sm lg:backdrop-blur-none transition-all duration-300 ${isCartVisible ? 'opacity-100 visible' : 'opacity-0 invisible lg:visible lg:opacity-100'}`}>
        <div className={`absolute lg:static bottom-0 left-0 right-0 w-full lg:w-[460px] max-h-[90vh] lg:max-h-none bg-white lg:bg-white rounded-t-[3rem] lg:rounded-[3rem] border-t lg:border border-slate-200 shadow-2xl flex flex-col transform transition-transform duration-300 ${isCartVisible ? 'translate-y-0' : 'translate-y-full lg:translate-y-0'}`}>
          <div className="p-6 lg:p-8 bg-slate-50 border-b border-slate-200 flex items-center justify-between sticky top-0 z-10">
            <div className="flex items-center gap-3">
              <ShoppingCart size={22} className="text-blue-600" />
              <h3 className="font-black text-slate-800 uppercase tracking-widest text-xs lg:text-sm">Resumen de Venta</h3>
            </div>
            <button onClick={() => setIsCartVisible(false)} className="lg:hidden p-2 text-slate-400"><ChevronDown size={28}/></button>
          </div>

          <div className="flex-1 overflow-y-auto p-6 lg:p-8 space-y-6 lg:space-y-8 hide-scrollbar">
            {cart.map(item => (
              <div key={item.productId} className="flex items-start justify-between animate-in slide-in-from-right-4 duration-300">
                <div className="flex-1 pr-4">
                  <p className="text-sm lg:text-base font-black text-slate-800 leading-tight mb-0.5">{item.name}</p>
                  <p className="text-xs text-slate-400 font-black">${item.price.toLocaleString()} c/u</p>
                </div>
                <div className="flex items-center gap-2 bg-slate-100 rounded-2xl p-1.5 border border-slate-200/50">
                  <button onClick={() => updateQuantity(item.productId, -1)} className="p-1.5 bg-white text-slate-400 rounded-xl shadow-sm"><Minus size={14}/></button>
                  <span className="text-sm font-black w-8 text-center text-slate-800">{item.quantity}</span>
                  <button onClick={() => updateQuantity(item.productId, 1)} className="p-1.5 bg-white text-slate-400 rounded-xl shadow-sm"><Plus size={14}/></button>
                </div>
              </div>
            ))}
            {cart.length === 0 && (
              <div className="h-40 flex flex-col items-center justify-center text-slate-300">
                <ShoppingCart size={48} className="opacity-20 mb-3" />
                <p className="text-[10px] font-black uppercase tracking-widest">Carrito Vacío</p>
              </div>
            )}
          </div>

          <div className="p-8 lg:p-10 border-t border-slate-100 bg-white space-y-8">
            <div className="flex items-center justify-between">
              <span className="font-black text-slate-400 uppercase tracking-widest text-[10px] lg:text-xs">Subtotal Neto</span>
              <span className="font-black text-3xl lg:text-5xl text-blue-600 tracking-tighter">${total.toLocaleString()}</span>
            </div>

            <div className="space-y-4">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1 leading-none">Tipo de Operación</p>
              <div className="grid grid-cols-2 gap-4">
                <button onClick={() => setSaleStatus(SaleStatus.COMPLETED)} className={`flex flex-col items-center justify-center py-5 rounded-3xl border-2 transition-all ${saleStatus === SaleStatus.COMPLETED ? 'border-blue-600 bg-blue-50 text-blue-700' : 'border-slate-100 bg-white text-slate-400 opacity-60'}`}>
                  <Wallet size={24} className="mb-2" />
                  <span className="text-[10px] font-black uppercase tracking-wider">Efectivo</span>
                </button>
                <button onClick={() => setSaleStatus(SaleStatus.CREDIT)} className={`flex flex-col items-center justify-center py-5 rounded-3xl border-2 transition-all ${saleStatus === SaleStatus.CREDIT ? 'border-amber-500 bg-amber-50 text-amber-700' : 'border-slate-100 bg-white text-slate-400 opacity-60'}`}>
                  <CreditCard size={24} className="mb-2" />
                  <span className="text-[10px] font-black uppercase tracking-wider">Crédito</span>
                </button>
              </div>
            </div>

            {saleStatus === SaleStatus.CREDIT && (
              <div className="space-y-2 animate-in slide-in-from-top-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Monto de Abono</label>
                <input type="number" className="w-full px-6 py-5 bg-amber-50 border border-amber-100 rounded-3xl text-2xl font-black text-amber-700 outline-none" value={amountPaid} onChange={(e) => setAmountPaid(e.target.value)} placeholder="0.00" />
              </div>
            )}

            <button onClick={handleProcessSale} disabled={cart.length === 0} className="w-full bg-slate-900 text-white py-6 rounded-[2rem] font-black text-xl lg:text-2xl transition-all shadow-2xl active:scale-95 uppercase tracking-[0.2em] shadow-slate-300">
              Cerrar Venta
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

