import React, { useMemo, useState, useEffect } from 'react';
import { XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, AreaChart, Area, BarChart, Bar, Cell } from 'recharts';
import { dbService } from '../services/dbService';
import { DollarSign, TrendingDown, Package, Users, FileText, PieChart, Printer, Loader2, ArrowUpRight, BarChart3, Layers } from 'lucide-react';
import { Sale, Expense, Product, Client } from '../types';

type DashboardPeriod = 'semana' | 'mes' | 'año';
const COLORS = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899', '#06b6d4'];

const DashboardView: React.FC = () => {
  const [sales, setSales] = useState<Sale[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [clients, setClients] = useState<Client[]>([]);
  const [period, setPeriod] = useState<DashboardPeriod>('semana');
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);
      try {
        const [s, e, p, c] = await Promise.all([dbService.getSales(), dbService.getExpenses(), dbService.getProducts(), dbService.getClients()]);
        setSales(s); setExpenses(e); setProducts(p); setClients(c);
      } catch (err) { console.error(err); } finally { setLoading(false); }
    };
    fetchData();
  }, []);

  const filteredData = useMemo(() => {
    const now = new Date(); let startDate = new Date();
    if (period === 'semana') startDate.setDate(now.getDate() - 7);
    else if (period === 'mes') startDate.setMonth(now.getMonth() - 1);
    else if (period === 'año') startDate.setFullYear(now.getFullYear() - 1);
    return { fSales: sales.filter(s => new Date(s.date) >= startDate), fExpenses: expenses.filter(e => new Date(e.date) >= startDate) };
  }, [sales, expenses, period]);

  const stats = useMemo(() => {
    const revenue = filteredData.fSales.reduce((acc, s) => acc + (s.amountPaid || 0), 0);
    const cost = filteredData.fExpenses.reduce((acc, e) => acc + e.amount, 0);
    return { revenue, expenses: cost, profit: revenue - cost, pending: clients.reduce((acc, c) => acc + c.currentDebt, 0) };
  }, [filteredData, clients]);

  const chartData = useMemo(() => {
    const days = period === 'semana' ? 7 : period === 'mes' ? 30 : 12;
    const data = [];
    for (let i = days; i >= 0; i--) {
      const d = new Date();
      if (period === 'año') d.setMonth(d.getMonth() - i); else d.setDate(d.getDate() - i);
      const daySales = sales.filter(s => new Date(s.date).toDateString() === d.toDateString());
      const dayExpenses = expenses.filter(e => new Date(e.date).toDateString() === d.toDateString());
      data.push({
        name: period === 'año' ? d.toLocaleString('es', { month: 'short' }) : d.getDate().toString(),
        ingresos: daySales.reduce((acc, s) => acc + (s.amountPaid || 0), 0),
        gastos: dayExpenses.reduce((acc, e) => acc + e.amount, 0)
      });
    }
    return data;
  }, [sales, expenses, period]);

  const categoryStats = useMemo(() => {
    const map: Record<string, any> = {};
    const prodMap = products.reduce((acc, p) => { acc[p.id] = p.category || 'Varios'; return acc; }, {} as any);
    filteredData.fSales.forEach(s => s.items.forEach(it => {
      const cat = prodMap[it.productId] || 'Varios';
      if (!map[cat]) map[cat] = { category: cat, money: 0, units: 0 };
      map[cat].money += it.price * it.quantity; map[cat].units += it.quantity;
    }));
    return Object.values(map).sort((a, b) => b.money - a.money).slice(0, 5);
  }, [filteredData, products]);

  const StatCard = ({ title, value, icon: Icon, color, sub }: any) => (
    <div className="bg-white p-5 lg:p-7 rounded-[2rem] border border-slate-200 shadow-sm flex items-start justify-between relative overflow-hidden">
      <div className="relative z-10">
        <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">{title}</p>
        <h3 className="text-xl lg:text-3xl font-black text-slate-800 tracking-tighter">${value.toLocaleString()}</h3>
        <p className="text-[8px] font-bold text-slate-400 mt-1 uppercase tracking-tight">{sub}</p>
      </div>
      <div className={`p-3 rounded-2xl ${color} shadow-lg shadow-current/10 relative z-10`}>
        <Icon size={20} className="lg:size-24" />
      </div>
    </div>
  );

  if (loading) return <div className="h-full flex items-center justify-center"><Loader2 className="animate-spin text-blue-600" size={40} /></div>;

  return (
    <div className="space-y-6 lg:space-y-10 pb-10">
      <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-6">
        <div>
          <h1 className="text-2xl lg:text-4xl font-black text-slate-800 tracking-tighter">Analítica</h1>
          <p className="text-xs lg:text-lg text-slate-500 font-medium">Pulso operativo de tu comercio.</p>
        </div>
        <div className="flex bg-white p-1 rounded-2xl border border-slate-200 shadow-sm w-full lg:w-auto">
          {(['semana', 'mes', 'año'] as DashboardPeriod[]).map(p => (
            <button key={p} onClick={() => setPeriod(p)} className={`flex-1 lg:px-7 py-3 text-[10px] font-black uppercase tracking-widest rounded-xl transition-all ${period === p ? 'bg-blue-600 text-white shadow-xl' : 'text-slate-400 hover:text-slate-600'}`}>
              {p}
            </button>
          ))}
        </div>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 lg:gap-8">
        <StatCard title="Ingreso Neto" value={stats.revenue} icon={DollarSign} color="bg-blue-50 text-blue-600" sub="Ventas Cobradas" />
        <StatCard title="Gasto Operativo" value={stats.expenses} icon={TrendingDown} color="bg-rose-50 text-rose-600" sub="Salidas y Compras" />
        <StatCard title="Margen Real" value={stats.profit} icon={PieChart} color="bg-emerald-50 text-emerald-600" sub="Flujo Neto" />
        <StatCard title="Por Cobrar" value={stats.pending} icon={Users} color="bg-amber-50 text-amber-600" sub="Deuda Clientes" />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 lg:gap-10">
        <div className="lg:col-span-2 bg-white p-6 lg:p-10 rounded-[3rem] border border-slate-200 shadow-sm relative overflow-hidden">
          <h3 className="text-[10px] lg:text-xs font-black text-slate-800 uppercase tracking-widest mb-8 flex items-center gap-2">
            <ArrowUpRight className="text-blue-600" size={16} /> Tendencia de Flujo
          </h3>
          <div className="h-64 lg:h-96 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={chartData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 10, fontWeight: 700}} dy={10} />
                <YAxis axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 10, fontWeight: 700}} />
                <Tooltip contentStyle={{borderRadius: '20px', border: 'none', boxShadow: '0 25px 50px -12px rgb(0 0 0 / 0.1)'}} />
                <Area type="monotone" dataKey="ingresos" stroke="#3b82f6" strokeWidth={4} fill="#3b82f6" fillOpacity={0.05} />
                <Area type="monotone" dataKey="gastos" stroke="#f43f5e" strokeWidth={4} fill="#f43f5e" fillOpacity={0.05} />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white p-6 lg:p-10 rounded-[3rem] border border-slate-200 shadow-sm">
          <h3 className="text-[10px] lg:text-xs font-black text-slate-800 uppercase tracking-widest mb-8 flex items-center gap-2">
            <BarChart3 className="text-blue-600" size={16} /> Top Categorías ($)
          </h3>
          <div className="h-64 lg:h-96 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={categoryStats} layout="vertical">
                <XAxis type="number" hide />
                <YAxis dataKey="category" type="category" axisLine={false} tickLine={false} tick={{fill: '#64748b', fontSize: 10, fontWeight: 800}} width={80} />
                <Tooltip cursor={{fill: 'transparent'}} />
                <Bar dataKey="money" radius={[0, 10, 10, 0]} barSize={20}>
                  {categoryStats.map((e, i) => <Cell key={i} fill={COLORS[i % COLORS.length]} />)}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>
    </div>
  );
};
export default DashboardView;

import React, { useState, useEffect, useMemo } from 'react';
import { dbService } from '../services/dbService';
import { SaleStatus, Sale, Client } from '../types';
import { CreditCard, AlertCircle, RefreshCw, Loader2, DollarSign, CheckCircle2, Circle, Calendar, Hash, UserCircle, X, ChevronRight } from 'lucide-react';

const CreditView: React.FC = () => {
  const [sales, setSales] = useState<Sale[]>([]);
  const [clients, setClients] = useState<Client[]>([]);
  const [isAbonoOpen, setIsAbonoOpen] = useState(false);
  const [selectedClient, setSelectedClient] = useState<Client | null>(null);
  const [selectedSaleIds, setSelectedSaleIds] = useState<Set<string>>(new Set());
  const [abonoAmount, setAbonoAmount] = useState<number>(0);
  const [loading, setLoading] = useState(false);

  const fetchData = async () => {
    try {
      const [allSales, allClients] = await Promise.all([
        dbService.getSales(),
        dbService.getClients()
      ]);
      setSales(allSales.filter(s => s.status === SaleStatus.CREDIT && (s.total - s.amountPaid) > 0));
      setClients(allClients.filter(c => c.currentDebt > 0));
    } catch (err) {
      console.error("Error fetching credit data:", err);
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  const handleRegisterAbono = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!selectedClient || selectedSaleIds.size === 0 || abonoAmount <= 0) return;

    setLoading(true);
    try {
      await dbService.processDistributedAbono(
        selectedClient.id, 
        abonoAmount, 
        Array.from(selectedSaleIds)
      );
      await fetchData();
      setIsAbonoOpen(false);
      resetModal();
      alert('Abono procesado con éxito.');
    } catch (err) {
      alert('Error al procesar el abono.');
    } finally {
      setLoading(false);
    }
  };

  const resetModal = () => {
    setSelectedClient(null);
    setSelectedSaleIds(new Set());
    setAbonoAmount(0);
  };

  const toggleSaleSelection = (id: string) => {
    const next = new Set(selectedSaleIds);
    if (next.has(id)) next.delete(id);
    else next.add(id);
    setSelectedSaleIds(next);
  };

  const pendingSalesForClient = useMemo(() => {
    if (!selectedClient) return [];
    return sales.filter(s => s.clientId === selectedClient.id);
  }, [selectedClient, sales]);

  const totalOwedBySelection = useMemo(() => {
    return pendingSalesForClient
      .filter(s => selectedSaleIds.has(s.id))
      .reduce((acc, s) => acc + (s.total - s.amountPaid), 0);
  }, [pendingSalesForClient, selectedSaleIds]);

  return (
    <div className="space-y-6 animate-in fade-in duration-500 pb-12">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-xl lg:text-3xl font-black text-slate-800 tracking-tight">Cobranzas</h1>
          <p className="text-xs lg:text-base text-slate-500 font-medium">Gestión de créditos y saldos pendientes.</p>
        </div>
        <button 
          onClick={() => { resetModal(); setIsAbonoOpen(true); }}
          className="bg-emerald-600 hover:bg-emerald-700 text-white px-5 py-3 lg:py-4 rounded-2xl font-black text-xs lg:text-sm uppercase tracking-widest flex items-center justify-center gap-2 shadow-lg shadow-emerald-100 transition-all active:scale-95"
        >
          <DollarSign size={18} /> Registrar Abono
        </button>
      </div>

      {/* Vista de Tabla/Cards de Clientes Deudores */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {clients.map(client => (
          <div key={client.id} className="bg-white p-5 rounded-3xl border border-slate-200 shadow-sm flex items-center justify-between group hover:border-emerald-200 transition-all">
            <div className="flex items-center gap-3">
              <div className="w-12 h-12 rounded-2xl bg-amber-50 text-amber-600 flex items-center justify-center font-black text-lg">
                {client.name.charAt(0)}
              </div>
              <div>
                <span className="font-black text-slate-800 leading-tight block">{client.name}</span>
                <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">{client.phone || 'Sin contacto'}</p>
              </div>
            </div>
            <div className="text-right">
              <p className="text-[9px] font-black text-slate-400 uppercase tracking-tighter">Deuda Total</p>
              <span className="font-black text-rose-600 text-lg tracking-tight">${client.currentDebt.toLocaleString()}</span>
            </div>
          </div>
        ))}
        {clients.length === 0 && (
          <div className="col-span-full py-16 text-center bg-white rounded-[2rem] border-2 border-dashed border-slate-100">
            <CreditCard className="mx-auto text-slate-100 mb-2" size={48} />
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Sin deudas pendientes</p>
          </div>
        )}
      </div>

      {/* Modal de Abono - RE-DISEÑADO PARA MÓVIL (Compacto) */}
      {isAbonoOpen && (
        <div className="fixed inset-0 z-[100] flex items-end sm:items-center justify-center p-0 sm:p-4">
          <div className="absolute inset-0 bg-slate-900/40 backdrop-blur-sm" onClick={() => setIsAbonoOpen(false)} />
          <div className="relative bg-white w-full max-w-xl h-[95vh] sm:h-auto sm:max-h-[90vh] rounded-t-[2.5rem] sm:rounded-[2.5rem] shadow-2xl overflow-hidden animate-in slide-in-from-bottom sm:zoom-in-95 duration-300 flex flex-col">

            {/* Cabecera Compacta */}
            <div className="px-6 py-4 border-b border-slate-100 flex items-center justify-between bg-white sticky top-0 z-10">
              <h3 className="text-sm font-black text-slate-800 uppercase tracking-tighter flex items-center gap-2">
                <DollarSign className="text-emerald-500" size={18} /> Conciliación Rápida
              </h3>
              <button onClick={() => setIsAbonoOpen(false)} className="p-2 text-slate-400"><X size={24} /></button>
            </div>

            <form onSubmit={handleRegisterAbono} className="p-5 lg:p-8 space-y-4 overflow-y-auto hide-scrollbar flex-1 flex flex-col">

              {/* Inputs Principales Compactos */}
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                <div className="space-y-1">
                  <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">1. Cliente</label>
                  <select 
                    required 
                    className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl outline-none font-bold text-sm focus:ring-2 focus:ring-emerald-500"
                    onChange={(e) => {
                      setSelectedClient(clients.find(c => c.id === e.target.value) || null);
                      setSelectedSaleIds(new Set());
                    }}
                    value={selectedClient?.id || ''}
                  >
                    <option value="">Seleccionar Moroso</option>
                    {clients.map(c => (
                      <option key={c.id} value={c.id}>{c.name} (${c.currentDebt})</option>
                    ))}
                  </select>
                </div>

                <div className="space-y-1">
                  <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">2. Monto Abono ($)</label>
                  <input 
                    name="amount" 
                    type="number" 
                    step="0.01" 
                    required 
                    className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl outline-none font-black text-lg text-emerald-600 focus:ring-2 focus:ring-emerald-500" 
                    placeholder="0.00"
                    value={abonoAmount || ''}
                    onChange={(e) => setAbonoAmount(Number(e.target.value))}
                  />
                </div>
              </div>

              {selectedClient && (
                <div className="space-y-2 flex-1 flex flex-col overflow-hidden">
                  <div className="flex items-center justify-between px-1">
                    <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest">3. Aplicar a Facturas</label>
                    <span className="text-[9px] font-black text-blue-600 uppercase bg-blue-50 px-2 py-0.5 rounded-md">
                      {selectedSaleIds.size} seleccionada(s)
                    </span>
                  </div>

                  {/* Lista de Facturas - ESTILO DENSO */}
                  <div className="bg-slate-50 rounded-2xl border border-slate-200 overflow-y-auto p-2 space-y-1 flex-1 hide-scrollbar">
                    {pendingSalesForClient.map(sale => {
                      const isSelected = selectedSaleIds.has(sale.id);
                      const saldo = sale.total - sale.amountPaid;

                      return (
                        <div 
                          key={sale.id}
                          onClick={() => toggleSaleSelection(sale.id)}
                          className={`p-3 rounded-xl border transition-all cursor-pointer flex items-center justify-between ${
                            isSelected 
                              ? 'bg-white border-emerald-500 shadow-sm ring-2 ring-emerald-50' 
                              : 'bg-white/50 border-slate-100 hover:border-slate-300'
                          }`}
                        >
                          <div className="flex items-center gap-3">
                             <div className={isSelected ? 'text-emerald-500' : 'text-slate-200'}>
                               {isSelected ? <CheckCircle2 size={18} /> : <Circle size={18} />}
                             </div>
                             <div>
                                <div className="flex items-center gap-2">
                                  <span className="text-[10px] font-black text-slate-800">#{sale.id.slice(0, 5)}</span>
                                  <span className="text-[9px] font-bold text-slate-400 uppercase">{new Date(sale.date).toLocaleDateString()}</span>
                                </div>
                                <p className="text-[9px] text-slate-400 font-medium">Total: ${sale.total.toLocaleString()}</p>
                             </div>
                          </div>
                          <div className="text-right">
                             <span className={`text-sm font-black ${isSelected ? 'text-emerald-600' : 'text-slate-600'}`}>
                               ${saldo.toLocaleString()}
                             </span>
                          </div>
                        </div>
                      );
                    })}
                  </div>
                </div>
              )}

              {/* Pie de Modal Compacto */}
              <div className="bg-slate-900 rounded-2xl p-4 text-white space-y-1">
                <div className="flex justify-between items-center opacity-50">
                   <span className="text-[8px] font-black uppercase tracking-widest">Deuda Seleccionada</span>
                   <span className="text-[10px] font-bold">${totalOwedBySelection.toLocaleString()}</span>
                </div>
                <div className="flex justify-between items-center">
                   <span className="text-[10px] font-black uppercase tracking-widest text-emerald-400">Restante estimado</span>
                   <span className="text-xl font-black text-emerald-400">
                     ${Math.max(0, totalOwedBySelection - abonoAmount).toLocaleString()}
                   </span>
                </div>
              </div>

              <button 
                disabled={loading || !selectedClient || selectedSaleIds.size === 0 || abonoAmount <= 0} 
                type="submit" 
                className="w-full bg-slate-900 text-white py-4 rounded-xl font-black text-base shadow-xl flex items-center justify-center gap-2 transition-all active:scale-95 disabled:opacity-30 uppercase tracking-widest"
              >
                {loading ? <Loader2 className="animate-spin" size={20} /> : 'Finalizar Pago'}
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default CreditView;

import React, { useMemo, useState, useEffect } from 'react';
import { XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, AreaChart, Area, BarChart, Bar, Cell } from 'recharts';
import { dbService } from '../services/dbService';
import { DollarSign, TrendingDown, Package, Users, FileText, PieChart, Printer, Loader2, ArrowUpRight, BarChart3, Layers } from 'lucide-react';
import { Sale, Expense, Product, Client } from '../types';

type DashboardPeriod = 'semana' | 'mes' | 'año';
const COLORS = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899', '#06b6d4'];

const DashboardView: React.FC = () => {
  const [sales, setSales] = useState<Sale[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [clients, setClients] = useState<Client[]>([]);
  const [period, setPeriod] = useState<DashboardPeriod>('semana');
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);
      try {
        const [s, e, p, c] = await Promise.all([dbService.getSales(), dbService.getExpenses(), dbService.getProducts(), dbService.getClients()]);
        setSales(s); setExpenses(e); setProducts(p); setClients(c);
      } catch (err) { console.error(err); } finally { setLoading(false); }
    };
    fetchData();
  }, []);

  const filteredData = useMemo(() => {
    const now = new Date(); let startDate = new Date();
    if (period === 'semana') startDate.setDate(now.getDate() - 7);
    else if (period === 'mes') startDate.setMonth(now.getMonth() - 1);
    else if (period === 'año') startDate.setFullYear(now.getFullYear() - 1);
    return { fSales: sales.filter(s => new Date(s.date) >= startDate), fExpenses: expenses.filter(e => new Date(e.date) >= startDate) };
  }, [sales, expenses, period]);

  const stats = useMemo(() => {
    const revenue = filteredData.fSales.reduce((acc, s) => acc + (s.amountPaid || 0), 0);
    const cost = filteredData.fExpenses.reduce((acc, e) => acc + e.amount, 0);
    return { revenue, expenses: cost, profit: revenue - cost, pending: clients.reduce((acc, c) => acc + c.currentDebt, 0) };
  }, [filteredData, clients]);

  const chartData = useMemo(() => {
    const days = period === 'semana' ? 7 : period === 'mes' ? 30 : 12;
    const data = [];
    for (let i = days; i >= 0; i--) {
      const d = new Date();
      if (period === 'año') d.setMonth(d.getMonth() - i); else d.setDate(d.getDate() - i);
      const daySales = sales.filter(s => new Date(s.date).toDateString() === d.toDateString());
      const dayExpenses = expenses.filter(e => new Date(e.date).toDateString() === d.toDateString());
      data.push({
        name: period === 'año' ? d.toLocaleString('es', { month: 'short' }) : d.getDate().toString(),
        ingresos: daySales.reduce((acc, s) => acc + (s.amountPaid || 0), 0),
        gastos: dayExpenses.reduce((acc, e) => acc + e.amount, 0)
      });
    }
    return data;
  }, [sales, expenses, period]);

  const categoryStats = useMemo(() => {
    const map: Record<string, any> = {};
    const prodMap = products.reduce((acc, p) => { acc[p.id] = p.category || 'Varios'; return acc; }, {} as any);
    filteredData.fSales.forEach(s => s.items.forEach(it => {
      const cat = prodMap[it.productId] || 'Varios';
      if (!map[cat]) map[cat] = { category: cat, money: 0, units: 0 };
      map[cat].money += it.price * it.quantity; map[cat].units += it.quantity;
    }));
    return Object.values(map).sort((a, b) => b.money - a.money).slice(0, 5);
  }, [filteredData, products]);

  const StatCard = ({ title, value, icon: Icon, iconColor, sub }: any) => (
    <div className="bg-white p-6 lg:p-8 rounded-[2rem] lg:rounded-[3rem] border border-slate-200 shadow-sm relative overflow-hidden group transition-all hover:border-blue-100 h-full">
      <div className="relative z-10">
        <p className="text-[9px] lg:text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">{title}</p>
        <h3 className="text-xl lg:text-4xl font-black text-slate-800 tracking-tighter leading-none">${value.toLocaleString()}</h3>
        <p className="text-[8px] lg:text-[10px] font-bold text-slate-400 mt-2 uppercase tracking-tight">{sub}</p>
      </div>
      {/* Watermark Icon - Background Effect */}
      <div className={`absolute -right-4 lg:-right-6 -bottom-4 lg:-bottom-6 ${iconColor} opacity-[0.08] lg:opacity-[0.06] pointer-events-none transition-transform duration-700 group-hover:scale-125 group-hover:-rotate-12`}>
        <Icon size={140} strokeWidth={1} />
      </div>
    </div>
  );

  if (loading) return <div className="h-full flex items-center justify-center"><Loader2 className="animate-spin text-blue-600" size={40} /></div>;

  return (
    <div className="space-y-6 lg:space-y-10 pb-10">
      <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-6">
        <div>
          <h1 className="text-2xl lg:text-4xl font-black text-slate-800 tracking-tighter">Analítica</h1>
          <p className="text-xs lg:text-lg text-slate-500 font-medium">Pulso operativo de tu comercio.</p>
        </div>
        <div className="flex bg-white p-1 rounded-2xl border border-slate-200 shadow-sm w-full lg:w-auto">
          {(['semana', 'mes', 'año'] as DashboardPeriod[]).map(p => (
            <button key={p} onClick={() => setPeriod(p)} className={`flex-1 lg:px-7 py-3 text-[10px] font-black uppercase tracking-widest rounded-xl transition-all ${period === p ? 'bg-blue-600 text-white shadow-xl' : 'text-slate-400 hover:text-slate-600'}`}>
              {p}
            </button>
          ))}
        </div>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 lg:gap-8">
        <StatCard title="Ingreso Neto" value={stats.revenue} icon={DollarSign} iconColor="text-blue-600" sub="Ventas Cobradas" />
        <StatCard title="Gasto Operativo" value={stats.expenses} icon={TrendingDown} iconColor="text-rose-600" sub="Salidas y Compras" />
        <StatCard title="Margen Real" value={stats.profit} icon={PieChart} iconColor="text-emerald-600" sub="Flujo Neto" />
        <StatCard title="Por Cobrar" value={stats.pending} icon={Users} iconColor="text-amber-600" sub="Deuda Clientes" />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 lg:gap-10">
        <div className="lg:col-span-2 bg-white p-6 lg:p-10 rounded-[3rem] border border-slate-200 shadow-sm relative overflow-hidden">
          <h3 className="text-[10px] lg:text-xs font-black text-slate-800 uppercase tracking-widest mb-8 flex items-center gap-2">
            <ArrowUpRight className="text-blue-600" size={16} /> Tendencia de Flujo
          </h3>
          <div className="h-64 lg:h-96 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={chartData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 10, fontWeight: 700}} dy={10} />
                <YAxis axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 10, fontWeight: 700}} />
                <Tooltip contentStyle={{borderRadius: '20px', border: 'none', boxShadow: '0 25px 50px -12px rgb(0 0 0 / 0.1)'}} />
                <Area type="monotone" dataKey="ingresos" stroke="#3b82f6" strokeWidth={4} fill="#3b82f6" fillOpacity={0.05} />
                <Area type="monotone" dataKey="gastos" stroke="#f43f5e" strokeWidth={4} fill="#f43f5e" fillOpacity={0.05} />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white p-6 lg:p-10 rounded-[3rem] border border-slate-200 shadow-sm">
          <h3 className="text-[10px] lg:text-xs font-black text-slate-800 uppercase tracking-widest mb-8 flex items-center gap-2">
            <BarChart3 className="text-blue-600" size={16} /> Top Categorías ($)
          </h3>
          <div className="h-64 lg:h-96 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={categoryStats} layout="vertical">
                <XAxis type="number" hide />
                <YAxis dataKey="category" type="category" axisLine={false} tickLine={false} tick={{fill: '#64748b', fontSize: 10, fontWeight: 800}} width={80} />
                <Tooltip cursor={{fill: 'transparent'}} />
                <Bar dataKey="money" radius={[0, 10, 10, 0]} barSize={20}>
                  {categoryStats.map((e, i) => <Cell key={i} fill={COLORS[i % COLORS.length]} />)}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>
    </div>
  );
};
export default DashboardView;

import React, { useState, useMemo, useEffect, useRef } from 'react';
