import React, { useState, useMemo, useEffect, useRef } from 'react';
import { dbService } from '../services/dbService';
import { Product, Client, SaleItem, SaleStatus, Sale } from '../types';
import { ShoppingCart, Search, User, Trash2, Plus, Minus, CreditCard, Wallet, ScanLine, UserPlus, Loader2, X, ChevronDown, Camera } from 'lucide-react';
import { Html5Qrcode } from "html5-qrcode";

const SalesView: React.FC = () => {
  const [products, setProducts] = useState<Product[]>([]);
  const [clients, setClients] = useState<Client[]>([]);
  const [cart, setCart] = useState<SaleItem[]>([]);
  const [selectedClient, setSelectedClient] = useState<Client | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [clientSearch, setClientSearch] = useState('');
  const [saleStatus, setSaleStatus] = useState<SaleStatus>(SaleStatus.COMPLETED);
  const [amountPaid, setAmountPaid] = useState<string>('');
  const [isCartVisible, setIsCartVisible] = useState(false);
  const [isScannerOpen, setIsScannerOpen] = useState(false);
  const [scannerLoading, setScannerLoading] = useState(false);

  const scannerRef = useRef<Html5Qrcode | null>(null);
  const lastProcessedRef = useRef<number>(0);

  useEffect(() => {
    dbService.getProducts().then(setProducts).catch(console.error);
    dbService.getClients().then(setClients).catch(console.error);
    return () => {
      if (scannerRef.current) {
        scannerRef.current.stop().catch(console.error);
      }
    };
  }, []);

  const addToCart = (product: Product) => {
    const now = Date.now();
    if (now - lastProcessedRef.current < 200) return;
    lastProcessedRef.current = now;
    if (product.stock <= 0) {
      alert("¡Sin Stock!");
      return;
    }
    setCart(prev => {
      const existing = prev.find(item => item.productId === product.id);
      if (existing) {
        return prev.map(item => item.productId === product.id ? { ...item, quantity: item.quantity + 1 } : item);
      }
      return [...prev, { productId: product.id, name: product.name, price: product.price, quantity: 1 }];
    });
    setSearchTerm('');
    if (navigator.vibrate) navigator.vibrate(50);
  };

  const startScanner = async () => {
    setIsScannerOpen(true);
    setScannerLoading(true);
    try {
      const scanner = new Html5Qrcode("scanner-region");
      scannerRef.current = scanner;
      await scanner.start(
        { facingMode: "environment" },
        { fps: 10, qrbox: { width: 250, height: 150 } },
        (decodedText) => {
          const product = products.find(p => p.barcode === decodedText);
          if (product) {
            addToCart(product);
            stopScanner();
          }
        },
        () => {}
      );
      setScannerLoading(false);
    } catch (err) {
      console.error(err);
      alert("Error al acceder a la cámara");
      setIsScannerOpen(false);
    }
  };

  const stopScanner = () => {
    if (scannerRef.current) {
      scannerRef.current.stop().then(() => {
        setIsScannerOpen(false);
        scannerRef.current = null;
      }).catch(console.error);
    } else {
      setIsScannerOpen(false);
    }
  };

  const filteredProducts = useMemo(() => {
    if (!searchTerm || searchTerm.length < 2) return [];
    return products.filter(p => p.name.toLowerCase().includes(searchTerm.toLowerCase()) || (p.barcode && p.barcode.includes(searchTerm)));
  }, [products, searchTerm]);

  const total = useMemo(() => cart.reduce((acc, item) => acc + (item.price * item.quantity), 0), [cart]);

  const handleProcessSale = async () => {
    if (cart.length === 0) return;
    if (saleStatus === SaleStatus.CREDIT && !selectedClient) {
      alert('Seleccione un cliente');
      return;
    }
    const sale: Partial<Sale> = {
      id: crypto.randomUUID(),
      clientId: selectedClient?.id,
      items: cart,
      total,
      date: new Date().toISOString(),
      status: saleStatus,
      amountPaid: saleStatus === SaleStatus.CREDIT ? Number(amountPaid) : total
    };
    try {
      await dbService.createSale(sale);
      setCart([]);
      setSelectedClient(null);
      setAmountPaid('');
      setIsCartVisible(false);
      dbService.getProducts().then(setProducts);
      alert('Venta procesada');
    } catch (err) { alert("Error"); }
  };

  return (
    <div className="h-full flex flex-col lg:flex-row gap-6 animate-in fade-in pb-20 lg:pb-0">
      <div className="flex-1 flex flex-col space-y-4 lg:space-y-6">
        <div className="bg-white p-5 lg:p-7 rounded-[2rem] border border-slate-200 shadow-sm space-y-4">
          <div className="flex items-center justify-between">
            <h3 className="text-xs font-black text-slate-800 flex items-center gap-2 uppercase tracking-widest">
              <ScanLine size={20} className="text-blue-500" /> Terminal Táctil
            </h3>
            <button 
              onClick={startScanner}
              className="lg:hidden p-3 bg-blue-600 text-white rounded-2xl shadow-lg flex items-center gap-2 font-black text-[10px] uppercase tracking-widest active:scale-95 transition-all"
            >
              <Camera size={18} /> Escanear
            </button>
          </div>
          <div className="relative">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" size={24} />
            <input 
              type="text" 
              placeholder="Producto o Código..." 
              className="w-full pl-14 pr-4 py-4 lg:py-6 bg-slate-50 border border-slate-200 rounded-3xl outline-none text-base lg:text-xl font-black transition-all"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
            {filteredProducts.length > 0 && (
              <div className="absolute top-full left-0 right-0 mt-3 bg-white border border-slate-200 rounded-[2.5rem] shadow-2xl z-[80] overflow-hidden">
                {filteredProducts.map(p => (
                  <button key={p.id} onClick={() => addToCart(p)} className="w-full p-5 flex items-center justify-between hover:bg-blue-50 transition-all text-left border-b last:border-0">
                    <div>
                      <p className="font-black text-slate-800">{p.name}</p>
                      <p className="text-[10px] font-black uppercase text-slate-400">Stock: {p.stock} uds</p>
                    </div>
                    <span className="font-black text-blue-600">${p.price.toLocaleString()}</span>
                  </button>
                ))}
              </div>
            )}
          </div>
        </div>

        {/* Client Selection (Assume exists as per original code) */}
      </div>

      {/* Cart Summary & Checkout (Assume exists as per original code) */}

      {/* Barcode Scanner Modal */}
      {isScannerOpen && (
        <div className="fixed inset-0 z-[150] flex flex-col bg-black/95 animate-in fade-in duration-300">
           <div className="flex items-center justify-between p-6 text-white">
              <h4 className="font-black text-xs uppercase tracking-[0.2em]">Escáner de Barras</h4>
              <button onClick={stopScanner} className="p-3 bg-white/10 rounded-2xl"><X size={24}/></button>
           </div>
           <div className="flex-1 flex flex-col items-center justify-center p-4">
              <div className="relative w-full max-w-sm aspect-video bg-black rounded-3xl border-2 border-white/20 overflow-hidden shadow-2xl">
                 {scannerLoading && (
                   <div className="absolute inset-0 flex items-center justify-center z-10 bg-black/50">
                     <Loader2 className="text-blue-500 animate-spin" size={48} />
                   </div>
                 )}
                 <div id="scanner-region" className="w-full h-full"></div>
                 <div className="absolute inset-0 border-[40px] border-black/40 pointer-events-none">
                    <div className="w-full h-full border-2 border-blue-500/50 rounded-lg"></div>
                 </div>
              </div>
              <p className="text-white/40 text-[10px] font-black uppercase tracking-widest mt-8 text-center px-12 leading-relaxed">
                Enmarque el código de barras dentro del visor azul para añadir automáticamente.
              </p>
           </div>
        </div>
      )}
    </div>
  );
};

