import React, { useState, useMemo, useEffect, useRef } from 'react';
import { dbService } from '../services/dbService';
import { Product, Client, SaleItem, SaleStatus, Sale } from '../types';
import { ShoppingCart, Search, User, Trash2, Plus, Minus, CreditCard, Wallet, ScanLine, UserPlus, Loader2, X, ChevronDown, Camera, Check } from 'lucide-react';
import { Html5Qrcode } from "html5-qrcode";

const SalesView: React.FC = () => {
  const [products, setProducts] = useState<Product[]>([]);
  const [clients, setClients] = useState<Client[]>([]);
  const [cart, setCart] = useState<SaleItem[]>([]);
  const [selectedClient, setSelectedClient] = useState<Client | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [clientSearch, setClientSearch] = useState('');
  const [saleStatus, setSaleStatus] = useState<SaleStatus>(SaleStatus.COMPLETED);
  const [amountPaid, setAmountPaid] = useState<string>('');
  const [isCartVisible, setIsCartVisible] = useState(false);
  const [isScannerOpen, setIsScannerOpen] = useState(false);
  const [scannerLoading, setScannerLoading] = useState(false);
  const [processing, setProcessing] = useState(false);

  const scannerRef = useRef<Html5Qrcode | null>(null);
  const lastProcessedRef = useRef<number>(0);

  useEffect(() => {
    const loadData = async () => {
      try {
        const [p, c] = await Promise.all([dbService.getProducts(), dbService.getClients()]);
        setProducts(p);
        setClients(c);
      } catch (err) {
        console.error("Error loading sales data:", err);
      }
    };
    loadData();
    return () => {
      if (scannerRef.current) {
        scannerRef.current.stop().catch(() => {});
      }
    };
  }, []);

  const addToCart = (product: Product) => {
    const now = Date.now();
    if (now - lastProcessedRef.current < 300) return; // Debounce scan
    lastProcessedRef.current = now;

    if (product.stock <= 0) {
      alert(`¡Sin stock de ${product.name}!`);
      return;
    }

    setCart(prev => {
      const existing = prev.find(item => item.productId === product.id);
      if (existing) {
        if (existing.quantity >= product.stock) {
          alert("Límite de stock alcanzado");
          return prev;
        }
        return prev.map(item => item.productId === product.id ? { ...item, quantity: item.quantity + 1 } : item);
      }
      return [...prev, { productId: product.id, name: product.name, price: product.price, quantity: 1 }];
    });
    setSearchTerm('');
    if (navigator.vibrate) navigator.vibrate(50);
  };

  const updateQuantity = (productId: string, delta: number) => {
    setCart(prev => prev.map(item => {
      if (item.productId === productId) {
        const product = products.find(p => p.id === productId);
        const newQty = Math.max(0, item.quantity + delta);
        if (product && newQty > product.stock) {
          alert("Stock máximo alcanzado");
          return item;
        }
        return { ...item, quantity: newQty };
      }
      return item;
    }).filter(item => item.quantity > 0));
  };

  const startScanner = async () => {
    setIsScannerOpen(true);
    setScannerLoading(true);
    try {
      const scanner = new Html5Qrcode("scanner-region");
      scannerRef.current = scanner;
      await scanner.start(
        { facingMode: "environment" },
        { fps: 10, qrbox: { width: 250, height: 180 } },
        (decodedText) => {
          const product = products.find(p => p.barcode === decodedText);
          if (product) {
            addToCart(product);
            stopScanner();
          }
        },
        () => {}
      );
      setScannerLoading(false);
    } catch (err) {
      console.error(err);
      alert("No se pudo acceder a la cámara. Verifique los permisos.");
      setIsScannerOpen(false);
    }
  };

  const stopScanner = () => {
    if (scannerRef.current) {
      scannerRef.current.stop().then(() => {
        setIsScannerOpen(false);
        scannerRef.current = null;
      }).catch(console.error);
    } else {
      setIsScannerOpen(false);
    }
  };

  const filteredProducts = useMemo(() => {
    if (!searchTerm || searchTerm.length < 1) return [];
    return products.filter(p => 
      p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
      (p.barcode && p.barcode.includes(searchTerm))
    ).slice(0, 5);
  }, [products, searchTerm]);

  const filteredClients = useMemo(() => {
    if (!clientSearch) return [];
    return clients.filter(c => c.name.toLowerCase().includes(clientSearch.toLowerCase())).slice(0, 4);
  }, [clients, clientSearch]);

  const total = useMemo(() => cart.reduce((acc, item) => acc + (item.price * item.quantity), 0), [cart]);

  const handleProcessSale = async () => {
    if (cart.length === 0 || processing) return;
    if (saleStatus === SaleStatus.CREDIT && !selectedClient) {
      alert('Por favor, seleccione un cliente para ventas a crédito.');
      return;
    }

    setProcessing(true);
    const sale: Partial<Sale> = {
      id: crypto.randomUUID(),
      clientId: selectedClient?.id,
      items: cart,
      total,
      date: new Date().toISOString(),
      status: saleStatus,
      amountPaid: saleStatus === SaleStatus.CREDIT ? Number(amountPaid || 0) : total
    };

    try {
      await dbService.createSale(sale);
      setCart([]);
      setSelectedClient(null);
      setAmountPaid('');
      setClientSearch('');
      setIsCartVisible(false);
      const updatedProducts = await dbService.getProducts();
      setProducts(updatedProducts);
      alert('¡Venta realizada con éxito!');
    } catch (err) {
      console.error(err);
      alert("Error al procesar la venta.");
    } finally {
      setProcessing(false);
    }
  };

  return (
    <div className="h-full flex flex-col lg:flex-row gap-6 animate-in fade-in pb-20 lg:pb-0">
      <div className="flex-1 flex flex-col space-y-4 lg:space-y-6">

        {/* Terminal de Búsqueda */}
        <div className="bg-white p-5 lg:p-7 rounded-[2.5rem] border border-slate-200 shadow-sm space-y-4">
          <div className="flex items-center justify-between px-2">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] flex items-center gap-2">
              <ScanLine size={16} className="text-blue-500" /> Terminal de Ventas
            </h3>
            <button 
              onClick={startScanner}
              className="lg:hidden p-3 bg-blue-600 text-white rounded-2xl shadow-lg flex items-center gap-2 font-black text-[10px] uppercase tracking-widest active:scale-95 transition-all"
            >
              <Camera size={18} /> Escanear
            </button>
          </div>
          <div className="relative">
            <Search className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-300" size={24} />
            <input 
              type="text" 
              placeholder="Escribe nombre o código del producto..." 
              className="w-full pl-16 pr-4 py-5 lg:py-6 bg-slate-50 border border-slate-200 rounded-3xl outline-none text-base lg:text-xl font-black transition-all focus:bg-white focus:ring-4 focus:ring-blue-50 shadow-inner"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
            {filteredProducts.length > 0 && (
              <div className="absolute top-full left-0 right-0 mt-3 bg-white border border-slate-200 rounded-[2rem] shadow-2xl z-[80] overflow-hidden animate-in slide-in-from-top-2 duration-200">
                {filteredProducts.map(p => (
                  <button key={p.id} onClick={() => addToCart(p)} className="w-full p-5 flex items-center justify-between hover:bg-blue-50 transition-all text-left border-b border-slate-50 last:border-0 group">
                    <div className="flex flex-col">
                      <span className="font-black text-slate-800 group-hover:text-blue-600">{p.name}</span>
                      <span className="text-[10px] font-black uppercase text-slate-400">Existencia: {p.stock} uds</span>
                    </div>
                    <div className="text-right">
                      <p className="font-black text-blue-600 text-lg">${p.price.toLocaleString()}</p>
                      <p className="text-[9px] font-bold text-emerald-500 uppercase">Añadir +</p>
                    </div>
                  </button>
                ))}
              </div>
            )}
          </div>
        </div>

        {/* Selector de Cliente */}
        <div className="bg-white p-5 lg:p-7 rounded-[2.5rem] border border-slate-200 shadow-sm space-y-4">
           <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] px-2">Cliente / Receptor</h3>
           <div className="relative">
             <User className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-300" size={20} />
             <input 
               type="text" 
               placeholder="Venta de contado (Escriba para buscar cliente)" 
               className="w-full pl-14 pr-4 py-4 bg-slate-50 border border-slate-200 rounded-2xl outline-none font-bold text-slate-700"
               value={selectedClient ? selectedClient.name : clientSearch}
               onChange={(e) => {
                 setClientSearch(e.target.value);
                 if (selectedClient) setSelectedClient(null);
               }}
             />
             {selectedClient && (
               <button onClick={() => { setSelectedClient(null); setClientSearch(''); }} className="absolute right-4 top-1/2 -translate-y-1/2 p-2 text-rose-500"><X size={18}/></button>
             )}
             {filteredClients.length > 0 && !selectedClient && (
               <div className="absolute top-full left-0 right-0 mt-2 bg-white border border-slate-200 rounded-2xl shadow-xl z-[70] overflow-hidden">
                 {filteredClients.map(c => (
                   <button key={c.id} onClick={() => { setSelectedClient(c); setClientSearch(''); }} className="w-full p-4 flex items-center justify-between hover:bg-slate-50 transition-all border-b last:border-0">
                      <span className="font-bold text-slate-800">{c.name}</span>
                      <span className="text-[10px] font-black text-blue-600 uppercase">Seleccionar</span>
                   </button>
                 ))}
               </div>
             )}
           </div>
        </div>

        {/* Carrito en Móvil (Visible solo si hay items) */}
        {cart.length > 0 && (
          <button 
            onClick={() => setIsCartVisible(true)}
            className="lg:hidden fixed bottom-20 right-6 w-16 h-16 bg-blue-600 text-white rounded-full shadow-2xl flex items-center justify-center z-[90] animate-bounce-short"
          >
            <div className="relative">
              <ShoppingCart size={24} />
              <span className="absolute -top-3 -right-3 bg-rose-500 text-white text-[10px] font-black w-6 h-6 rounded-full flex items-center justify-center border-2 border-white">{cart.length}</span>
            </div>
          </button>
        )}
      </div>

      {/* Panel de Resumen (Derecha / Modal en móvil) */}
      <div className={`fixed lg:static inset-0 z-[100] lg:z-0 lg:w-96 transform transition-transform duration-300 flex flex-col ${isCartVisible ? 'translate-y-0' : 'translate-y-full lg:translate-y-0'}`}>
        <div className="absolute inset-0 bg-slate-900/40 lg:hidden" onClick={() => setIsCartVisible(false)} />
        <div className="relative bg-white lg:bg-slate-900 h-[90vh] lg:h-full mt-auto lg:mt-0 rounded-t-[3rem] lg:rounded-[3rem] shadow-2xl flex flex-col lg:p-8 p-6 overflow-hidden">

          <div className="flex items-center justify-between mb-8">
            <h3 className="text-xl font-black text-slate-800 lg:text-white uppercase tracking-tighter flex items-center gap-2">
               <ShoppingCart size={24} className="text-blue-500" /> Tu Carrito
            </h3>
            <button onClick={() => setIsCartVisible(false)} className="lg:hidden p-2 text-slate-400"><X size={28}/></button>
          </div>

          <div className="flex-1 overflow-y-auto hide-scrollbar space-y-4 mb-6">
            {cart.map(item => (
              <div key={item.productId} className="bg-slate-50 lg:bg-white/5 p-4 rounded-3xl border border-slate-100 lg:border-white/10 flex items-center justify-between">
                <div className="flex-1 min-w-0 pr-4">
                  <p className="font-black text-slate-800 lg:text-white truncate text-sm">{item.name}</p>
                  <p className="text-xs font-bold text-slate-400">${item.price.toLocaleString()}</p>
                </div>
                <div className="flex items-center gap-3">
                  <button onClick={() => updateQuantity(item.productId, -1)} className="w-8 h-8 rounded-xl bg-white lg:bg-white/10 flex items-center justify-center text-slate-400 hover:text-rose-500 transition-colors shadow-sm"><Minus size={14}/></button>
                  <span className="font-black text-slate-800 lg:text-white w-6 text-center">{item.quantity}</span>
                  <button onClick={() => updateQuantity(item.productId, 1)} className="w-8 h-8 rounded-xl bg-white lg:bg-white/10 flex items-center justify-center text-slate-400 hover:text-blue-500 transition-colors shadow-sm"><Plus size={14}/></button>
                </div>
              </div>
            ))}
            {cart.length === 0 && (
              <div className="h-full flex flex-col items-center justify-center text-slate-400 opacity-50 space-y-4 py-20">
                <ShoppingCart size={64} strokeWidth={1} />
                <p className="text-[10px] font-black uppercase tracking-widest text-center">El carrito está vacío</p>
              </div>
            )}
          </div>

          <div className="space-y-4 pt-6 border-t border-slate-100 lg:border-white/10">
            {/* Método de Pago */}
            <div className="flex gap-2">
              <button 
                onClick={() => setSaleStatus(SaleStatus.COMPLETED)}
                className={`flex-1 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all flex items-center justify-center gap-2 border-2 ${saleStatus === SaleStatus.COMPLETED ? 'bg-blue-600 border-blue-600 text-white' : 'bg-transparent border-slate-200 lg:border-white/10 text-slate-400'}`}
              >
                <Wallet size={16}/> Contado
              </button>
              <button 
                onClick={() => setSaleStatus(SaleStatus.CREDIT)}
                className={`flex-1 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all flex items-center justify-center gap-2 border-2 ${saleStatus === SaleStatus.CREDIT ? 'bg-amber-500 border-amber-500 text-white' : 'bg-transparent border-slate-200 lg:border-white/10 text-slate-400'}`}
              >
                <CreditCard size={16}/> Crédito
              </button>
            </div>

            {saleStatus === SaleStatus.CREDIT && (
              <div className="animate-in slide-in-from-top-2 duration-300">
                <input 
                  type="number" 
                  placeholder="Monto abonado hoy..." 
                  className="w-full px-5 py-4 bg-slate-50 lg:bg-white/5 border border-slate-200 lg:border-white/10 rounded-2xl outline-none font-black text-slate-800 lg:text-white"
                  value={amountPaid}
                  onChange={(e) => setAmountPaid(e.target.value)}
                />
              </div>
            )}

            <div className="flex items-center justify-between text-slate-800 lg:text-white px-2">
              <span className="text-[10px] font-black uppercase tracking-widest opacity-50">Total a Pagar</span>
              <span className="text-3xl font-black tracking-tighter">${total.toLocaleString()}</span>
            </div>

            <button 
              onClick={handleProcessSale}
              disabled={cart.length === 0 || processing}
              className="w-full bg-blue-600 hover:bg-blue-700 disabled:bg-slate-200 lg:disabled:bg-white/10 text-white py-5 rounded-3xl font-black text-lg shadow-xl shadow-blue-100 lg:shadow-none flex items-center justify-center gap-3 transition-all active:scale-95 uppercase tracking-widest"
            >
              {processing ? <Loader2 className="animate-spin" size={24} /> : (
                <><Check size={24} /> Finalizar Venta</>
              )}
            </button>
          </div>
        </div>
      </div>

      {/* Modal de Escáner */}
      {isScannerOpen && (
        <div className="fixed inset-0 z-[200] flex flex-col bg-slate-900/95 animate-in fade-in duration-300">
           <div className="flex items-center justify-between p-8 text-white">
              <h4 className="font-black text-xs uppercase tracking-[0.2em] flex items-center gap-3">
                <Camera className="text-blue-500" /> Escáner de Óptico
              </h4>
              <button onClick={stopScanner} className="p-4 bg-white/10 rounded-[2rem] hover:bg-white/20 transition-all"><X size={24}/></button>
           </div>
           <div className="flex-1 flex flex-col items-center justify-center p-6">
              <div className="relative w-full max-w-sm aspect-[4/3] bg-black rounded-[3rem] border-4 border-white/10 overflow-hidden shadow-2xl">
                 {scannerLoading && (
                   <div className="absolute inset-0 flex items-center justify-center z-10 bg-black/60 backdrop-blur-sm">
                     <Loader2 className="text-blue-500 animate-spin" size={48} />
                   </div>
                 )}
                 <div id="scanner-region" className="w-full h-full"></div>
                 {/* Guía Visual */}
                 <div className="absolute inset-0 pointer-events-none flex items-center justify-center">
                    <div className="w-64 h-32 border-2 border-blue-500/60 rounded-2xl relative">
                       <div className="absolute top-0 left-0 w-8 h-8 border-t-4 border-l-4 border-blue-500 -mt-1 -ml-1 rounded-tl-lg"></div>
                       <div className="absolute top-0 right-0 w-8 h-8 border-t-4 border-r-4 border-blue-500 -mt-1 -mr-1 rounded-tr-lg"></div>
                       <div className="absolute bottom-0 left-0 w-8 h-8 border-b-4 border-l-4 border-blue-500 -mb-1 -ml-1 rounded-bl-lg"></div>
                       <div className="absolute bottom-0 right-0 w-8 h-8 border-b-4 border-r-4 border-blue-500 -mb-1 -mr-1 rounded-br-lg"></div>
                    </div>
                 </div>
              </div>
              <p className="text-white/40 text-[10px] font-black uppercase tracking-[0.3em] mt-12 text-center px-12 leading-relaxed">
                Alinee el código de barras dentro del marco para detección instantánea.
              </p>
           </div>
        </div>
      )}
    </div>
  );
};

export default SalesView;

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { dbService } from '../services/dbService';
import { Product } from '../types';
import { Plus, Search, Edit2, Trash2, Camera, Package, RefreshCw, Loader2, Calculator, X, AlertTriangle, ChevronDown, Barcode, Download, ArrowUpRight } from 'lucide-react';
import JsBarcode from 'jsbarcode';

const InventoryView: React.FC = () => {
  const [products, setProducts] = useState<Product[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isReplenishOpen, setIsReplenishOpen] = useState(false);
  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
  const [isBarcodeModalOpen, setIsBarcodeModalOpen] = useState(false);
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);
  const [productToDelete, setProductToDelete] = useState<Product | null>(null);
  const [productForBarcode, setProductForBarcode] = useState<Product | null>(null);
  const [loading, setLoading] = useState(false);

  const [categoryInput, setCategoryInput] = useState('');
  const [showCategorySuggestions, setShowCategorySuggestions] = useState(false);
  const categoryRef = useRef<HTMLDivElement>(null);
  const barcodeRef = useRef<SVGSVGElement>(null);

  const [calcQty, setCalcQty] = useState<number>(0);
  const [calcUnitCost, setCalcUnitCost] = useState<number>(0);

  const fetchProducts = async () => {
    try {
      const data = await dbService.getProducts();
      setProducts(data);
    } catch (err) {
      console.error(err);
    }
  };

  useEffect(() => {
    fetchProducts();
    const handleClickOutside = (event: MouseEvent) => {
      if (categoryRef.current && !categoryRef.current.contains(event.target as Node)) {
        setShowCategorySuggestions(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  useEffect(() => {
    if (isBarcodeModalOpen && productForBarcode && barcodeRef.current) {
      JsBarcode(barcodeRef.current, productForBarcode.barcode || '000000000', {
        format: "CODE128",
        lineColor: "#000",
        width: 2,
        height: 100,
        displayValue: true,
        fontSize: 18,
        textMargin: 10
      });
    }
  }, [isBarcodeModalOpen, productForBarcode]);

  const filteredProducts = useMemo(() => {
    return products.filter(p => 
      p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
      (p.barcode && p.barcode.includes(searchTerm))
    );
  }, [products, searchTerm]);

  const downloadBarcode = () => {
    if (!barcodeRef.current) return;
    const svg = barcodeRef.current;
    const svgData = new XMLSerializer().serializeToString(svg);
    const canvas = document.createElement("canvas");
    const ctx = canvas.getContext("2d");
    const img = new Image();

    img.onload = () => {
      canvas.width = img.width + 40;
      canvas.height = img.height + 40;
      if (ctx) {
        ctx.fillStyle = "white";
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.drawImage(img, 20, 20);
        const pngUrl = canvas.toDataURL("image/png");
        const downloadLink = document.createElement("a");
        downloadLink.href = pngUrl;
        downloadLink.download = `barcode-${productForBarcode?.name || 'product'}.png`;
        document.body.appendChild(downloadLink);
        downloadLink.click();
        document.body.removeChild(downloadLink);
      }
    };
    img.src = "data:image/svg+xml;base64," + btoa(unescape(encodeURIComponent(svgData)));
  };

  const handleSaveProduct = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setLoading(true);
    const formData = new FormData(e.currentTarget);
    const isNew = !editingProduct;
    const productData: Partial<Product> = {
      id: editingProduct?.id || crypto.randomUUID(),
      name: formData.get('name') as string,
      barcode: (formData.get('barcode') as string) || '',
      category: categoryInput || 'General',
      price: Number(formData.get('price')),
      cost: Number(formData.get('cost')),
      stock: Number(formData.get('stock')),
    };
    try {
      await dbService.saveProduct(productData, isNew);
      await fetchProducts();
      setIsModalOpen(false);
      setEditingProduct(null);
    } catch (err) { 
      alert("Error al guardar el producto"); 
    } finally { 
      setLoading(false); 
    }
  };

  const handleReplenish = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!editingProduct) return;
    setLoading(true);
    try {
      await dbService.updateStockAndRecordExpense(editingProduct.id, calcQty, calcUnitCost, editingProduct.name);
      await fetchProducts();
      setIsReplenishOpen(false);
      setEditingProduct(null);
    } catch (err) { alert("Error al reponer"); }
    finally { setLoading(false); }
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500 pb-10">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-xl lg:text-3xl font-black text-slate-800 tracking-tight">Inventario</h1>
          <p className="text-xs lg:text-base text-slate-500 font-medium">Control táctico de productos y etiquetas.</p>
        </div>
        <button 
          onClick={() => { setEditingProduct(null); setCategoryInput('General'); setIsModalOpen(true); }}
          className="bg-blue-600 hover:bg-blue-700 text-white px-5 py-3 rounded-2xl font-black text-xs uppercase tracking-widest flex items-center justify-center gap-2 shadow-lg transition-all active:scale-95"
        >
          <Plus size={18} /> Nuevo Item
        </button>
      </div>

      <div className="relative">
        <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
        <input 
          type="text" 
          placeholder="Buscar por nombre o código..." 
          className="w-full pl-12 pr-4 py-4 bg-white border border-slate-200 rounded-2xl focus:ring-4 focus:ring-blue-50 transition-all font-medium shadow-sm outline-none"
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
        />
      </div>

      <div className="bg-white border border-slate-200 rounded-[2.5rem] overflow-hidden shadow-xl">
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-slate-50 text-slate-400 text-[10px] font-black uppercase tracking-[0.2em]">
                <th className="px-8 py-6">Producto</th>
                <th className="px-8 py-6">Precio</th>
                <th className="px-8 py-6 text-center">Stock</th>
                <th className="px-8 py-6 text-right">Acciones</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredProducts.map((p) => (
                <tr key={p.id} className="hover:bg-slate-50/50 transition-all group">
                  <td className="px-8 py-6">
                    <div className="flex flex-col">
                      <span className="font-black text-slate-800 text-base">{p.name}</span>
                      <span className="text-[10px] text-slate-400 font-black uppercase tracking-widest">{p.barcode || 'Manual'}</span>
                    </div>
                  </td>
                  <td className="px-8 py-6">
                    <span className="text-base font-black text-blue-600">${p.price.toLocaleString()}</span>
                  </td>
                  <td className="px-8 py-6 text-center">
                    <div className={`inline-block px-4 py-1 rounded-full text-[10px] font-black ${p.stock <= 5 ? 'bg-rose-100 text-rose-600' : 'bg-emerald-100 text-emerald-600'}`}>
                      {p.stock} UNIDADES
                    </div>
                  </td>
                  <td className="px-8 py-6">
                    <div className="flex items-center justify-end gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                      <button onClick={() => { setProductForBarcode(p); setIsBarcodeModalOpen(true); }} className="p-2 bg-slate-100 text-slate-600 rounded-xl hover:bg-slate-200"><Barcode size={18}/></button>
                      <button onClick={() => { setEditingProduct(p); setIsReplenishOpen(true); setCalcQty(0); setCalcUnitCost(p.cost); }} className="p-2 bg-emerald-50 text-emerald-600 rounded-xl hover:bg-emerald-100"><RefreshCw size={18}/></button>
                      <button onClick={() => { setEditingProduct(p); setCategoryInput(p.category || ''); setIsModalOpen(true); }} className="p-2 bg-blue-50 text-blue-600 rounded-xl hover:bg-blue-100"><Edit2 size={18}/></button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* Modal de Etiquetas */}
      {isBarcodeModalOpen && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-md" onClick={() => setIsBarcodeModalOpen(false)} />
          <div className="relative bg-white w-full max-w-sm rounded-[3rem] p-8 shadow-2xl text-center animate-in zoom-in-95 duration-200">
            <h3 className="text-xl font-black text-slate-800 mb-2 uppercase tracking-tight">Etiqueta de Barra</h3>
            <p className="text-xs text-slate-400 font-bold mb-6 truncate">{productForBarcode?.name}</p>
            <div className="bg-white p-6 rounded-3xl border border-slate-100 mb-8 flex justify-center">
               <svg ref={barcodeRef}></svg>
            </div>
            <div className="flex flex-col gap-3">
              <button onClick={downloadBarcode} className="w-full bg-slate-900 text-white py-4 rounded-2xl font-black text-sm flex items-center justify-center gap-2 shadow-xl active:scale-95 transition-all">
                <Download size={18} /> Descargar Imagen
              </button>
              <button onClick={() => setIsBarcodeModalOpen(false)} className="w-full bg-slate-100 text-slate-600 py-4 rounded-2xl font-black text-xs uppercase tracking-widest">Cerrar</button>
            </div>
          </div>
        </div>
      )}

      {/* Modal Principal Crear/Editar */}
      {isModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-end sm:items-center justify-center p-0 sm:p-4">
          <div className="absolute inset-0 bg-slate-900/40 backdrop-blur-sm" onClick={() => setIsModalOpen(false)} />
          <div className="relative bg-white w-full max-w-3xl h-[95vh] sm:h-auto rounded-t-[3rem] sm:rounded-[3rem] shadow-2xl overflow-hidden flex flex-col animate-in slide-in-from-bottom sm:zoom-in-95">
            <div className="px-8 py-6 border-b border-slate-100 flex items-center justify-between sticky top-0 bg-white">
              <h3 className="text-xl font-black text-slate-800 uppercase tracking-tighter">Ficha Técnica Item</h3>
              <button onClick={() => setIsModalOpen(false)} className="p-2 text-slate-400"><X size={28} /></button>
            </div>
            <form onSubmit={handleSaveProduct} className="p-8 lg:p-10 space-y-6 overflow-y-auto hide-scrollbar flex-1">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-4">
                  <div className="space-y-1">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Nombre</label>
                    <input name="name" defaultValue={editingProduct?.name} required className="w-full px-6 py-4 bg-slate-50 border border-slate-200 rounded-2xl outline-none font-black" />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Código Barra</label>
                    <input name="barcode" defaultValue={editingProduct?.barcode} className="w-full px-6 py-4 bg-slate-50 border border-slate-200 rounded-2xl outline-none font-bold" />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Stock</label>
                    <input name="stock" type="number" defaultValue={editingProduct?.stock || 0} required className="w-full px-6 py-4 bg-slate-50 border border-slate-200 rounded-2xl outline-none font-black" />
                  </div>
                </div>
                <div className="space-y-4 bg-blue-50/50 p-6 rounded-[2.5rem] border border-blue-100">
                  <div className="space-y-1">
                    <label className="text-[10px] font-black text-blue-600 uppercase tracking-widest ml-1">Precio Venta ($)</label>
                    <input name="price" type="number" step="0.01" defaultValue={editingProduct?.price} required className="w-full px-6 py-4 bg-white border border-blue-100 rounded-2xl outline-none font-black text-2xl text-blue-600" />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Costo Unitario ($)</label>
                    <input name="cost" type="number" step="0.01" defaultValue={editingProduct?.cost} required className="w-full px-6 py-4 bg-white border border-slate-200 rounded-2xl outline-none font-black" />
                  </div>
                  <div className="pt-2">
                    <p className="text-[9px] font-black text-slate-400 uppercase">Margen sugerido</p>
                    <p className="text-xl font-black text-emerald-500 tracking-tighter">+{editingProduct ? ((editingProduct.price - editingProduct.cost)/editingProduct.cost * 100).toFixed(0) : 0}%</p>
                  </div>
                </div>
              </div>
              <button disabled={loading} type="submit" className="w-full bg-slate-900 text-white py-6 rounded-2xl font-black text-lg shadow-xl active:scale-95 transition-all">
                {loading ? <Loader2 className="animate-spin" /> : 'Guardar Información'}
              </button>
            </form>
          </div>
        </div>
      )}

      {/* Modal Reponer Stock */}
      {isReplenishOpen && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-md" onClick={() => setIsReplenishOpen(false)} />
          <form onSubmit={handleReplenish} className="relative bg-white w-full max-w-md rounded-[3rem] p-8 shadow-2xl space-y-6 animate-in zoom-in-95 duration-200">
            <h3 className="text-xl font-black text-slate-800 uppercase tracking-tighter">Entrada de Mercancía</h3>
            <div className="space-y-4">
              <div className="space-y-1">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Cantidad a Añadir</label>
                <input type="number" required value={calcQty} onChange={(e) => setCalcQty(Number(e.target.value))} className="w-full px-6 py-4 bg-slate-50 border border-slate-200 rounded-2xl outline-none font-black text-xl" />
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Costo Unitario Compra ($)</label>
                <input type="number" step="0.01" required value={calcUnitCost} onChange={(e) => setCalcUnitCost(Number(e.target.value))} className="w-full px-6 py-4 bg-slate-50 border border-slate-200 rounded-2xl outline-none font-black text-xl" />
              </div>
              <div className="bg-slate-900 rounded-2xl p-5 text-white">
                 <p className="text-[8px] font-black uppercase opacity-50 tracking-widest mb-1">Total Inversión</p>
                 <p className="text-2xl font-black text-emerald-400">${(calcQty * calcUnitCost).toLocaleString()}</p>
              </div>
            </div>
            <button disabled={loading || calcQty <= 0} type="submit" className="w-full bg-blue-600 text-white py-5 rounded-2xl font-black text-lg shadow-xl active:scale-95 transition-all">
              {loading ? <Loader2 className="animate-spin" /> : 'Confirmar Entrada'}
            </button>
          </form>
        </div>
      )}
    </div>
  );
};

