              <span style="color: #10b981;">$${stats.profit.toLocaleString()}</span>
            </div>
            <div class="card">
              <label>Cuentas x Cobrar</label>
              <span style="color: #f59e0b;">$${stats.pending.toLocaleString()}</span>
            </div>
          </div>

          <h3>Desglose por Categorías</h3>
          <table>
