              <h2>Periodo: ${period.toUpperCase()}</h2>
              <p>Generado el ${dateStr}</p>
            </div>
          </div>
          <div class="grid">
            <div class="card"><label>Ingreso Bruto</label><span>$${stats.revenue.toLocaleString()}</span></div>
            <div class="card"><label>Gastos</label><span style="color: #ef4444;">$${stats.expenses.toLocaleString()}</span></div>
            <div class="card"><label>Utilidad Neta</label><span style="color: #10b981;">$${stats.profit.toLocaleString()}</span></div>
            <div class="card"><label>Por Cobrar</label><span style="color: #f59e0b;">$${stats.pending.toLocaleString()}</span></div>
          </div>
          <h3>Rendimiento por Categoría (Ordenado por Ganancia)</h3>
          <table>
            <thead><tr><th>Categoría</th><th style="text-align: right;">Unidades Vendidas</th><th style="text-align: right;">Ganancia Neta (Real)</th></tr></thead>
            <tbody>${categoryRows}</tbody>
          </table>
          <div class="footer">ESTE DOCUMENTO ES UN RESUMEN OPERATIVO GENERADO POR SISTEMA CAJA PRO.<br>TODOS LOS MONTOS EXPRESADOS EN USD ($)</div>
          <script>window.onload = () => { setTimeout(() => { window.print(); }, 500); };</script>
        </body>
      </html>
    `);
    printWindow.document.close();
  };

  const StatCard = ({ title, value, icon: Icon, iconColor, sub }: any) => (
    <div className="bg-white p-6 lg:p-8 rounded-[2rem] lg:rounded-[3rem] border border-slate-200 shadow-sm relative overflow-hidden group transition-all hover:border-blue-100 h-full">
