    [...categoryStats].sort((a, b) => b.profit - a.profit).slice(0, 5)
    .map(c => ({ name: c.name, value: Math.max(0, c.profit) })), 
  [categoryStats]);

  const unitsPieData = useMemo(() => 
    [...categoryStats].sort((a, b) => b.units - a.units).slice(0, 5)
    .map(c => ({ name: c.name, value: c.units })), 
