import { supabase } from '../supabaseClient';
import { Product, Client, Sale, Expense, SaleStatus } from '../types';

// Generador de UUID v4 estándar para evitar errores de tipo en PostgreSQL/Supabase
const generateUUID = () => {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    const r = Math.random() * 16 | 0, v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
};

export const dbService = {
  // Productos
  async getProducts(): Promise<Product[]> {
    const { data, error } = await supabase
      .from('products')
      .select('*')
      .order('name', { ascending: true });

    if (error) throw error;
    return (data || []).map(p => ({
      id: p.id,
      userId: p.user_id,
      name: p.name,
      price: p.price,
      cost: p.cost,
      stock: p.stock,
      barcode: p.barcode,
      category: p.category
    }));
  },

  async saveProduct(product: Partial<Product>, isNew: boolean = false) {
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) throw new Error("Sesión expirada");

    const productId = product.id || generateUUID();
    const currentStock = Number(product.stock) || 0;
    const currentCost = Number(product.cost) || 0;

    // 1. Si es edición, verificamos si aumentó el stock para registrar el gasto
    if (!isNew && product.id) {
      const { data: existing } = await supabase
        .from('products')
        .select('stock')
        .eq('id', product.id)
        .single();

      if (existing && currentStock > existing.stock && currentCost > 0) {
        const diff = currentStock - existing.stock;
        await this.saveExpense({
          description: `Ajuste Inventario (Edición): ${product.name} (+${diff} uds)`,
          amount: diff * currentCost,
          category: 'Reabastecimiento',
          date: new Date().toISOString()
        });
      }
    }

    // 2. Guardar o actualizar producto
    const productData = { 
      id: productId,
      name: product.name,
      price: Number(product.price),
      cost: currentCost,
      stock: currentStock,
      barcode: product.barcode || '',
      category: product.category || 'General',
      user_id: user.id 
    };

    const { error: productError } = await supabase.from('products').upsert(productData);
    if (productError) throw productError;

    // 3. Si es nuevo con stock inicial, registramos el gasto
    if (isNew && currentStock > 0 && currentCost > 0) {
      await this.saveExpense({
        description: `Inversión Inicial: ${product.name} (${currentStock} uds)`,
        amount: currentStock * currentCost,
        category: 'Reabastecimiento',
        date: new Date().toISOString()
      });
    }
  },

  async updateStockAndRecordExpense(productId: string, quantityToAdd: number, cost: number, productName: string) {
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) throw new Error("No autenticado");

    const { data: prod, error: fetchError } = await supabase
      .from('products')
      .select('stock')
      .eq('id', productId)
      .single();

    if (fetchError || !prod) throw new Error("Producto no encontrado");

    // Actualizar stock del producto
    const { error: updateError } = await supabase
      .from('products')
      .update({ 
        stock: prod.stock + quantityToAdd,
        cost: cost 
      })
      .eq('id', productId);

    if (updateError) throw updateError;

    // Registrar gasto como Reabastecimiento
    await this.saveExpense({
      description: `Reposición Stock: ${productName} (+${quantityToAdd} uds)`,
      amount: quantityToAdd * cost,
      category: 'Reabastecimiento',
      date: new Date().toISOString()
    });
  },

  async deleteProduct(id: string) {
    const { error } = await supabase.from('products').delete().eq('id', id);
    if (error) throw error;
  },

  // Clientes
  async getClients(): Promise<Client[]> {
    const { data, error } = await supabase.from('clients').select('*');
    if (error) throw error;
    return (data || []).map(c => ({
      id: c.id,
      userId: c.user_id,
      name: c.name,
      phone: c.phone || '',
      email: c.email || '',
      currentDebt: c.current_debt || 0
    }));
  },

  async saveClient(client: Partial<Client>): Promise<Client> {
    const { data: { user } } = await supabase.auth.getUser();
    const clientId = client.id || generateUUID();

    const { error, data } = await supabase
      .from('clients')
      .upsert({ 
        id: clientId,
        name: client.name,
        phone: client.phone || '',
        email: client.email || '',
        current_debt: client.currentDebt || 0,
        user_id: user?.id 
      })
      .select()
      .single();

    if (error) throw error;
    return {
      id: data.id,
      userId: data.user_id,
      name: data.name,
      phone: data.phone || '',
      email: data.email || '',
      currentDebt: data.current_debt || 0
    };
  },

  async deleteClient(id: string) {
    const { error } = await supabase.from('clients').delete().eq('id', id);
    if (error) throw error;
  },

  // Ventas
  async getSales(): Promise<Sale[]> {
    const { data, error } = await supabase.from('sales').select('*').order('date', { ascending: false });
    if (error) throw error;
    return (data || []).map(s => ({
      id: s.id,
      userId: s.user_id,
      clientId: s.client_id,
      items: s.items || [],
      total: s.total,
      date: s.date,
      status: s.status,
      amountPaid: s.amount_paid
    }));
  },

  async createSale(sale: Partial<Sale>) {
    const { data: { user } } = await supabase.auth.getUser();
    const saleId = sale.id || generateUUID();

    const { data: newSale, error: saleError } = await supabase
      .from('sales')
      .insert({
        id: saleId,
        user_id: user?.id,
        client_id: sale.clientId,
        total: sale.total,
        amount_paid: sale.amountPaid,
        status: sale.status,
        items: sale.items
      })
      .select().single();

    if (saleError) throw saleError;

    // Ajustar stock
    for (const item of sale.items || []) {
      const { data: prod } = await supabase.from('products').select('stock').eq('id', item.productId).single();
      if (prod) await supabase.from('products').update({ stock: prod.stock - item.quantity }).eq('id', item.productId);
    }

    // Ajustar deuda cliente
    if (sale.status === SaleStatus.CREDIT && sale.clientId) {
      const pending = (sale.total || 0) - (sale.amountPaid || 0);
      const { data: client } = await supabase.from('clients').select('current_debt').eq('id', sale.clientId).single();
      if (client) await supabase.from('clients').update({ current_debt: client.current_debt + pending }).eq('id', sale.clientId);
    }
    return newSale;
  },

  async deleteSale(saleId: string) {
    const { data: sale } = await supabase.from('sales').select('*').eq('id', saleId).single();
    if (!sale) return;

    for (const item of sale.items || []) {
      const { data: prod } = await supabase.from('products').select('stock').eq('id', item.productId).single();
      if (prod) await supabase.from('products').update({ stock: prod.stock + item.quantity }).eq('id', item.productId);
    }

    if (sale.status === SaleStatus.CREDIT && sale.client_id) {
      const pending = sale.total - sale.amount_paid;
      const { data: client } = await supabase.from('clients').select('current_debt').eq('id', sale.client_id).single();
      if (client) await supabase.from('clients').update({ current_debt: Math.max(0, client.current_debt - pending) }).eq('id', sale.client_id);
    }
    await supabase.from('sales').delete().eq('id', saleId);
  },

  // Egresos / Gastos
  async getExpenses(): Promise<Expense[]> {
    const { data, error } = await supabase.from('expenses').select('*').order('date', { ascending: false });
    if (error) throw error;
    return (data || []).map(e => ({
      id: e.id,
      userId: e.user_id,
      amount: e.amount,
      description: e.description,
      date: e.date,
      category: e.category || 'Otros'
    }));
  },

  async saveExpense(expense: Partial<Expense>) {
    const { data: { user }, error: authError } = await supabase.auth.getUser();
    if (authError || !user) throw new Error("Error de autenticación: Por favor inicia sesión.");

    const expenseId = expense.id || generateUUID();
    const expenseData = {
      id: expenseId,
      description: expense.description || 'Gasto sin descripción',
      amount: Number(expense.amount) || 0,
      category: expense.category || 'Otros',
      user_id: user.id,
      date: expense.date || new Date().toISOString()
    };

    // Usamos UPSERT para manejar creación y edición con la misma lógica
    const { error } = await supabase
      .from('expenses')
      .upsert(expenseData);

    if (error) {
      console.error("Error detallado en saveExpense:", error);
      throw new Error(`Base de datos rechazó el gasto: ${error.message}`);
    }
  },

  async deleteExpense(id: string) {
    const { error } = await supabase.from('expenses').delete().eq('id', id);
    if (error) throw error;
  },

  async processDistributedAbono(clientId: string, totalAmount: number, saleIds: string[]) {
    const { data: sales, error: fetchError } = await supabase
      .from('sales')
      .select('*')
      .in('id', saleIds)
      .order('date', { ascending: true });

    if (fetchError) throw fetchError;

    let remainingPayment = totalAmount;
    for (const sale of sales) {
      if (remainingPayment <= 0) break;
      const pending = sale.total - sale.amount_paid;
      const paymentToApply = Math.min(remainingPayment, pending);
      const newAmountPaid = sale.amount_paid + paymentToApply;

      await supabase
        .from('sales')
        .update({
          amount_paid: newAmountPaid,
          status: newAmountPaid >= sale.total ? SaleStatus.COMPLETED : SaleStatus.CREDIT
        })
        .eq('id', sale.id);

      remainingPayment -= paymentToApply;
    }

    const { data: client } = await supabase.from('clients').select('current_debt').eq('id', clientId).single();
    if (client) {
      await supabase.from('clients').update({ current_debt: Math.max(0, client.current_debt - totalAmount) }).eq('id', clientId);
    }
  }
};

